INSERT INTO public.economics_cases
  (subsection, case_id, title, context, statements, answer_key, tactical_explanations, difficulty_level, sort_order, tier)
VALUES
( '2.1', 'CASE 2.1.01', 'Jonas budgets his allowance: bus pass or a game skin', 'Sixteen-year-old Jonas receives twelve euros pocket money each week from his parents. He needs a bus pass costing eight euros to get to school and back all week, and he also wants to buy a virtual skin for his favourite game for ten euros. He cannot afford both this week and has to make a choice about how to use his twelve euros. Evaluate the statements below using the book''s distinction between needs and wants.', ARRAY['The bus pass is a need for Jonas because he requires it to get to school, while the game skin is a want because it is not essential for his everyday life.', 'Because both the bus pass and the game skin cost money, the book classifies both of them equally as needs.', 'Since Jonas is only a teenager and not yet a full member of a household or a business, the concepts of needs and wants described in the book do not yet apply to him.', 'If Jonas simply decides to do nothing with his twelve euros this week, he has managed to opt out of making an economic decision.', 'Once Jonas buys the bus pass, his want for the game skin automatically disappears, because needs must always be satisfied before wants exist at all.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — The book distinguishes needs, which are necessary for a person''s well-being, from wants, which are desired but not essential; getting to school is a need, while a virtual game skin is a want.', 'FALSE — Having a price does not make something a need; the book''s distinction rests on whether something is necessary for well-being, not on whether money changes hands for it.', 'FALSE — The book treats individuals, not only adult members of a household or registered businesses, as having needs and wants and facing economic decisions once they use a scarce resource such as pocket money.', 'FALSE — The book stresses that nobody can opt out of making economic decisions; choosing to spend nothing and hold onto the money is itself a decision about how to use a scarce resource.', 'FALSE — The book does not claim a want disappears once a need is met; Jonas can still want the game skin even after buying the bus pass, he simply cannot afford both this week.'], '3/5', 1, 'full' ),
( '2.1', 'CASE 2.1.02', 'Herr Novak''s bakery: bread on the shelf, delivery to the door', 'Herr Novak runs a small bakery in Linz. Households in the neighbourhood buy his bread and pastries directly from the shop, and some elderly customers also pay an extra euro for him to deliver a loaf to their door each morning. Herr Novak is an entrepreneur running a business, while the people who buy from him are households. Evaluate the statements below.', ARRAY['In this scenario, Herr Novak represents the entrepreneur side of the economy described in the book, while his customers represent households.', 'The loaf of bread is a good, whereas the doorstep delivery is a service, matching the book''s distinction between tangible goods and intangible services.', 'Because Herr Novak is a business owner rather than a household, the book says he personally has no needs of his own.', 'The euro that customers pay for delivery is not really an exchange, since delivery itself has no monetary value according to the book.', 'Flour and oven fuel are unlimited for a small bakery, so Herr Novak never has to economise on his ingredients.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — The book identifies households and entrepreneurs as the two main parts of the economy interacting with one another, exactly as shown here.', 'TRUE — Bread is a tangible item and therefore a good, while delivery is an activity performed for the customer and therefore a service.', 'FALSE — The book states that individuals and businesses alike have needs; Herr Novak, as an entrepreneur, has needs of his own, such as needing suppliers and customers.', 'FALSE — Paying money for a service is exactly the kind of exchange the book describes; a service can be bought and sold just like a good.', 'FALSE — Flour and oven fuel are limited, purchasable resources; Herr Novak must economise on ingredients like any other business owner facing scarcity.'], '2/5', 2, 'full' ),
( '2.1', 'CASE 2.1.03', 'A theory vignette: what exactly is being bought at the corner café', 'Imagine a small corner café where customers buy a bag of roasted coffee beans to take home, and also pay for a barista to prepare a cappuccino they drink on the spot. Some customers say they only ''need'' their morning caffeine, while others admit the oat-milk latte is more of a treat. Use the book''s concepts of goods, services, needs and wants to assess the statements.', ARRAY['The bag of roasted beans is a good, since it is a tangible item the customer takes away, while the barista''s preparation of the cappuccino is a service.', 'According to the book, needs and wants are exactly the same thing, so there is no meaningful difference between craving caffeine and craving an oat-milk latte.', 'A customer who only ever buys coffee to satisfy a habitual craving is still exhibiting a want if that particular drink is not necessary for basic well-being.', 'Because the café is a business and not a household, it cannot itself be said to have needs, such as needing reliable coffee-bean suppliers.', 'By paying money for the beans or the cappuccino, customers and the café each fulfil needs or wants through exchange, as the book describes.'], ARRAY[true, false, true, false, true], ARRAY['TRUE — This matches the book''s distinction between a tangible good (the beans) and an intangible service (preparing and serving the drink).', 'FALSE — The book separates needs, which are necessary for well-being, from wants, which are desired but not essential; the two concepts are not identical.', 'TRUE — A habitual craving for a particular drink, rather than caffeine as such, is best described as a want, since it is not essential to basic well-being.', 'FALSE — The book states that businesses, like individuals, have needs; a café genuinely needs things such as reliable suppliers, staff and premises to operate.', 'TRUE — Exchange, as described in the book, is precisely how needs and wants on both sides of a transaction get fulfilled.'], '3/5', 3, 'full' ),
( '2.1', 'CASE 2.1.04', 'A carpenter''s workshop and a family''s new dining table', 'Petra and her family need a sturdier dining table after their old one collapsed. They commission carpenter Fabian to build one from oak, paying him 650 euros once it is delivered. Fabian, in turn, uses part of that money to buy more timber for his next commission. Assess the following statements about this exchange using the book''s concepts.', ARRAY['Petra''s family, as a household, and Fabian, as an entrepreneur, represent the two main groups the book identifies as parts of the economy.', 'The dining table is a good, since it is a tangible, physical item that Fabian produces and delivers to the family.', 'By paying Fabian 650 euros for the table, Petra''s family fulfils a need — a working dining table — through exchange, exactly as the book describes.', 'Fabian only needs money for himself and has no genuine need for timber, since timber is merely a want for a business.', 'Timber for Fabian''s workshop is a limited resource, so Fabian must economise on how much oak he uses for each commission.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — Households and entrepreneurs are the two main parts of the economy described in the book, and Petra''s family and Fabian fill exactly those roles.', 'TRUE — A physical, tangible item like a dining table matches the book''s definition of a good.', 'TRUE — The family''s need for a working table is fulfilled through the exchange of money for the finished product, as the book describes exchange.', 'FALSE — The book states that businesses genuinely have needs, such as needing raw materials like timber to keep operating; timber is not merely a want for Fabian.', 'TRUE — Timber is a limited, purchasable resource, so Fabian must economise on how much he uses per project rather than assume unlimited supply.'], '2/5', 4, 'full' ),
( '2.1', 'CASE 2.1.05', 'The Hoffmann household and the corner electrician: a full picture', 'The Hoffmann family calls in self-employed electrician Boris to fix a faulty wiring fault in their kitchen, paying him 180 euros for two hours of work. Boris himself is also a father who, that same evening, goes to the supermarket to buy groceries for his own family. Consider how each side of this everyday situation reflects the basic economic concepts from the book.', ARRAY['The Hoffmann family acts as a household when it pays Boris, while Boris acts as an entrepreneur when he supplies the repair.', 'Boris''s electrical repair is a service rather than a good, because it is an activity performed rather than a physical item handed over.', 'The Hoffmanns'' faulty wiring created a need for a working electrical system, which the exchange of money for Boris''s service then fulfilled.', 'Later that evening, when Boris buys groceries, he is acting as a household with needs of his own, showing that individuals and businesses both have needs.', 'Because Boris''s time and expertise are limited resources, he must economise by deciding how many repair jobs he can realistically take on in a day.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — This matches the book''s household/entrepreneur framing: the family pays for a service, and Boris supplies it as an entrepreneur.', 'TRUE — An activity performed for someone, rather than a physical item, is a service, exactly as the book defines it.', 'TRUE — The wiring fault created a genuine need, which was fulfilled through the exchange of money for Boris''s repair service.', 'TRUE — Boris, buying groceries as an individual, shows that people on the ''entrepreneur'' side of one transaction still have their own household needs elsewhere.', 'TRUE — Boris''s limited working hours and expertise are scarce resources, forcing him to economise by choosing how many jobs to accept.'], '3/5', 5, 'full' ),
( '2.1', 'CASE 2.1.06', 'Retiring off-grid: the Bauers try to leave the economy behind', 'After retiring, Mr and Mrs Bauer move to a small plot of land, grow their own vegetables, keep chickens, and repair their own furniture, hoping to ''step outside the economy'' entirely. They still occasionally sell surplus eggs to neighbours for a few euros. Their son argues that they have not really escaped economic life at all. Evaluate the statements.', ARRAY['By producing almost everything themselves, the Bauers have successfully opted out of making any economic decisions, exactly as they intended.', 'Even self-sufficient production requires the Bauers to economise, because their land, seeds, time and chicken feed remain limited resources relative to what they might want to do with them.', 'When the Bauers sell surplus eggs to neighbours, that transaction is an exchange fulfilling the neighbours'' need or want for eggs, just as the book describes exchange.', 'Because the Bauers are retired, the book would classify them as entrepreneurs rather than as a household.', 'Deciding how many chickens to keep versus how much land to use for vegetables is itself an economic decision the Bauers cannot avoid making.'], ARRAY[false, true, true, false, true], ARRAY['FALSE — The book insists nobody can opt out of making economic decisions; even self-sufficient living still requires ongoing choices about how to use scarce resources.', 'TRUE — Land, seeds, time and feed remain limited relative to the Bauers'' wants, so they must still economise, matching the book''s scarcity concept.', 'TRUE — Selling eggs for money is exactly the kind of exchange the book describes, fulfilling the neighbours'' need or want.', 'FALSE — Retirement status does not change the book''s household/entrepreneur classification; the Bauers remain a household consuming and producing for themselves, not an entrepreneur running a business for the market.', 'TRUE — Choosing how to split limited land and animals between competing uses is an economic decision the Bauers cannot avoid making.'], '4/5', 6, 'full' ),
( '2.1', 'CASE 2.1.07', 'Frau Keller''s grocery shop and the families on Ulmenstraße', 'Frau Keller owns a small grocery shop on Ulmenstraße. Families on the street buy milk, bread and vegetables from her every week, while she buys wholesale stock, pays rent, and pays her one part-time assistant a wage. Consider both sides of this everyday economic relationship.', ARRAY['The families on Ulmenstraße act as households, while Frau Keller''s shop represents the entrepreneur side of the economy described in the book.', 'Milk, bread and vegetables are goods because they are tangible items that the households take home and consume.', 'Because Frau Keller''s assistant is paid a wage rather than buying anything, the book says he is not truly a member of any household.', 'Frau Keller herself has needs as a business owner, such as needing reliable wholesale suppliers, which shows that entrepreneurs have needs just like individuals.', 'Because shelf space and her weekly budget are limited, Frau Keller must economise by choosing carefully which products to restock.'], ARRAY[true, true, false, true, true], ARRAY['TRUE — This is exactly the households/entrepreneurs split the book uses to describe the basic parts of the economy.', 'TRUE — Tangible items taken home and consumed are goods, matching the book''s definition.', 'FALSE — Being paid a wage does not remove someone from household membership; the book''s household/business distinction concerns roles in a transaction, not employment status.', 'TRUE — The book notes that entrepreneurs and businesses have needs too, such as needing reliable suppliers to keep operating.', 'TRUE — Limited shelf space and a fixed budget are scarce resources, so Frau Keller must economise when deciding what to restock.'], '3/5', 7, 'full' ),
( '2.1', 'CASE 2.1.08', 'Kaffee Ecke: beans, baristas, and a queue every morning', 'At Kaffee Ecke, owner Sami sells bags of specialty beans over the counter and also employs two baristas who prepare espresso drinks for customers queuing every morning. Some regulars say they truly need their coffee to function at work, while others simply enjoy trying a new seasonal flavour each month. Sami''s supply of a rare Ethiopian bean lot is limited to only forty kilograms this season.', ARRAY['Sami acts as an entrepreneur supplying goods and services, while his customers act as households satisfying needs and wants through their purchases.', 'The bag of beans sold over the counter is a good, while the barista''s preparation of an espresso is a service.', 'A regular who insists they ''need'' their coffee to function may in fact be describing a strong want rather than a true survival need, though the book leaves room for personal habit.', 'Trying a new seasonal flavour each month is best classified as a want, since it is not essential to a customer''s basic well-being.', 'Because the rare Ethiopian bean lot is limited to forty kilograms, Sami must economise by deciding how to allocate it across the season rather than assuming unlimited supply.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Sami supplies goods and services as an entrepreneur, while customers as households satisfy needs and wants, matching the book''s basic economic picture.', 'TRUE — A tangible bag of beans is a good; preparing a drink is an activity, and therefore a service.', 'TRUE — The book''s needs/wants distinction is about necessity for well-being, so a habitual craving is more accurately a strong want than a strict survival need.', 'TRUE — Trying a new flavour for enjoyment, rather than necessity, fits the book''s definition of a want.', 'TRUE — A fixed, limited batch of beans is a scarce resource that forces Sami to economise across the season.'], '3/5', 8, 'full' ),
( '2.1', 'CASE 2.1.09', 'Lukas and his end-of-month pocket money puzzle', 'University student Lukas receives 300 euros a month from his parents. He needs to spend 90 euros on public transport and basic toiletries, and he wants to buy a new pair of designer trainers for 140 euros. Evaluate the following statements about Lukas''s situation using the book''s concepts.', ARRAY['The 90 euros for transport and toiletries covers needs, while the 140 euros for trainers covers a want, following the book''s distinction.', 'Because Lukas receives money from his parents rather than earning it himself, he is not really part of the household side of the economy described in the book.', 'If Lukas buys the trainers, his need for transport disappears completely for the rest of the month.', 'Wanting the trainers is irrational and therefore falls outside the scope of economics as described in the book.', 'Since Lukas''s parents give him money every month, his 300 euros should be treated as an unlimited resource that never needs to be economised.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Transport and toiletries are necessary for daily life and are therefore needs, while the trainers are desired but not essential, making them a want.', 'FALSE — Receiving money from parents does not exclude Lukas from the household side of the economy; he remains an individual with needs and wants who makes economic decisions.', 'FALSE — Buying the trainers does not remove Lukas''s ongoing need for transport; that need continues regardless of other purchases made in the same month.', 'FALSE — The book does not exclude wants from economics for being non-essential; wants are a normal part of the needs/wants framework it describes.', 'FALSE — A fixed monthly sum remains a limited resource; Lukas must still economise, deciding how to allocate it between needs and wants.'], '3/5', 9, 'full' ),
( '2.1', 'CASE 2.1.10', 'Farmer Reinisch and the village''s weekly market stall', 'Farmer Reinisch grows potatoes and carrots on a fixed plot of eight hectares just outside the village. Every Saturday, households from the village buy his produce directly at a small market stall, paying him in cash. He has been considering whether to devote more of his limited land to carrots, which currently sell better than potatoes.', ARRAY['Farmer Reinisch functions as an entrepreneur in this scenario, while the village households represent the other main part of the economy described in the book.', 'Because farmland can, in theory, always be bought elsewhere, the eight hectares Reinisch already owns should not be treated as a scarce resource for him.', 'Potatoes and carrots are services rather than goods, since they must be prepared before a household can eat them.', 'Deciding how to split his eight hectares between potatoes and carrots is an economic decision that Reinisch cannot avoid making given his limited land.', 'Once households buy vegetables at the stall, the book says no genuine exchange has taken place because cash, unlike barter, is not a real economic transaction.'], ARRAY[true, false, false, true, false], ARRAY['TRUE — Reinisch supplies produce as an entrepreneur, while the village households are the other side of the economy described in the book.', 'FALSE — The theoretical availability of land elsewhere does not make Reinisch''s own eight hectares unlimited; his actual land is a fixed, scarce resource for his decisions.', 'FALSE — Potatoes and carrots are tangible physical items, so they are goods; needing preparation before eating does not turn a good into a service.', 'TRUE — With only eight fixed hectares, allocating land between crops is an unavoidable economic decision.', 'FALSE — Paying with cash is exactly the kind of exchange the book describes; it does not make the transaction any less genuine than barter.'], '2/5', 10, 'full' ),
( '2.1', 'CASE 2.1.11', 'In the economics classroom: defining ''the economy'' from scratch', 'During a first economics lesson, a teacher asks students to define ''the economy'' using only what they have read in their textbook. One student suggests it is simply ''shops and shopping'', while another argues it also includes people producing things at home. The class ends up listing several core building blocks the book uses to describe economic life.', ARRAY['According to the book, the economy consists essentially of households and entrepreneurs (businesses) interacting with one another.', 'The book distinguishes goods, which are tangible items, from services, which are intangible activities performed for someone.', 'Both households and businesses have needs, and exchange between them is one way those needs (and wants) get fulfilled.', 'Resources being scarce means that both individuals and businesses are forced to economise rather than assume they can have everything they might want.', 'The book states that nobody, whether a household or a business, can truly opt out of making economic decisions, since even inaction is itself a choice about scarce resources.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — This is precisely how the book frames the basic parts of the economy: households and entrepreneurs interacting.', 'TRUE — This matches the book''s core distinction between tangible goods and intangible services.', 'TRUE — The book states that individuals and businesses both have needs, and exchange is presented as a way of fulfilling them.', 'TRUE — Scarcity is the reason economising is necessary for both individuals and businesses, as the book explains.', 'TRUE — The book explicitly makes the point that economic decision-making cannot be avoided, even by doing nothing.'], '2/5', 11, 'full' ),
( '2.1', 'CASE 2.1.12', 'At the hair salon: is a haircut a good or a service?', 'Sabine visits her local hair salon every six weeks for a haircut, paying twenty-five euros each time. Her hairdresser, Timo, also sells small bottles of shampoo at the counter for clients who want to buy them. Evaluate the following claims about this everyday visit.', ARRAY['The haircut itself is a service, since it is an activity performed on Sabine rather than a physical item she takes home, unlike the shampoo bottle, which is a good.', 'Because Sabine pays money for the haircut just as she would for the shampoo, the book classifies both as goods.', 'Timo, as a self-employed hairdresser, has no needs of his own according to the book, since he is on the entrepreneur side of the economy.', 'Sabine''s need for a haircut is best described as a want that arises only because Timo persuades her to keep coming back.', 'Since Sabine repeats this exchange every six weeks, the book would say it stops counting as scarce resource use because it has become a routine habit.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — An activity performed on a person, rather than a physical item handed over, is a service; the shampoo, being a tangible item, is a good.', 'FALSE — Paying money does not determine whether something is a good or a service; the haircut remains a service regardless of payment.', 'FALSE — Entrepreneurs and businesses have needs too, according to the book; being self-employed does not remove Timo''s own needs.', 'FALSE — This statement makes an unsupported causal claim about persuasion; the book does not attribute needs or wants to salesmanship, and the classification of haircuts as need or want does not depend on why Sabine keeps returning.', 'FALSE — Scarcity of time and resources does not disappear because a purchase is routine; economising still applies to each repeated decision.'], '4/5', 12, 'full' ),
( '2.1', 'CASE 2.1.13', 'The Sunday soup kitchen: charity without opting out of economics', 'Every Sunday, volunteers at a community centre cook and give away free soup to anyone who comes by, using donated vegetables and a kitchen lent for free by the church. One volunteer claims that because nothing is sold, the soup kitchen operates completely outside ''the economy'' described in textbooks. Assess the statements below.', ARRAY['Because the soup is given away for free, no need is being fulfilled and therefore no exchange, in the book''s sense, is taking place at all.', 'The volunteers must still economise, since donated vegetables, kitchen time and their own labour are limited resources relative to how many people they would like to feed.', 'Because money changes hands nowhere in this scenario, the volunteers and recipients have both fully opted out of making economic decisions.', 'Deciding which vegetables to use first, and how large a portion to serve each visitor, are economic decisions the volunteers cannot avoid making given limited supplies.', 'The church, by lending its kitchen for free, has no need of its own since it does not run a for-profit business.'], ARRAY[false, true, false, true, false], ARRAY['FALSE — Even though the soup is free, recipients'' need for food is still genuinely fulfilled; free provision does not mean no need is met.', 'TRUE — Donated vegetables, kitchen time and volunteer labour remain limited resources relative to how many people the volunteers would like to feed, so economising is still necessary.', 'FALSE — The absence of money does not mean people opt out of economic decisions; the book stresses nobody can escape making choices about how to use scarce resources.', 'TRUE — Deciding which vegetables to use and how large a portion to serve are unavoidable economic decisions given limited supplies.', 'FALSE — Not running a for-profit business does not mean the church has no needs; it can still need its kitchen back for other uses, showing that organisations, like individuals, have needs.'], '3/5', 13, 'full' ),
( '2.1', 'CASE 2.1.14', 'A barter deal: a handmade bookshelf for gardening lessons', 'Amateur carpenter Milan offers to build a bookshelf for his neighbour Greta, who happens to be a professional gardener. Instead of paying him in cash, Greta agrees to give Milan six gardening lessons in return. Neither euro banknotes nor a bank transfer are involved in this deal. Evaluate the statements about this direct exchange.', ARRAY['This barter arrangement still counts as an exchange in the book''s sense, because Milan and Greta each give something to fulfil a need or want of the other.', 'Because no money is used, the book would say Milan and Greta have opted out of the economic decisions involved in producing the bookshelf and the lessons.', 'The wood Milan uses for the bookshelf is a limited resource, so he still has to economise on how much of it he uses for this particular project.', 'Gardening lessons are a good rather than a service, because Greta demonstrates physical techniques using real plants and tools.', 'Both Milan and Greta have needs and wants of their own that this barter helps satisfy, which matches the book''s point that individuals, not only businesses, have needs.'], ARRAY[true, false, true, false, true], ARRAY['TRUE — Barter still counts as exchange since both sides give something to satisfy the other''s need or want, even without money involved.', 'FALSE — Using barter instead of money does not amount to opting out of economic decisions; both still had to decide how to use their limited time and materials.', 'TRUE — Wood is a limited resource, so Milan still has to economise on how much of it he uses.', 'FALSE — Gardening lessons are an activity performed by Greta, making them a service, not a good, despite using physical tools and plants.', 'TRUE — Individuals, not only businesses, have needs and wants that exchange can help satisfy, as the book notes.'], '3/5', 14, 'full' ),
( '2.1', 'CASE 2.1.15', 'Street music on the square: tips for a Sunday performance', 'Musician Elena busks every Sunday afternoon on the main square, playing violin for passers-by who drop coins and small notes into her open case. Some listeners say they simply enjoy the atmosphere, while Elena herself needs the income to help cover her rent. Assess the statements.', ARRAY['Elena''s performance is a service, since it is an activity enjoyed by listeners rather than a physical item handed over.', 'Listeners who drop money into Elena''s case because they enjoy the atmosphere are satisfying a want rather than a basic need.', 'Because the amount any single listener pays is not fixed in advance, this cannot be classified as an exchange according to the book.', 'Elena''s need to cover her rent shows that individuals, not just registered businesses, can be understood through the book''s concept of needs.', 'Elena''s available performing time each Sunday is a limited resource, so she must economise by choosing which square or time slot is likely to earn the most.'], ARRAY[true, true, false, true, true], ARRAY['TRUE — An activity enjoyed by listeners, rather than a tangible item, matches the book''s definition of a service.', 'TRUE — Enjoying atmosphere is not essential to survival or basic well-being, so it fits the book''s definition of a want.', 'FALSE — A variable or voluntary payment amount does not disqualify a transaction from being an exchange; money is still given in return for the performance.', 'TRUE — The book''s point that individuals have needs applies to Elena just as much as it applies to registered businesses.', 'TRUE — Elena''s limited performing time is a scarce resource, requiring her to economise on where and when she plays.'], '3/5', 15, 'full' ),
( '2.1', 'CASE 2.1.16', 'Swapping novels for algebra help between classmates', 'Classmates Nora and Felix agree to swap: Nora lends Felix a stack of five novels she has already read, and in return Felix spends two afternoons helping her prepare for an algebra test. No money is exchanged between them at any point. Evaluate the statements about this classmate arrangement.', ARRAY['According to the book, an exchange can only take place if money is used, so this novels-for-tutoring swap does not count as an exchange at all.', 'Felix''s tutoring is a service, while the novels Nora lends him are goods, matching the book''s distinction between the two.', 'Because Nora and Felix are both students rather than businesses, the concepts of needs, wants and exchange from the book do not really apply to them.', 'Felix''s limited free time on those two afternoons is a scarce resource that he has to allocate between tutoring Nora and his other commitments.', 'Once the swap is agreed, both Nora and Felix have opted out of making any further economic decisions related to their time.'], ARRAY[false, true, false, true, false], ARRAY['FALSE — The book''s concept of exchange is not limited to monetary transactions; the novels-for-tutoring swap still fulfils needs and wants for both sides.', 'TRUE — Novels are tangible items and therefore goods; tutoring is an activity performed for someone and therefore a service.', 'FALSE — The book applies its concepts of needs, wants and exchange to individuals generally, not only to registered businesses.', 'TRUE — Felix''s free time is limited and must be allocated between tutoring Nora and his other commitments.', 'FALSE — Agreeing to the swap does not end economic decision-making; both still face ongoing choices about how to use their remaining time and resources.'], '3/5', 16, 'full' ),
( '2.1', 'CASE 2.1.17', 'PhoneFix Wien: cracked screens and spare parts', 'PhoneFix Wien is a small repair shop where technician Aylin replaces cracked phone screens for customers, using spare parts she orders from a supplier in limited monthly batches. Households bring in broken phones because they need a working device for daily life, while some customers also buy phone cases just because they like the design. Evaluate the statements.', ARRAY['Aylin''s screen-replacement work is a service, while the phone case sold at the counter is a good, following the book''s distinction.', 'Because Aylin runs a repair shop rather than a household, the book says her monthly batch of spare parts can never really run scarce.', 'A customer buying a phone case purely because they like the design is satisfying a want rather than a basic need.', 'Repairing a phone does not count as fulfilling a need, since phones themselves are luxury items outside the scope of the book''s concepts.', 'Because her monthly batch of spare parts is limited, Aylin must economise by deciding which repair jobs to prioritise when stock runs low.'], ARRAY[true, false, true, false, true], ARRAY['TRUE — Repair work is an activity performed on the phone, making it a service, while the phone case is a tangible item, making it a good.', 'FALSE — A monthly batch, by definition, is limited; the book would not describe such a fixed batch as never scarce.', 'TRUE — Buying a case for its design rather than out of necessity fits the book''s definition of a want.', 'FALSE — The book does not exclude phones from being needs; having a working device for daily communication can be a genuine need, and this claim misreads the book''s concept.', 'TRUE — A limited monthly batch of parts is a scarce resource, forcing Aylin to economise and prioritise among repair jobs.'], '2/5', 17, 'full' ),
( '2.1', 'CASE 2.1.18', 'The Cerny household plans September on a tight budget', 'The Cerny family has 1,400 euros left after rent for the rest of September. They need to spend 600 euros on groceries and school supplies for their two children, and they also want to book a 300-euro weekend trip to visit relatives. Assess the following statements.', ARRAY['Groceries and school supplies represent needs for the Cerny household, while the weekend trip represents a want, following the book''s distinction.', 'As a household, the Cerny family must economise its remaining 1,400 euros, since it is a limited resource relative to everything they might like to spend it on.', 'School supplies for the children still count as a need of the household as a whole, since the book treats the household, not just individual members, as the unit with needs.', 'Deciding whether to book the weekend trip this month is an economic decision the Cerny family cannot avoid making, since doing nothing is also a choice about their scarce budget.', 'If the family decides against the trip, their want for it will have been permanently and completely erased, according to the book.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Groceries and school supplies are necessary for daily life and schooling, making them needs, while the trip is desired but not essential, making it a want.', 'TRUE — A fixed remaining sum of money is a limited resource, requiring the household to economise on how it is spent.', 'TRUE — The book treats the household as the relevant unit with needs, so supplies bought for the children count as a household need.', 'TRUE — Choosing whether to book the trip, including choosing to postpone it, is itself an economic decision, since inaction is also a choice.', 'FALSE — The book does not claim a want is permanently erased once unmet; the family may still want the trip later, they simply cannot afford it this month.'], '3/5', 18, 'full' ),
( '2.1', 'CASE 2.1.19', 'Market day in Hallstatt: a full snapshot of everyday economics', 'On market day in a small Austrian village, cheese-maker Toni sells wheels of cheese from his stall, while his neighbour Rosa offers face-painting for children as a fun sideline. Visiting families buy cheese because they need groceries for the week, and some children get their faces painted purely for enjoyment. Toni only has thirty wheels of cheese left from this batch and none more until next week.', ARRAY['Toni and Rosa act as entrepreneurs at the market, while the visiting families represent the household side of the economy described in the book.', 'The wheel of cheese is a good, while Rosa''s face-painting is a service, matching the book''s distinction between tangible and intangible offerings.', 'Buying cheese for weekly groceries satisfies a need, while paying for face-painting satisfies more of a want.', 'By paying for cheese or face-painting, families and the two sellers each fulfil needs or wants through exchange, exactly as the book describes.', 'Because Toni has only thirty wheels of cheese left, he must economise by deciding how to allocate this limited stock among the families still queuing.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Toni and Rosa supply goods and services as entrepreneurs, while the families are households, matching the book''s basic framing.', 'TRUE — A tangible wheel of cheese is a good; face-painting, an activity performed on a customer, is a service.', 'TRUE — Weekly groceries are necessary for daily life, making cheese a need, while face-painting is enjoyable but not essential, making it a want.', 'TRUE — Exchange fulfilling needs and wants on both sides is exactly the mechanism the book describes.', 'TRUE — A limited remaining stock of cheese is a scarce resource, forcing Toni to economise on how he allocates it.'], '2/5', 19, 'full' ),
( '2.1', 'CASE 2.1.20', 'The self-declared hermit who insists he needs no one', 'A former office worker named Karl moves into a remote cabin, claiming he ''needs nobody'' and has left all economic decisions behind. He still occasionally trades firewood he has chopped for canned food from a passing hiker. Evaluate the statements about Karl''s claims.', ARRAY['Even Karl''s occasional firewood-for-canned-food trade with hikers is an exchange fulfilling needs, exactly as the book describes exchange between people.', 'Because Karl lives alone and avoids shops, the book would say he has genuinely opted out of making economic decisions.', 'Karl''s claim that he ''needs nobody'' proves that scarcity does not apply to him, since he has no household or business relationships.', 'Chopping firewood requires no economising on Karl''s part, since forests are described in the book as an unlimited resource.', 'According to the book, a person must be part of a registered business or an official household to be affected by needs, wants and scarcity at all.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Even an occasional trade fulfils needs through exchange, matching the book''s description of exchange between people.', 'FALSE — Living remotely does not remove the need to make economic decisions about scarce resources like firewood, food and time.', 'FALSE — Karl still faces scarcity of firewood, food and time; claiming to need nobody does not mean scarcity stops applying to him.', 'FALSE — Forests and accessible firewood are limited resources requiring effort and choice, contrary to being described as unlimited.', 'FALSE — The book applies needs, wants and scarcity to individuals generally, not only to those in registered businesses or officially recognised households.'], '4/5', 20, 'full' ),
( '2.2', 'CASE 2.2.01', 'Simon picks a Saturday job: car wash pay or volunteering', 'Sixteen-year-old Simon can either work a Saturday shift at the local car wash for 45 euros, or spend the day volunteering at an animal shelter, which pays nothing but which he finds rewarding. He can only do one activity this particular Saturday because both run at the same time. Evaluate the statements about opportunity cost.', ARRAY['If Simon chooses to volunteer at the shelter, the opportunity cost of that choice is the 45 euros he gives up from the car wash shift.', 'Because the car wash shift is his only paid option, Simon faces no real scarcity in deciding how to use his Saturday, since scarcity, according to the book, only concerns money.', 'Because volunteering brings Simon personal satisfaction, the book says satisfaction cancels out any opportunity cost that might otherwise exist.', 'Since Simon is only a teenager rather than a household or a firm, the book''s concept of scarce resources requiring allocation does not apply to his Saturday.', 'The opportunity cost of volunteering also includes the cost of the animal shelter''s dog food, since that is a resource Simon would be using.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Opportunity cost is the (financial) benefit of the next-best alternative given up; by volunteering, Simon forgoes the 45 euros from the car wash.', 'FALSE — Scarcity, as the book describes it, concerns limited resources generally, including time, not only money; Simon''s single Saturday remains a scarce resource regardless of pay.', 'FALSE — Personal satisfaction does not cancel out opportunity cost; the concept still applies to whichever option is not chosen, satisfaction or not.', 'FALSE — The book applies scarcity and economic decision-making to individuals as well as to households and firms; being a teenager does not exempt Simon.', 'FALSE — Opportunity cost concerns the benefit Simon personally gives up by not choosing the alternative, not a third party''s unrelated resource costs such as dog food.'], '3/5', 1, 'full' ),
( '2.2', 'CASE 2.2.02', 'Ana weighs her supermarket bakery job against her own market stall', 'Ana currently earns 1,900 euros a month working in a supermarket bakery. She is considering leaving to run her own cinnamon-roll stall at weekend markets, which she estimates could bring in 2,100 euros a month after costs, but she would lose her supermarket job security and paid holidays. She can only pursue one of the two paths at a time.', ARRAY['If Ana leaves her supermarket job to run the stall, the opportunity cost of that decision includes the 1,900 euros a month she gives up from her old job.', 'Because running the stall would bring in more money overall, the book says Ana''s decision to leave has no opportunity cost at all.', 'If Ana instead stays at the supermarket, the opportunity cost of staying is the 2,100 euros a month she could have earned from the stall, not the amount she keeps earning at the supermarket.', 'As a household deciding how to use her own labour, Ana does not really face scarcity, because she is only choosing between two jobs rather than allocating physical resources.', 'Since paid holidays and job security are not measured in euros, the book says they cannot be considered at all when identifying Ana''s opportunity cost.'], ARRAY[true, false, true, false, false], ARRAY['TRUE — Leaving means giving up her 1,900-euro monthly salary, the (financial) benefit of her next-best alternative.', 'FALSE — Every choice between two competing uses of limited time still has an opportunity cost; higher expected income from the stall does not make the forgone salary disappear as a concept.', 'TRUE — The opportunity cost of staying is what she gives up from the alternative — the stall''s potential 2,100 euros — not what she continues to receive from her current choice.', 'FALSE — Time and labour are themselves scarce resources; choosing between two jobs is exactly the kind of allocation problem the book describes, not an exception to it.', 'FALSE — The book''s definition centres on the financial benefit given up, but this does not mean non-financial factors like job security are declared irrelevant; the claim is too absolute.'], '3/5', 2, 'full' ),
( '2.2', 'CASE 2.2.03', 'The town council must choose: skate park or library renovation', 'The small town of Bergdorf has 90,000 euros available this year for one capital project. The council is deciding between building a new skate park, which younger residents have requested, or renovating the aging public library, which many older residents want repaired. The council cannot fund both projects this year with the available budget.', ARRAY['Bergdorf''s government, like households and firms, faces the basic economic problem of allocating scarce resources described in the book.', 'If the council builds the skate park, the opportunity cost of that decision is the benefit residents would have gained from the library renovation.', 'Because a town council can, in principle, raise taxes, the book says local government budgets are never really scarce in any given year.', 'The 90,000-euro budget is a limited resource this year, so the council''s decision between the two projects is an example of allocating scarce resources.', 'If the council chooses the library renovation, the opportunity cost of that decision is the total cost of both projects added together.'], ARRAY[true, true, false, true, false], ARRAY['TRUE — The book describes households, firms and governments as all facing the basic problem of allocating limited resources.', 'TRUE — Choosing the skate park means giving up the library renovation''s benefit, which is the opportunity cost of that decision.', 'FALSE — The ability to raise taxes in future does not make this year''s fixed 90,000-euro budget unlimited; within the year, it remains a scarce resource.', 'TRUE — A fixed budget being split between two competing projects is a direct example of allocating scarce resources.', 'FALSE — Opportunity cost is the benefit of the single next-best alternative given up, not the sum of both projects'' costs.'], '2/5', 3, 'full' ),
( '2.2', 'CASE 2.2.04', 'Handwerk GmbH must choose between two product lines', 'Handwerk GmbH has only enough oak timber this quarter to produce either a run of dining tables, expected to generate 40,000 euros in profit, or a run of bookshelves, expected to generate 28,000 euros in profit. The company''s saw and staff hours are also fully booked either way, so it genuinely cannot produce both runs from the same timber batch.', ARRAY['As a firm, Handwerk GmbH faces the same basic problem of allocating scarce resources that the book also describes for households and governments.', 'If Handwerk GmbH produces the dining tables, the opportunity cost of that decision is the 28,000 euros in profit it gives up from the bookshelves.', 'If Handwerk GmbH instead produces the bookshelves, the opportunity cost of that decision is the 40,000 euros in profit it gives up from the dining tables.', 'Because both product lines use the same timber batch, the book says Handwerk GmbH''s decision has no opportunity cost, since the timber is shared either way.', 'The limited oak timber this quarter forces Handwerk GmbH to economise by choosing the more profitable of the two product lines.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — Firms face the same scarce-resource allocation problem as households and governments, according to the book.', 'TRUE — Choosing tables means giving up the 28,000-euro profit that the bookshelves would have generated.', 'TRUE — Choosing bookshelves means giving up the 40,000-euro profit that the tables would have generated.', 'FALSE — Sharing the same limited timber batch is exactly why a choice, and therefore an opportunity cost, exists; it does not eliminate one.', 'TRUE — Limited timber forces the firm to economise by selecting the more profitable of the two product lines.'], '3/5', 4, 'full' ),
( '2.2', 'CASE 2.2.05', 'Scarcity everywhere: a household, a firm and a ministry, side by side', 'In the same week, the Weber household decides between a family holiday and repaying part of their car loan early, a mid-sized firm decides between hiring a new sales representative or upgrading its delivery vans, and the transport ministry decides between resurfacing a motorway or extending a regional railway line. Each of the three actors has a fixed budget and cannot fund both of its own options this year.', ARRAY['Households, firms and governments all face the basic economic problem of allocating limited resources among competing uses, as described in the book.', 'For the Weber household, the opportunity cost of the family holiday is the (financial) benefit of paying down the car loan early, which they give up instead.', 'For the firm, the opportunity cost of hiring the sales representative is the benefit it would have gained from upgrading its delivery vans instead.', 'For the transport ministry, the opportunity cost of resurfacing the motorway is the benefit residents would have gained from the railway extension instead.', 'In each of the three cases, the fixed budget available this year is the scarce resource that forces a choice between the two competing options.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — The book states households, firms and governments alike must allocate their scarce resources among competing uses.', 'TRUE — The holiday''s opportunity cost is the benefit of paying down the loan early, the next-best alternative given up.', 'TRUE — Hiring the representative gives up the benefit of upgrading the vans instead, which is the opportunity cost.', 'TRUE — Resurfacing the motorway gives up the benefit of the railway extension instead, which is the opportunity cost.', 'TRUE — In each case, a fixed budget is the scarce resource forcing a choice between two competing options.'], '3/5', 5, 'full' ),
( '2.2', 'CASE 2.2.06', 'Elif''s semester dilemma: tutoring gig or unpaid internship', 'University student Elif can either keep her part-time tutoring job, which pays 400 euros a month, or accept an unpaid internship at a local architecture firm that she believes will improve her career prospects. The internship and tutoring hours overlap, so she cannot do both this semester. Evaluate the statements about her opportunity cost.', ARRAY['If Elif accepts the unpaid internship, the opportunity cost of that decision is the 400 euros a month she gives up from tutoring.', 'Because the internship pays no salary at all, the book says Elif''s choice to intern has no opportunity cost, since nothing measurable is given up.', 'If Elif keeps tutoring instead, the opportunity cost of that decision is the improved career prospects and experience she gives up from the internship.', 'The opportunity cost of Elif''s decision must always be expressed only in euros, since the book allows no other way of describing what is given up.', 'Because Elif is a student rather than an employee of a firm, the book still treats her as an individual who allocates a scarce resource — her time — between tutoring and the internship.'], ARRAY[true, false, true, false, true], ARRAY['TRUE — Accepting the internship means giving up the 400-euro monthly tutoring income, the financial benefit of the next-best alternative.', 'FALSE — The absence of a salary from the internship does not remove opportunity cost; Elif still gives up her tutoring income, which is a real forgone financial benefit.', 'TRUE — Staying in tutoring means giving up the internship''s career benefits and experience, the next-best alternative''s benefit.', 'FALSE — The book allows opportunity cost to include non-financial benefits, even though it emphasises the ''(financial)'' benefit; it does not restrict description to euros only.', 'TRUE — Elif, as an individual, still allocates a scarce resource, her time, between the two options, regardless of her student status.'], '3/5', 6, 'full' ),
( '2.2', 'CASE 2.2.07', 'The Almeida family''s small garden: vegetables or flowers', 'The Almeida family has one 40-square-metre garden plot behind their house. They are debating whether to use the whole plot for growing vegetables, which they estimate would save them about 250 euros a year in grocery bills, or to use it for flowers, which they simply enjoy looking at but which save no money. They do not have enough space to do both at a meaningful scale.', ARRAY['The Almeida family''s 40 square metres of garden space is a limited resource that they must allocate between vegetables and flowers.', 'If the family plants flowers instead of vegetables, the opportunity cost of that decision is the roughly 250 euros a year in grocery savings they give up.', 'If the family plants vegetables instead, the opportunity cost is the enjoyment of a flower garden they give up, even though the book''s definition emphasises financial benefit.', 'Because flowers do not save the family any money, growing flowers can never be a rational choice according to the book''s concept of opportunity cost.', 'As a household, the Almeida family faces exactly the kind of resource-allocation problem the book describes for households, firms and governments alike.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — A fixed 40 square metres is a limited resource that must be split between two competing uses.', 'TRUE — Choosing flowers means giving up the roughly 250-euro grocery savings that vegetables would have provided.', 'TRUE — Choosing vegetables means giving up the enjoyment of a flower garden, even if that particular benefit is not purely financial.', 'FALSE — The book does not say a choice must save money to be rational; opportunity cost simply describes what is given up, it does not forbid non-financial preferences from guiding a decision.', 'TRUE — This is the same scarce-resource allocation problem the book applies to households, firms and governments.'], '3/5', 7, 'full' ),
( '2.2', 'CASE 2.2.08', 'Mateo decides between his salaried job and full-time freelancing', 'Software engineer Mateo currently earns 3,600 euros a month in a stable, salaried position at a mid-sized firm. A client has offered him a full-time freelance contract that Mateo estimates would bring in about 4,200 euros a month, but he would lose employer-paid health insurance and guaranteed income during quiet months. He can only pursue one path at a time.', ARRAY['Mateo''s situation reflects a household-level decision about how to allocate his own limited working time between two competing uses.', 'If Mateo takes the freelance contract, the opportunity cost of that decision is the 3,600 euros a month in salary he gives up, along with his employer-paid benefits.', 'If Mateo stays in his salaried job instead, the opportunity cost of that decision is the (potential) 4,200 euros a month he gives up from freelancing.', 'Because Mateo cannot do both jobs at once, his working hours function as a scarce resource that forces him to choose between the two alternatives.', 'The book''s definition of opportunity cost as the (financial) benefit of the next-best alternative given up applies directly to Mateo''s choice between these two income paths.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Mateo''s decision is an example of an individual allocating limited working time between two competing uses.', 'TRUE — Taking the freelance contract means giving up his 3,600-euro salary and its accompanying benefits, the next-best alternative''s benefit.', 'TRUE — Staying salaried means giving up the potential 4,200-euro freelance income, the next-best alternative''s benefit.', 'TRUE — His working hours are a scarce resource forcing a single choice between the two paths.', 'TRUE — The book''s exact definition of opportunity cost applies directly to comparing these two income paths.'], '2/5', 8, 'full' ),
( '2.2', 'CASE 2.2.09', 'A common misunderstanding about what opportunity cost really means', 'In a study group, a student named Robin claims that opportunity cost simply means ''the total money you did not choose, added up from every option you rejected.'' Another student, Sara, uses this definition to analyse a choice between a 500-euro washing machine and a 700-euro laptop, since she can only afford one this month. Evaluate the statements against the book''s actual definition.', ARRAY['If Sara buys the laptop, the opportunity cost of that choice is the (financial) benefit she gives up from the washing machine, not some combination of every possible purchase.', 'Robin''s definition matches the book exactly: opportunity cost is the sum of every rejected alternative''s cost.', 'Because Sara is choosing between only two items, the book says no genuine scarcity is involved, since scarcity only applies when there are many options.', 'If Sara buys the washing machine, the opportunity cost of that decision is 1,200 euros, the combined price of both items.', 'Opportunity cost, according to the book, refers to the price tag of the item actually purchased, not to any alternative that was given up.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Opportunity cost is the benefit of the single next-best alternative given up, here the washing machine, not a combination of all rejected options.', 'FALSE — The book defines opportunity cost as the (financial) benefit of the next-best alternative given up, not the sum of every rejected alternative''s cost, so Robin''s definition does not match.', 'FALSE — Scarcity applies whenever a limited resource, here Sara''s budget, must be allocated among competing uses, even with just two options.', 'FALSE — The opportunity cost of the washing machine is the 700-euro benefit given up from the laptop, not the combined 1,200-euro price of both items.', 'FALSE — Opportunity cost refers to the benefit of the alternative not chosen, not the price of the item actually bought.'], '4/5', 9, 'full' ),
( '2.2', 'CASE 2.2.10', 'City hall debates a new bus line versus new bike lanes', 'City hall in a mid-sized town has 500,000 euros earmarked this year for one transport improvement. Planners are weighing a new bus line connecting an outer suburb, expected to benefit commuters, against a network of protected bike lanes through the town centre. The budget is not enough to deliver both projects fully this year.', ARRAY['The city government, like a household or a firm, must allocate its limited 500,000-euro budget between the two competing transport projects.', 'If the government proceeds with the bus line, it faces no opportunity cost, because public projects are funded by taxation rather than by market prices.', 'Because both projects aim to improve transport, the book says they cannot be compared using the concept of opportunity cost at all.', 'If the government proceeds with the bike lanes instead, the opportunity cost of that decision is the benefit commuters would have gained from the new bus line.', 'Local governments are exempt from the basic economic problem of scarce resources described in the book, since public budgets are set by law rather than by markets.'], ARRAY[true, false, false, true, false], ARRAY['TRUE — The fixed 500,000-euro budget is the scarce resource allocated between the two projects.', 'FALSE — Being funded by taxation does not remove opportunity cost; choosing the bus line still means giving up the bike lanes'' benefit.', 'FALSE — The book applies opportunity cost precisely to compare alternative uses of the same limited resource, including similar transport projects.', 'TRUE — Choosing bike lanes means giving up the bus line''s benefit for commuters, the next-best alternative.', 'FALSE — Governments face the same basic problem of scarce resources as households and firms, according to the book, regardless of how their budgets are set.'], '2/5', 10, 'full' ),
( '2.2', 'CASE 2.2.11', 'A bike shop owner splits a Saturday between repairs and sales', 'Petr owns a small bicycle shop and works alone on Saturdays, his busiest day. He estimates that spending the whole day on repairs would earn him about 380 euros, while spending the whole day helping customers choose and buy new bicycles would earn him about 460 euros in commission and margin. He only has one Saturday and cannot do both fully.', ARRAY['Petr''s available Saturday hours are a scarce resource that he must allocate between repair work and sales, just as the book describes for firms and individuals.', 'If Petr spends the day on repairs, the opportunity cost of that decision is the 460 euros he gives up from focusing on sales instead.', 'If Petr spends the day on sales instead, the opportunity cost of that decision is the 380 euros he gives up from repairs.', 'Because Petr cannot perform both activities fully on the same Saturday, his choice illustrates the basic economic problem of allocating scarce resources.', 'The (financial) benefit of the next-best alternative given up, as defined in the book, is exactly what determines Petr''s opportunity cost in either case.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Petr''s limited Saturday hours are the scarce resource being allocated between repairs and sales.', 'TRUE — Choosing repairs means giving up the 460 euros that focusing on sales would have earned.', 'TRUE — Choosing sales means giving up the 380 euros that focusing on repairs would have earned.', 'TRUE — The inability to do both fully on the same day illustrates the basic problem of allocating scarce resources.', 'TRUE — The book''s exact definition of opportunity cost applies to Petr''s decision in either direction.'], '2/5', 11, 'full' ),
( '2.2', 'CASE 2.2.12', 'A wealthy heir claims opportunity cost does not apply to him', 'David inherits a large sum of money and claims that because he ''never has to worry about running out of cash,'' the concept of opportunity cost described in his economics textbook simply does not apply to how he spends his afternoons. He is deciding today between visiting a museum exhibition or meeting an old friend for lunch, since the two events overlap in time. Evaluate the statements.', ARRAY['If David chooses the museum exhibition, the opportunity cost of that decision is the (financial or non-financial) benefit he gives up from meeting his friend for lunch instead.', 'Because David has effectively unlimited money, the book says his time is also unlimited, so no opportunity cost can arise from his afternoon choice.', 'Opportunity cost, according to the book, only applies to people who must worry about running out of money, not to wealthy individuals.', 'Since David is not a registered business or a government body, the book''s concept of scarce resources and opportunity cost does not apply to his personal afternoon.', 'Because both the museum and the lunch cost roughly the same amount of money, the book says this particular choice involves no real opportunity cost.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Even with unlimited money, David''s time is limited, so choosing the museum still means giving up the benefit of lunch with his friend.', 'FALSE — Having unlimited money does not make time unlimited; time remains scarce, so opportunity cost still arises from the overlapping events.', 'FALSE — The book applies opportunity cost to any decision involving a scarce resource such as time, not only to people worried about running out of money.', 'FALSE — The book''s concepts of scarcity and opportunity cost apply to individuals and their personal decisions, not only to registered businesses or government bodies.', 'FALSE — Similar cost does not eliminate opportunity cost; the benefit given up, the other activity itself, is what defines it, regardless of price similarity.'], '4/5', 12, 'full' ),
( '2.2', 'CASE 2.2.13', 'Irrigation water: wheat fields or vegetable fields', 'During a dry summer, farmer Ilić has only enough irrigation water this month to fully water either his wheat fields or his vegetable fields, not both. He estimates the wheat would bring in 12,000 euros if fully irrigated, while the vegetables would bring in 15,500 euros if fully irrigated. Assess the statements about his decision.', ARRAY['Ilić''s limited irrigation water this month is a scarce resource that must be allocated between the wheat fields and the vegetable fields.', 'If Ilić irrigates the vegetable fields, the opportunity cost of that decision is 27,500 euros, the combined revenue of both fields.', 'Because Ilić is a farmer rather than a registered firm, the book says his production decisions do not involve any real opportunity cost.', 'If Ilić irrigates the wheat fields instead, the opportunity cost of that decision is the 15,500 euros in revenue he gives up from the vegetable fields.', 'Since both fields belong to the same farm, watering one instead of the other does not really count as allocating a scarce resource, according to the book.'], ARRAY[true, false, false, true, false], ARRAY['TRUE — The limited irrigation water this month is the scarce resource split between the two fields.', 'FALSE — The opportunity cost of irrigating the vegetables is the 12,000 euros given up from the wheat, not the combined revenue of both fields.', 'FALSE — Being a farmer does not exempt Ilić from facing opportunity cost; the book applies the concept to any decision-maker allocating scarce resources.', 'TRUE — Irrigating the wheat means giving up the 15,500 euros in revenue from the vegetables, the next-best alternative.', 'FALSE — Belonging to the same farm does not remove scarcity; the water is still a limited resource that must be allocated between the two uses.'], '3/5', 13, 'full' ),
( '2.2', 'CASE 2.2.14', 'Nina compares a design agency job to solo freelance contracts', 'Graphic designer Nina earns 2,700 euros a month as an employee at a design agency. A collection of freelance clients would likely pay her about 3,100 euros a month combined, but she would need to handle her own invoicing, taxes and slow-paying clients. She is deciding which path to pursue for the coming year.', ARRAY['If Nina becomes a freelancer, the opportunity cost of that decision is the 2,700 euros a month in salary she gives up from the agency job.', 'Because freelancing pays more in this scenario, the book says Nina''s decision to freelance carries no opportunity cost whatsoever.', 'If Nina stays at the agency instead, the opportunity cost of that decision is the (potential) 3,100 euros a month she gives up from freelancing.', 'The extra administrative work of invoicing and taxes should be added directly onto Nina''s salary figure to calculate her opportunity cost, according to the book.', 'Nina''s working time is a limited resource, so her decision reflects the basic economic problem of allocating scarce resources described in the book.'], ARRAY[true, false, true, false, true], ARRAY['TRUE — Becoming a freelancer means giving up the 2,700-euro monthly salary, the next-best alternative''s benefit.', 'FALSE — A higher expected income from freelancing does not eliminate opportunity cost; the forgone salary is still the opportunity cost of that choice.', 'TRUE — Staying at the agency means giving up the potential 3,100 euros from freelancing, the next-best alternative''s benefit.', 'FALSE — The book''s opportunity cost concept identifies the benefit of the next-best alternative; it does not instruct adding administrative burdens directly onto a salary figure.', 'TRUE — Nina''s working time is a limited resource, illustrating the basic problem of allocating scarce resources.'], '3/5', 14, 'full' ),
( '2.2', 'CASE 2.2.15', 'The Bergmanns save for one renovation this year: kitchen or bathroom', 'The Bergmann family has saved 18,000 euros for home improvements this year. A full kitchen renovation would cost the entire amount, and so would a full bathroom renovation; they cannot afford to do both this year. They estimate the kitchen renovation would add more resale value to their home than the bathroom renovation would.', ARRAY['The Bergmanns'' 18,000 euros in savings is a limited resource that must be allocated between the kitchen and the bathroom renovation.', 'If the family renovates the kitchen, the opportunity cost of that decision is the benefit they give up from renovating the bathroom instead.', 'If the family renovates the bathroom instead, the opportunity cost of that decision is the greater resale value they give up from the kitchen renovation.', 'Because both renovations cost exactly 18,000 euros, the book says neither option can have an opportunity cost, since the price is identical either way.', 'As a household, the Bergmanns face the same basic problem of allocating scarce resources between competing uses that the book also describes for firms and governments.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — The fixed 18,000 euros is the scarce resource allocated between the two renovations.', 'TRUE — Choosing the kitchen means giving up the bathroom renovation''s benefit, the next-best alternative.', 'TRUE — Choosing the bathroom means giving up the kitchen''s greater resale-value benefit, the next-best alternative.', 'FALSE — An identical price for both options does not remove opportunity cost; the benefit given up, whichever option is not chosen, still defines it.', 'TRUE — This is the same basic scarce-resource allocation problem the book applies across households, firms and governments.'], '2/5', 15, 'full' ),
( '2.2', 'CASE 2.2.16', 'A startup''s tight budget: one more developer or one marketer', 'A small startup has budget for exactly one new hire this quarter: either a software developer, expected to speed up product development, or a marketing specialist, expected to boost sales. The founders cannot afford both salaries with their current funding. Evaluate the statements.', ARRAY['The startup''s limited hiring budget this quarter is the scarce resource being allocated between the developer role and the marketing role.', 'If the founders hire the developer, the opportunity cost of that decision is the developer''s own annual salary.', 'Because the startup is newly founded, the book says it is exempt from the basic economic problem of allocating scarce resources that applies to older, established firms.', 'If the founders hire the marketing specialist instead, the opportunity cost of that decision is the benefit they give up from hiring the developer instead.', 'Since both roles are paid similar salaries, the book says this decision involves no meaningful opportunity cost either way.'], ARRAY[true, false, false, true, false], ARRAY['TRUE — The limited hiring budget is the scarce resource allocated between the two roles.', 'FALSE — The opportunity cost of hiring the developer is the benefit given up from the marketing hire, not the developer''s own salary.', 'FALSE — Newly founded firms face the same basic economic problem of allocating scarce resources as established firms, according to the book.', 'TRUE — Hiring the marketer means giving up the benefit of hiring the developer instead, the next-best alternative.', 'FALSE — Similar salaries do not eliminate opportunity cost; the benefit forgone from the unchosen role is what matters, not whether the costs are similar.'], '3/5', 16, 'full' ),
( '2.2', 'CASE 2.2.17', 'A retail chain picks between two possible new store locations', 'A regional retail chain has capital for exactly one new store this year. Location A, in a busy shopping district, is projected to generate 220,000 euros in annual profit; location B, in a growing suburb, is projected to generate 180,000 euros. The chain''s available capital this year is only enough to open one of the two stores.', ARRAY['The retail chain''s available capital this year is a scarce resource being allocated between location A and location B.', 'If the chain opens the store at location A, the opportunity cost of that decision is the 180,000 euros in projected profit it gives up from location B.', 'If the chain opens the store at location B instead, the opportunity cost of that decision is 400,000 euros, the combined profit of both locations.', 'Because the chain is a large firm rather than a small business, the book says its expansion decisions do not really involve scarce resources.', 'This decision illustrates the book''s basic economic problem: firms, like households and governments, must allocate limited resources among competing uses.'], ARRAY[true, true, false, false, true], ARRAY['TRUE — The chain''s limited capital this year is the scarce resource allocated between the two locations.', 'TRUE — Opening at location A means giving up the 180,000-euro projected profit from location B, the next-best alternative.', 'FALSE — The opportunity cost of opening at location B is the 220,000 euros given up from location A, not the combined profit of both locations.', 'FALSE — Firm size does not exempt a company from facing scarce resources; even large firms have limited capital for expansion in a given year.', 'TRUE — This decision illustrates the basic economic problem of allocating limited resources that the book applies to households, firms and governments alike.'], '3/5', 17, 'full' ),
( '2.2', 'CASE 2.2.18', 'A high schooler chooses between a weekend job and a sports academy', 'Seventeen-year-old Mila can either work Saturday mornings at a bookstore for 60 euros, or attend a competitive swimming academy that meets at the same time and costs nothing but takes up the same hours. She believes the academy could improve her chances of a sports scholarship later, though this benefit is not guaranteed in euros today.', ARRAY['Mila''s Saturday morning hours are a limited resource that she must allocate between the bookstore job and the swimming academy.', 'If Mila chooses the swimming academy, the opportunity cost of that decision is the 60 euros she gives up from the bookstore job.', 'If Mila chooses the bookstore job instead, the opportunity cost of that decision is the training time and potential scholarship benefit she gives up from the academy.', 'Because the potential scholarship benefit is uncertain, the book says it cannot count as any kind of opportunity cost at all.', 'Mila''s situation shows that individuals, not only firms and governments, face the basic economic problem of allocating scarce resources described in the book.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — Mila''s limited Saturday morning hours are the scarce resource split between the job and the academy.', 'TRUE — Choosing the academy means giving up the 60 euros she would have earned from the bookstore job.', 'TRUE — Choosing the job means giving up the training time and potential scholarship benefit from the academy, the next-best alternative.', 'FALSE — Uncertainty about a benefit does not remove it from being an opportunity cost; the book''s concept includes benefits given up even when their realisation is not guaranteed.', 'TRUE — Mila''s situation shows that individuals also face the basic economic problem of allocating scarce resources, not only firms and governments.'], '3/5', 18, 'full' ),
( '2.2', 'CASE 2.2.19', 'Three decisions, one lesson: scarcity and opportunity cost recap', 'To close a unit on basic economic concepts, a teacher presents three parallel decisions: a household choosing between saving and a new sofa, a firm choosing between two competing investment projects, and a government choosing between two competing infrastructure projects. In every case, the decision-maker has a fixed, limited amount of money available this year and cannot fund both options within that same actor''s decision.', ARRAY['In each of the three cases, resources are limited relative to the number of things the decision-maker would like to fund, which is why a choice has to be made.', 'The basic economic problem, according to the book, is that households, firms and governments alike must allocate their scarce resources among competing uses.', 'In each case, the opportunity cost of choosing one option is the (financial) benefit of the next-best alternative that is given up.', 'For the household, choosing the new sofa means the opportunity cost is the benefit of the money saved (and its future value) that is given up instead.', 'For the government, choosing one infrastructure project means the opportunity cost is the benefit residents would have gained from the other project instead.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — In each case, resources are limited relative to the decision-maker''s wants, which is precisely why a choice must be made.', 'TRUE — This matches the book''s statement of the basic economic problem for households, firms and governments.', 'TRUE — In each case, choosing one option means giving up the (financial) benefit of the next-best alternative.', 'TRUE — Choosing the sofa means giving up the benefit of the money saved instead, the next-best alternative.', 'TRUE — Choosing one infrastructure project means giving up the benefit residents would have gained from the other.'], '2/5', 19, 'full' ),
( '2.2', 'CASE 2.2.20', 'A misplaced claim: scarcity ''is only a government problem''', 'During a debate, a student named Tobias argues that ''scarce resources are only really a problem for governments, because only governments have to manage huge budgets for millions of people.'' He uses this claim to dismiss a classmate''s example about a family choosing between paying off debt early or funding a home extension. Evaluate the statements against the book''s actual position.', ARRAY['The family choosing between paying off debt early and funding a home extension faces exactly the same basic problem of allocating scarce resources that governments face, just on a smaller scale.', 'Tobias is correct: the book describes scarcity of resources as a problem exclusively affecting governments, not households or firms.', 'Because the family''s decision involves a smaller amount of money than a government budget, the book says no genuine opportunity cost is involved.', 'If the family pays off debt early, the opportunity cost of that decision only exists if the family is also a registered business.', 'According to the book, only decisions involving ''millions of people'' can be analysed using the concept of opportunity cost.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — The family faces the same basic problem of allocating scarce resources as governments, just at a smaller scale, exactly as the book describes for households.', 'FALSE — The book explicitly applies scarcity of resources to households and firms as well as governments, not exclusively to governments.', 'FALSE — The size of the amount involved does not determine whether opportunity cost applies; any decision between limited competing uses involves an opportunity cost.', 'FALSE — Opportunity cost applies to households making financial decisions, not only to registered businesses; the family''s debt decision has a genuine opportunity cost regardless.', 'FALSE — The book does not restrict opportunity cost to large-scale decisions; it applies the concept to households, firms and governments of any size.'], '4/5', 20, 'full' ),
( '2.3', 'CASE 2.3.01', 'An electric hatchback, a government bonus, and one household''s choice', 'Fatima Yilmaz is comparing whether to buy a new electric hatchback or keep her twelve-year-old petrol car for another two years. The government currently offers a purchase bonus for electric vehicles, which lowers the net price she would pay. Her decision depends only on her own monthly budget, the bonus, and how much she drives to work each day. Evaluate the statements using the book''s distinction between microeconomics and macroeconomics.', ARRAY['Fatima''s personal decision about which car to buy, even though a government bonus is involved, is a microeconomic decision because it concerns a single household''s choice.', 'Because a national government programme (the bonus) is involved, Fatima''s car purchase automatically becomes a macroeconomic issue rather than a microeconomic one.', 'Economics, according to the book, studies exactly this kind of decision: how households and businesses decide what to do with limited resources.', 'If, instead, the national statistics office reported how the electric car bonus changed the country''s total car sales and overall economic growth, that report would be a macroeconomic analysis.', 'Microeconomics and macroeconomics study identical questions, so there is no meaningful difference between analysing Fatima''s single decision and analysing the whole nation''s economy.'], ARRAY[true, false, true, true, false], ARRAY['TRUE — The book''s own electric-car-bonus example classifies a single household''s buying decision as microeconomics, since it concerns one economic unit, not the whole economy.', 'FALSE — The origin of a policy (a government bonus) does not reclassify an individual household''s own choice; what matters is the scope of what is being analysed, and here it is one household.', 'TRUE — The book defines economics as the study of how households and businesses decide what to do given limited resources, which is exactly Fatima''s situation.', 'TRUE — A report on total nationwide car sales and overall growth studies the economy as a whole, which the book classifies as macroeconomics.', 'FALSE — The book distinguishes microeconomics (individual households, businesses, markets) from macroeconomics (the whole economy: growth, unemployment, interest rates, price levels); they are not identical.'], '3/5', 1, 'full' ),
( '2.3', 'CASE 2.3.02', 'Freonia''s quarterly growth report: reading the whole economy at once', 'The National Statistics Office of Freonia releases a report each quarter showing the growth rate of the whole country''s economy, alongside the nationwide unemployment rate and the general level of interest rates set by the central bank. Analysts use this report to comment on how "the economy" is doing overall, not on any single household or firm. Evaluate the statements about micro- versus macroeconomics.', ARRAY['This report is a macroeconomic analysis because it studies the economy as a whole rather than one household or one business.', 'Economic growth, unemployment and interest rates are exactly the kinds of variables the book lists under macroeconomics.', 'If a single bakery instead studied only its own sales and staffing, that would count as microeconomics because it examines one specific business.', 'Economics as a science tries to explain and predict such phenomena — for example, why growth slows or unemployment rises — by building theories.', 'Both microeconomics and macroeconomics are branches of economics, which the book defines as the study of how households and businesses make decisions given limited resources.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Studying the whole economy rather than a single unit is precisely how the book defines macroeconomics.', 'TRUE — Growth, unemployment, interest rates and price levels/inflation are the macroeconomic topics the book names.', 'TRUE — A single business examining only its own operations is the book''s definition of a microeconomic matter.', 'TRUE — The book presents economics as a science because it builds theories to explain and predict such economic phenomena.', 'TRUE — Both branches sit under the book''s overall definition of economics, just applied at different levels (individual units versus the whole economy).'], '2/5', 2, 'full' ),
( '2.3', 'CASE 2.3.03', 'BrewPeak''s espresso price hike after a bean-cost shock', 'BrewPeak, a small coffee roastery in Porto run by Inês, decides to raise the price of its espresso blend after the cost of imported beans increased. Inês is only thinking about her own shop''s costs, her customers'' likely reactions, and her small team''s wages — not about the whole Portuguese economy. Evaluate the statements.', ARRAY['Because Inês''s decision affects prices, it must be classified as macroeconomics, since macroeconomics is defined as the study of prices in general.', 'Inês''s pricing decision concerns a single business reacting to its own costs, which the book classifies as microeconomics.', 'If enough small roasteries across the whole country raised prices, and the national statistics office reported a rising overall price level, that report would still be called microeconomics, since it started with individual businesses.', 'Economics, as defined in the book, only studies businesses like BrewPeak and ignores household decisions entirely.', 'Because human behaviour cannot be perfectly predicted, the book concludes economics fails to qualify as a science at all.'], ARRAY[false, true, false, false, false], ARRAY['FALSE — Macroeconomics is not simply "the study of prices"; it studies the whole economy (growth, unemployment, interest rates, general price levels), and a single firm''s price is a microeconomic matter regardless of the topic being ''price''.', 'TRUE — A single business reacting to its own costs is exactly the kind of decision the book assigns to microeconomics.', 'FALSE — Once the analysis moves to the whole economy''s general price level, the book classifies that as macroeconomics, even though it originated from many individual firms.', 'FALSE — The book''s definition of economics explicitly covers both household and business decisions, not businesses alone.', 'FALSE — The book still calls economics a science because it builds theories to explain and predict behaviour, even though human behaviour is not perfectly predictable.'], '4/5', 3, 'full' ),
( '2.3', 'CASE 2.3.04', 'Kelvinia''s central bank raises rates to cool nationwide inflation', 'The central bank of Kelvinia announces a nationwide increase in its key interest rate, aiming to slow down rising inflation across the whole country. News commentators note that the move will affect nearly every household''s mortgage and every business''s loan costs at once, not just one particular family or firm. Evaluate the statements.', ARRAY['A nationwide interest-rate decision aimed at nationwide inflation is a macroeconomic matter, since it concerns the whole economy rather than a single household or business.', 'Inflation and interest rates are among the macroeconomic topics the book lists, alongside economic growth and unemployment.', 'If, instead, only one household decided how much to save at its own bank given the new rate, that single household''s choice would be a microeconomic decision.', 'Because interest rates went up, this event automatically counts as microeconomics, since it directly changes individual mortgage payments for specific families.', 'Economics as a science tries to build theories that explain why central banks raise rates and predict the likely effects on inflation.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — A policy aimed at the whole economy''s inflation rate is macroeconomic, matching the book''s whole-economy scope for macroeconomics.', 'TRUE — The book explicitly names inflation and interest rates as macroeconomic topics.', 'TRUE — One household''s own savings decision, examined on its own, is the book''s example of a microeconomic matter.', 'FALSE — That individual effects trickle down to specific households does not reclassify a nationwide policy decision as microeconomics; the scope analysed (the whole economy) determines the classification.', 'TRUE — The book frames economics as a science that explains and predicts such phenomena through theories.'], '3/5', 4, 'full' ),
( '2.3', 'CASE 2.3.05', 'Elif''s weekly hours: tuition, rent, and one student''s budget', 'Elif is a first-year student deciding how many hours per week to work at a bookstore so she can cover tuition fees, rent and food while still having time to study. She is not trying to analyse the whole country''s job market — only her own weekly schedule and income. Evaluate the statements.', ARRAY['Elif''s personal budgeting decision is a microeconomic matter because it concerns one household (herself) allocating limited resources such as time and money.', 'Because Elif is a student rather than a company, her situation falls outside the book''s definition of economics, which only covers businesses.', 'If thousands of students nationwide changed their work hours and this shifted the overall national unemployment rate, that nationwide effect would still be classified as microeconomics because it originated from individual students.', 'Economics studies exactly this kind of situation: a household deciding what to do with limited resources such as time and income.', 'Since Elif''s decision does not involve government bonuses, it cannot be analysed using economic theory at all.'], ARRAY[true, false, false, true, false], ARRAY['TRUE — A single household allocating scarce time and money is the book''s textbook case of a microeconomic decision.', 'FALSE — The book''s definition of economics explicitly includes household decisions, not only business decisions.', 'FALSE — Once the effect is measured at the level of the whole country''s unemployment rate, the book classifies that as macroeconomics, regardless of where it originated.', 'TRUE — The book''s core definition of economics is the study of households and businesses deciding what to do with limited resources.', 'FALSE — Nothing in the book restricts economic theory to situations involving government bonuses; ordinary household choices are equally covered.'], '2/5', 5, 'full' ),
( '2.3', 'CASE 2.3.06', 'Bellamira''s Ministry of Labour publishes the national jobless rate', 'The Ministry of Labour of Bellamira publishes the national unemployment rate every month, along with figures on how fast the overall economy grew and how the general price level changed. Journalists use these figures to describe the health of "the economy" as a whole, without singling out any one company or family. Evaluate the statements.', ARRAY['Publishing the nationwide unemployment rate is a macroeconomic activity because it looks at the whole economy rather than a single business or household.', 'Growth, unemployment and the general price level are all macroeconomic variables named in the book.', 'Because the report is issued by a government ministry, it must be microeconomics, since only government bodies are studied under microeconomics.', 'If a single factory instead reported only how many of its own workers it laid off last month, that would be a microeconomic fact about one business.', 'The book treats economics as a science that forms theories to explain and predict such national-level patterns, for example why unemployment rises during a downturn.'], ARRAY[true, true, false, true, true], ARRAY['TRUE — Reporting on the whole economy''s unemployment matches the book''s scope for macroeconomics.', 'TRUE — Growth, unemployment and general price levels are exactly the macroeconomic variables the book lists.', 'FALSE — Classification depends on the scope of the analysis (a single unit versus the whole economy), not on which institution produces the report; ministries are not automatically ''microeconomics''.', 'TRUE — A single factory''s own layoffs is a fact about one business, which the book classifies as microeconomics.', 'TRUE — The book presents economics as a science that builds theories to explain and predict phenomena such as nationwide unemployment during downturns.'], '3/5', 6, 'full' ),
( '2.3', 'CASE 2.3.07', 'Scheduling cashiers for one Nordfrisch store in Bergendorf', 'Nordfrisch, a regional supermarket chain, is deciding how many cashiers to schedule for its store in Bergendorf next month, based only on that single store''s expected customer numbers and its own wage budget. The head office is not analysing the whole country''s retail sector in this particular decision. Evaluate the statements.', ARRAY['This staffing decision for one specific store is a microeconomic matter, since it concerns a single business allocating its limited resources.', 'Because Nordfrisch is a large chain with many stores nationwide, any decision it makes is automatically macroeconomic.', 'Microeconomics, unlike macroeconomics, does not study businesses at all — only households.', 'If the national statistics office instead studied total retail employment across every store in the whole country, that broader study would be macroeconomics.', 'Economics only qualifies as a science when it studies nationwide phenomena such as unemployment, never single-store decisions.'], ARRAY[true, false, false, true, false], ARRAY['TRUE — One store''s staffing decision, made by one business, is exactly the book''s example of a microeconomic decision.', 'FALSE — The size of the company does not determine the classification; this particular decision concerns only one store, so it remains microeconomics.', 'FALSE — The book''s definition of microeconomics explicitly includes business decisions, not only household decisions.', 'TRUE — Aggregating retail employment across the whole country shifts the analysis to the economy-wide level, which the book calls macroeconomics.', 'FALSE — Nothing in the book restricts ''science'' status to nationwide topics; microeconomic decisions are equally part of economics as a science.'], '3/5', 7, 'full' ),
( '2.3', 'CASE 2.3.08', 'Doverland''s consumer price index tracks the whole basket of goods', 'The statistical office of Doverland calculates a consumer price index that tracks how the general price level for a broad basket of goods and services has changed across the entire country over the past year. Economists use this index, together with growth and unemployment figures, to judge how the whole economy is performing. Evaluate the statements.', ARRAY['Tracking the general price level of the whole economy is a macroeconomic exercise, since it looks beyond any single household or business.', 'The book lists price levels and inflation among the topics macroeconomics studies, alongside growth, unemployment and interest rates.', 'If a single bakery instead only tracked how the price of its own bread changed over the year, that narrower question would be microeconomics.', 'Economics tries to explain and predict such patterns — for example why prices rise — by developing theories, which is part of why the book calls it a science.', 'Both this nationwide price index and a single household''s grocery budget are studied under economics, just at different levels: macro for the whole economy, micro for individual units.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — A whole-economy measure like a national price index matches the book''s definition of macroeconomics.', 'TRUE — Price levels and inflation are explicitly named as macroeconomic topics in the book.', 'TRUE — One bakery''s own price is a single-business matter, which the book classifies as microeconomics.', 'TRUE — The book''s description of economics as a science rests on exactly this ability to explain and predict such patterns via theories.', 'TRUE — Both examples fall under the book''s overall definition of economics, differing only in whether the unit of analysis is the whole economy (macro) or an individual unit (micro).'], '2/5', 8, 'full' ),
( '2.3', 'CASE 2.3.09', 'The Alvarez family: rent another year or take out a mortgage?', 'The Alvarez family is deciding whether to keep renting their flat in Seville or take out a mortgage to buy a similar-sized apartment nearby. Their decision depends only on their own savings, income and monthly budget, not on the housing market of the entire country. Evaluate the statements.', ARRAY['This is a microeconomic decision because it concerns a single household allocating its limited financial resources.', 'Because buying property involves large sums of money, any housing decision automatically counts as macroeconomics regardless of whose decision it is.', 'The book states that only businesses, not households, face the basic economic problem of limited resources.', 'If the central bank instead studied how nationwide mortgage borrowing affects the whole country''s interest rates, that would still be called microeconomics because it involves individual mortgages.', 'Since the Alvarez family already decided to rent last year, economics as a science cannot make any prediction about their future housing choices.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — One household weighing its own limited resources is the book''s clear example of a microeconomic decision.', 'FALSE — The size of the sum of money involved does not determine the classification; this remains one household''s own decision, so it stays microeconomics.', 'FALSE — The book states households, businesses and governments all face the basic problem of scarce resources, not businesses alone.', 'FALSE — A study of nationwide mortgage borrowing and its effect on the whole country''s interest rates concerns the economy as a whole, which the book classifies as macroeconomics.', 'FALSE — The book presents economic theories as tools that can still be used to explain and predict future behaviour; a past decision does not block this.'], '3/5', 9, 'full' ),
( '2.3', 'CASE 2.3.10', 'Riona''s inflation rate climbs to six percent', 'The government of Riona reports that the national inflation rate has climbed to six percent this year, meaning the general price level across the whole economy is rising faster than usual. Commentators discuss how this affects the overall economy, distinct from how it affects any single shop''s individual pricing choice. Evaluate the statements.', ARRAY['The nationwide inflation figure of six percent is a macroeconomic statistic because it reflects price changes across the whole economy.', 'Inflation is explicitly named in the book as one of the macroeconomic phenomena, together with growth, unemployment and interest rates.', 'If, instead, one grocery shop raised its own prices by six percent in response to its own higher costs, that shop''s decision would still be classified as macroeconomics because the same six percent figure is used.', 'The book treats economics as a science partly because it builds theories that try to explain rising inflation and predict its future path.', 'Because inflation is a difficult topic, the book classifies its study as neither microeconomics nor macroeconomics but a separate third branch of economics.'], ARRAY[true, true, false, true, false], ARRAY['TRUE — A whole-economy inflation figure matches the book''s definition of a macroeconomic statistic.', 'TRUE — Inflation is one of the macroeconomic topics the book explicitly names.', 'FALSE — Matching numerical values does not determine classification; one shop''s own pricing decision remains a microeconomic matter regardless of the percentage involved.', 'TRUE — The book frames economics as a science precisely because it develops theories to explain and predict phenomena like inflation.', 'FALSE — The book organises economics into microeconomics and macroeconomics; inflation is a macroeconomic topic, not a separate third branch.'], '3/5', 10, 'full' ),
( '2.3', 'CASE 2.3.11', 'VoltDrive weighs Coastville against Rivermouth for its next plant', 'VoltDrive, an electric-vehicle maker, is deciding whether to build its newest assembly plant in Coastville or Rivermouth, based on its own production costs, available land and its workforce needs. This is a decision made by one specific company about its own operations. Evaluate the statements.', ARRAY['VoltDrive''s plant-location choice is a microeconomic decision, since it concerns one business allocating its own limited resources.', 'The book''s definition of economics explicitly includes business decisions such as this one, alongside household decisions.', 'If the national government instead studied how factory investment across the whole country affects nationwide economic growth, that broader analysis would be macroeconomics.', 'Because VoltDrive makes electric cars, and electric cars are linked to a government bonus scheme, its plant decision must be classified as macroeconomics rather than microeconomics.', 'Economics as a science aims to build theories that can help explain why firms like VoltDrive choose one location over another.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — One firm''s own investment decision is the book''s example of a microeconomic matter.', 'TRUE — The book''s definition of economics covers business decisions as well as household decisions.', 'TRUE — A study of nationwide factory investment and its effect on overall growth concerns the whole economy, matching the book''s scope for macroeconomics.', 'FALSE — The product category or its links to unrelated policy schemes does not determine classification; the scope of this specific decision (one firm) keeps it microeconomics.', 'TRUE — The book frames economics as a science that builds theories to explain and predict decisions such as a firm''s location choice.'], '4/5', 11, 'full' ),
( '2.3', 'CASE 2.3.12', 'Halvoria slips into recession as nationwide unemployment climbs', 'Financial news reports that the country of Halvoria has entered a recession, with overall economic growth turning negative and unemployment rising across nearly every region. Analysts compare this national downturn to a single small shop that had to close because of one owner''s personal decisions. Evaluate the statements.', ARRAY['The reported recession, negative growth and rising nationwide unemployment describe a macroeconomic situation because they concern the whole economy.', 'The single shop''s closure, caused by one owner''s personal decisions, should also be classified as macroeconomics simply because it happened during a national recession.', 'The book claims that macroeconomics and microeconomics use completely different definitions of "economics," so the two fields do not actually belong to the same discipline.', 'Because unemployment is rising, the government''s earlier growth forecasts must have been generated without any economic theory, since theories always predict growth correctly.', 'Recessions only affect macroeconomics; individual households and businesses are not influenced at all during a national downturn.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Negative growth and rising unemployment across the whole economy match the book''s scope for macroeconomics.', 'FALSE — The surrounding national context does not reclassify one shop''s own closure; that decision, about a single business, remains microeconomics.', 'FALSE — Both branches share the book''s same underlying definition of economics (decisions given limited resources); they differ only in the scale analysed.', 'FALSE — The book never claims theories predict outcomes with perfect accuracy; imperfect forecasts do not mean no theory was used.', 'FALSE — Individual households and businesses are of course affected during a recession; the book''s classification concerns the scope of analysis, not whether smaller units feel any impact.'], '4/5', 12, 'full' ),
( '2.3', 'CASE 2.3.13', 'Professor Nkemelu''s lecture on economics as a predictive science', 'In an introductory lecture, Professor Nkemelu tells students that economics tries to explain why people and firms behave as they do, and to predict what might happen next, much as physics builds theories about falling objects. She adds that economic theories are built from observing real households and businesses making choices under scarcity. Evaluate the statements about economics as a science.', ARRAY['According to the book, economics counts as a science because it develops theories that explain and attempt to predict economic behaviour.', 'Economics, as described by Professor Nkemelu, studies how households and businesses decide what to do given their limited resources.', 'Because human beings are unpredictable, the book states that economic theories can never be tested against real-world data.', 'A theory that only applies to one specific household''s shopping trip would be an example of microeconomic theory, while a theory about a nationwide recession would be macroeconomic theory.', 'The book claims economic predictions are always exactly as reliable as predictions in physics, with no meaningful difference between the two sciences.'], ARRAY[true, true, false, true, false], ARRAY['TRUE — The book''s case for economics as a science rests on its ability to build theories that explain and predict behaviour.', 'TRUE — This matches the book''s basic definition of economics: households and businesses deciding what to do given scarce resources.', 'FALSE — The opposite is true: theories are compared with real observations and data, which is part of how economics functions as a science.', 'TRUE — A single household''s behaviour is microeconomic in scope, while a nationwide recession is macroeconomic in scope, matching the book''s distinction.', 'FALSE — The physics comparison is illustrative, not a claim of identical reliability; the book does not assert economics predicts as precisely as physics.'], '3/5', 13, 'full' ),
( '2.3', 'CASE 2.3.14', 'One juice bar''s mangoes: a small theory in action', 'In a seminar, students use a simple theory to predict what will happen to how many mangoes one juice bar buys each week if the wholesale price of mangoes suddenly rises. They deliberately avoid discussing anything about the country''s overall inflation rate or unemployment level in this exercise. Evaluate the statements.', ARRAY['Because the theory is applied to a single juice bar''s mango purchases, this exercise is an example of microeconomic analysis.', 'Predicting one juice bar''s reaction to a price change automatically becomes macroeconomics once a theory is used, since only macroeconomics relies on theories.', 'The book describes economics as a science partly because such theories are used to explain and predict how economic units respond to changes like a price rise.', 'Since the students avoided discussing inflation or unemployment, their exercise cannot be classified as economics at all under the book''s definition.', 'If the same wholesale mango price rise were studied for its effect on the country''s entire food price level, that would still be microeconomics because mangoes are a small, minor product.'], ARRAY[true, false, true, false, false], ARRAY['TRUE — Studying one juice bar''s own purchasing decision is exactly the book''s example of a microeconomic matter.', 'FALSE — Both microeconomics and macroeconomics use theories; using a theory does not by itself shift the analysis to macroeconomics.', 'TRUE — The book''s view of economics as a science rests on using theories to explain and predict responses like this one.', 'FALSE — The book''s definition of economics does not require discussion of inflation or unemployment; a household or firm''s decision under scarcity is economics regardless.', 'FALSE — Once the effect is measured at the level of the whole country''s food price level, the book classifies that as macroeconomics, regardless of how small the underlying product is.'], '3/5', 14, 'full' ),
( '2.3', 'CASE 2.3.15', 'Testing a theory: does the electric car bonus change buying behaviour?', 'A team of researchers builds a theory predicting that households will buy more electric cars once a government bonus lowers the net purchase price. They then check whether actual sales data from car dealerships confirms or contradicts this prediction. The researchers stress that their theory concerns individual households'' buying choices, not the country''s overall growth rate. Evaluate the statements.', ARRAY['Building a theory and then checking it against real sales data is exactly how the book describes economics functioning as a science.', 'Because the researchers'' theory concerns individual households deciding whether to buy a car, it belongs to microeconomics, matching the book''s own electric-car-bonus example.', 'If instead the researchers studied how the bonus scheme affected the whole country''s economic growth rate, that would shift the analysis into macroeconomics.', 'The book''s basic definition of economics — the study of how households and businesses decide what to do with limited resources — fits this household car-buying decision well.', 'A theory''s usefulness, according to the book''s view of economics as a science, partly depends on whether its predictions match what actually happens in reality.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Forming a theory and testing it against real data matches the book''s description of economics as a science.', 'TRUE — A single household''s buying decision is microeconomic in scope, matching the book''s own electric-car-bonus example.', 'TRUE — Once the analysis concerns the whole country''s growth rate, the book classifies that as macroeconomics.', 'TRUE — Fatima-style household car-buying decisions fit squarely within the book''s core definition of economics.', 'TRUE — The book ties economics'' status as a science to theories being checked against real-world outcomes.'], '2/5', 15, 'full' ),
( '2.3', 'CASE 2.3.16', 'The camera analogy: zooming into a household, zooming out to a nation', 'A classroom diagram compares economics to a camera that can zoom in on a single household buying groceries or zoom out to view the entire national economy''s growth, unemployment and price levels at once. The teacher uses this analogy to help students remember the difference between the two branches of economics. Evaluate the statements.', ARRAY['"Zooming in" on one household''s grocery decision corresponds to microeconomics, since it studies a single economic unit under scarcity.', '"Zooming out" to view nationwide growth, unemployment and price levels corresponds to macroeconomics, as the book defines it.', 'The camera analogy implies that microeconomics and macroeconomics study completely unrelated subjects with no shared foundation.', 'Economics as a whole, whether zoomed in or out, is described in the book as a science because it forms theories to explain and predict such decisions and patterns.', 'Because a camera cannot literally zoom into an economy, the book states this analogy proves economics is not a real science.'], ARRAY[true, true, false, true, false], ARRAY['TRUE — A single household''s decision matches the book''s definition of microeconomics.', 'TRUE — Growth, unemployment and price levels viewed for the whole country match the book''s definition of macroeconomics.', 'FALSE — Both branches share the same underlying discipline and foundation (scarcity and decisions about limited resources); they are related, not unrelated.', 'TRUE — The book calls economics a science at both levels because it builds theories that explain and predict outcomes.', 'FALSE — This is a non-sequitur; the literal limits of a teaching analogy have no bearing on the book''s actual position that economics is a science.'], '3/5', 16, 'full' ),
( '2.3', 'CASE 2.3.17', 'A rate cut theory and its economy-wide predictions', 'A macroeconomic theory predicts that when a central bank lowers its key interest rate across an entire country, borrowing becomes cheaper and total business investment and household spending tend to rise economy-wide. Economists compare this prediction with what actually happened in several countries after past rate cuts. Evaluate the statements.', ARRAY['This theory concerns economy-wide investment and spending, so it belongs to macroeconomics as defined in the book.', 'Interest rates are explicitly listed among the topics the book assigns to macroeconomics.', 'Comparing the theory''s prediction with what actually happened afterwards is consistent with the book''s description of economics as a science that explains and predicts.', 'If, instead, economists studied only how one single household changed its own savings after its personal bank changed its rate, that narrower study would be microeconomics.', 'Both this nationwide interest-rate theory and a single household''s savings decision fall under the book''s overall definition of economics: decisions made given limited resources, just analysed at different levels.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Economy-wide investment and spending match the book''s scope for macroeconomics.', 'TRUE — Interest rates are explicitly named among the book''s macroeconomic topics.', 'TRUE — Testing a theory''s prediction against real outcomes is exactly how the book describes economics working as a science.', 'TRUE — One household''s own savings decision is the book''s example of a microeconomic matter.', 'TRUE — Both examples share the book''s underlying definition of economics, differing only in the level analysed (whole economy versus one household).'], '2/5', 17, 'full' ),
( '2.3', 'CASE 2.3.18', 'A study-group debate: can economics really call itself a science?', 'A study group debates whether economics can really be called a science, since human beings sometimes act unpredictably, unlike planets following the laws of physics. One student argues that because people are unpredictable, economics should give up building theories altogether. Evaluate the statements.', ARRAY['The book still classifies economics as a science, even though human behaviour is less exactly predictable than physical phenomena, because it explains and predicts through theories.', 'The student''s suggestion matches the book''s own conclusion, which states that economics should stop building theories because people are unpredictable.', 'According to the book, only sciences whose predictions are always one hundred percent accurate deserve to be called a science.', 'Microeconomic theories, such as ones predicting a single household''s reaction to a price change, and macroeconomic theories, such as ones predicting nationwide unemployment, are both examples of the theories the book says economics builds.', 'Because the study group disagreed, the book leaves it entirely undecided whether economics is a science or not.'], ARRAY[true, false, false, true, false], ARRAY['TRUE — The book maintains that economics is a science because it forms theories that explain and predict, despite imperfect predictability of human behaviour.', 'FALSE — This is the opposite of the book''s position; the book does not conclude that theory-building should be abandoned.', 'FALSE — The book sets no such strict all-or-nothing accuracy requirement for something to be called a science.', 'TRUE — Theories exist at both the microeconomic level (single households/firms) and macroeconomic level (the whole economy), as the book describes.', 'FALSE — The book does take a clear position, treating economics as a science; a classroom disagreement does not change that.'], '4/5', 18, 'full' ),
( '2.3', 'CASE 2.3.19', 'One factory''s hiring versus a nation''s falling jobless rate', 'A research assistant is given two tasks: first, study why one specific toy factory''s monthly output changed after it hired ten new workers; second, study why the whole country''s unemployment rate fell over the past year. She keeps a clear separation between the two, using different types of data for each. Evaluate the statements.', ARRAY['The first task, about one specific factory''s output and hiring, is a microeconomic study because it concerns a single business.', 'The second task, about the whole country''s unemployment rate, is a macroeconomic study because it concerns the economy as a whole.', 'Both tasks fall under economics as the book defines it, since both involve decisions and outcomes tied to limited resources — labour in this case.', 'Because both tasks involve the same underlying resource, labour, the book says they must be classified under the same branch of economics, either both micro or both macro.', 'The research assistant''s approach reflects the book''s idea that economics is a science: she is trying to explain and potentially predict outcomes using observed data at two different levels.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — One factory''s own output and hiring is a single-business matter, matching the book''s definition of microeconomics.', 'TRUE — The whole country''s unemployment rate concerns the entire economy, matching the book''s definition of macroeconomics.', 'TRUE — Both tasks concern decisions about limited resources (labour), fitting the book''s overall definition of economics.', 'FALSE — Sharing the same type of resource does not determine classification; the scope of analysis (one firm versus the whole economy) does, so the two tasks belong to different branches.', 'TRUE — Using observed data to explain and potentially predict outcomes at two levels matches the book''s view of economics as a science.'], '4/5', 19, 'full' ),
( '2.3', 'CASE 2.3.20', 'A classroom disagreement about what ''economics'' actually covers', 'In a debate, one classmate claims that "economics" only means memorising government interest-rate announcements and has nothing to do with everyday choices such as students deciding how to spend their allowance. A second classmate, referencing the textbook, disagrees. Evaluate the statements.', ARRAY['The second classmate is correct: the book defines economics as the study of how households and businesses decide what to do given limited resources, which includes everyday choices like spending an allowance.', 'The first classmate is correct, since the book restricts the definition of economics strictly to government interest-rate decisions.', 'A student''s allowance-spending decision, being a household-level microeconomic matter, does not qualify as "real economics" according to the book, which reserves that term for macroeconomic topics only.', 'Because interest rates are a macroeconomic topic, the book excludes them from being explainable or predictable through economic theory.', 'The book states that microeconomics is merely a simplified nickname for macroeconomics, and the two terms describe the same thing.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — The book''s broad definition of economics covers everyday household choices, such as spending an allowance, not only government-level topics.', 'FALSE — The book''s definition is much broader than interest-rate announcements; it covers household and business decisions generally.', 'FALSE — Both microeconomic and macroeconomic topics count as "real economics" in the book; microeconomic matters are not excluded.', 'FALSE — Interest rates, as a macroeconomic topic, are exactly the kind of phenomenon economic theory tries to explain and predict.', 'FALSE — Microeconomics and macroeconomics are distinct branches studying different scopes (individual units versus the whole economy), not a nickname for one another.'], '4/5', 20, 'full' ),
( '2.4', 'CASE 2.4.01', 'Lucia''s bakery: wages out, bread and payments flowing back', 'Lucia runs a small bakery in Kraków. She pays wages every month to her two employees, Marek and Aga, who provide their labour by baking and serving customers. In return, the bakery sells fresh bread and pastries to local households, who pay for what they buy. Evaluate the statements using the book''s circular-flow model.', ARRAY['In this circular flow, Marek and Aga''s household side offers labour to the bakery and receives wages in return, matching the book''s model.', 'The bakery, as a business, also offers labour to households and receives wages in return, exactly like Marek and Aga do.', 'Because Lucia sells bread rather than paying wages, her bakery is not part of the circular flow described in the book.', 'Households, such as the local families buying bread, offer money payments to the bakery and receive goods and services in return, completing the circular flow the book describes.', 'The circular flow only works if the same people are simultaneously employees and customers of the same business, otherwise the model does not apply.'], ARRAY[true, false, false, true, false], ARRAY['TRUE — The book''s circular-flow model has households supplying labour to businesses and receiving wages in exchange.', 'FALSE — In the book''s model, businesses offer goods and services (not labour) and receive payments in return; labour and wages belong to the household side.', 'FALSE — Selling goods and services for payment is exactly the business side of the circular flow described in the book, not an exception to it.', 'TRUE — Households paying for goods and services and receiving them in return is the other half of the book''s circular-flow model.', 'FALSE — The model describes the economy-wide flow between households and businesses in general; it does not require the same individuals to be both employees and customers of one specific firm.'], '2/5', 1, 'full' ),
( '2.4', 'CASE 2.4.02', 'Sanne''s oranges and a Lisbon vendor who wants euros', 'At a Lisbon street market, a tourist named Sanne offers a bag of oranges to a vendor in exchange for a leather bag, since she has run out of euros. The vendor, who has no use for oranges, refuses and insists on being paid in cash instead. Evaluate the statements about money and barter.', ARRAY['The vendor''s refusal illustrates why the book describes barter as difficult: it requires a "double coincidence of wants," meaning each party must want exactly what the other offers.', 'Money solves this problem by acting as a medium of exchange that is generally accepted, unlike oranges which only some sellers might want.', 'If the vendor had accepted euros instead, those euros would also be functioning as a unit of account, since the leather bag''s price is expressed in a common currency unit.', 'Because the tourist offered a physical good instead of cash, her offer was actually a form of money, since the book defines money as anything physical that a buyer decides to offer.', 'This scene shows why the book states that without a widely accepted medium of exchange, everyday trade becomes far more complicated than using money.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — The book explains barter''s core difficulty as needing both sides to want exactly what the other has, which failed here.', 'TRUE — Money''s role as a generally accepted medium of exchange is precisely what avoids the double-coincidence problem barter creates.', 'TRUE — Expressing the bag''s price in euros is the unit-of-account function of money described in the book.', 'FALSE — The book defines money by its specific functions (medium of exchange, unit of account, store of value), not as "any physical good a buyer offers"; oranges do not become money simply by being offered.', 'TRUE — This matches the book''s point that barter is much more complicated than trade using a widely accepted medium of exchange.'], '3/5', 2, 'full' ),
( '2.4', 'CASE 2.4.03', 'The Kovač family''s decade-old jar of banknotes', 'The Kovač family has kept a jar of banknotes hidden at home for over a decade instead of spending it. During that time, prices in their country have kept rising every year. When they finally count the jar, they realise the same amount of money now buys noticeably fewer groceries than it did ten years earlier. Evaluate the statements.', ARRAY['This situation shows that money''s function as a store of value is weakened by inflation, since the same amount of money buys less over time.', 'Because the banknotes are still the same pieces of paper, their purchasing power must also have stayed exactly the same, according to the book.', 'The book claims that inflation only affects a currency''s role as a medium of exchange, never its role as a store of value.', 'Since the family kept cash rather than putting it in a bank, the book states this makes them personally responsible for causing national inflation.', 'The book recommends that households should always prefer to hold cash for ten years or more, since inflation has no real effect on stored money.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — The book links inflation directly to a weakening of money''s store-of-value function, since the same nominal amount buys fewer goods over time.', 'FALSE — Purchasing power is determined by prices, not by the physical banknotes; rising prices reduce purchasing power even if the notes are unchanged.', 'FALSE — It is precisely money''s store-of-value role, not just the medium-of-exchange role, that inflation undermines according to the book.', 'FALSE — One family''s choice to hold cash has no bearing on causing national inflation; this claim is unsupported and reverses cause and effect.', 'FALSE — The example directly contradicts this; inflation reduces the real value of stored cash over time, so the book does not make this recommendation.'], '3/5', 3, 'full' ),
( '2.4', 'CASE 2.4.04', 'Eurozone inflation holds close to the ECB''s preferred target', 'The European Central Bank reports that eurozone inflation is currently running at about 1.8 percent, which officials describe as being close to their preferred target of slightly below two percent. Commentators note that this is quite different from countries experiencing double-digit inflation, where citizens increasingly distrust their own currency. Evaluate the statements.', ARRAY['An inflation rate of about 1.8 percent, slightly below two percent, matches what the book describes as the ECB''s aim for price stability.', 'The book explains that money performs its functions — including as a store of value — reasonably well when inflation stays low and stable, as in this eurozone example.', 'In countries with very high inflation, the book notes that people can lose trust in their own currency, unlike in the low-inflation eurozone example described here.', 'Purchasing power refers to how much households can actually buy with their money; low, stable inflation helps protect that purchasing power over time.', 'This contrast between low eurozone inflation and countries with double-digit inflation illustrates why the book treats price stability as important for money to function well.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — The book describes the ECB''s target as inflation slightly below two percent, matching this figure.', 'TRUE — The book links low, stable inflation to money continuing to perform its functions well, including as a store of value.', 'TRUE — The book notes that very high inflation can erode trust in a currency, unlike the stable low-inflation eurozone case.', 'TRUE — This matches the book''s description of purchasing power and its relationship to inflation.', 'TRUE — The contrast between the two scenarios reflects exactly why the book emphasises price stability.'], '2/5', 4, 'full' ),
( '2.4', 'CASE 2.4.05', 'Vantoria''s fifteen percent inflation and a rush toward foreign currency', 'In the country of Vantoria, inflation has spiked to fifteen percent per year, far above the roughly two percent that central banks such as the ECB usually aim for. Many residents have started keeping savings in a more stable foreign currency instead of the local one, fearing further price rises. Evaluate the statements.', ARRAY['Vantoria''s fifteen percent inflation is far above the level the book associates with the ECB''s target of price stability, slightly below two percent.', 'Residents switching to a foreign currency reflects the book''s point that very high inflation can make people lose trust in money''s ability to store value.', 'Because residents are avoiding the local currency, the book states that money in Vantoria has completely stopped acting as a medium of exchange for all transactions.', 'High inflation erodes purchasing power, meaning the same amount of local currency buys fewer goods and services than before.', 'The book argues that a country''s inflation rate has no connection to how much citizens trust their own currency.'], ARRAY[true, true, false, true, false], ARRAY['TRUE — Fifteen percent inflation is far above the ECB-style target the book describes as slightly below two percent.', 'TRUE — The book links very high inflation to a loss of trust in a currency''s ability to store value.', 'FALSE — This overstates the case; the local currency can still be used for many domestic transactions even as trust in its store-of-value role weakens.', 'TRUE — Eroding purchasing power — buying fewer goods with the same amount of money — is the book''s core description of what high inflation does.', 'FALSE — The book draws a direct connection between high inflation and declining trust in a currency, the opposite of this claim.'], '3/5', 5, 'full' ),
( '2.4', 'CASE 2.4.06', 'Anborg''s lit pedestrian bridge, paid for by every taxpayer', 'The city of Anborg builds a well-lit pedestrian bridge over its river, paid for entirely out of general tax revenue. City planners note that it would be almost impossible to charge every walker a toll each time they cross, since there is no practical way to stop people from using it once it is built. Evaluate the statements about the government''s role.', ARRAY['The bridge is an example of a public good, similar to the streets and street lighting mentioned in the book, which are often financed through taxation.', 'The planners'' concern about being unable to stop non-paying walkers from crossing reflects the free-rider problem the book describes.', 'Because free riders cannot easily be excluded, private businesses often have little incentive to supply such goods, which is why the book says governments frequently step in.', 'Government spending on infrastructure like this bridge is funded through taxes collected from households and businesses, as the book describes.', 'This example fits the book''s broader point that governments provide certain goods, such as streets and public infrastructure, precisely because purely private markets tend to under-supply them.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Streets and similar infrastructure are the book''s examples of publicly financed goods, matching this bridge.', 'TRUE — The inability to exclude non-paying users is exactly the book''s free-rider problem.', 'TRUE — The book explains that free riders reduce private incentives to supply such goods, prompting government provision.', 'TRUE — Taxes from households and businesses funding public infrastructure matches the book''s description of government financing.', 'TRUE — This reflects the book''s broader argument for why governments supply such goods when private markets would under-provide them.'], '2/5', 6, 'full' ),
( '2.4', 'CASE 2.4.07', 'Halvby funds its national defence without selling it by the unit', 'The country of Halvby funds its national defence entirely through general taxation, with every taxpayer contributing regardless of how much protection any individual household believes it personally receives. A commentator argues that defence should instead be sold only to households willing to pay for it directly. Evaluate the statements.', ARRAY['National defence is a classic example of a public good the book lists, alongside streets and the police, which are typically funded through taxation rather than sold directly to individual buyers.', 'The commentator''s proposal would work well according to the book, since public goods like defence can easily exclude non-paying households once purchased individually.', 'Because defence protects the whole country at once, the book classifies it as a private good rather than a public good.', 'The book states that public goods such as defence must always be fully privatised to be provided efficiently.', 'Since some households might use less of the country''s defence than others, the book concludes that taxation for defence is unfair and should be abolished.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — The book names defence, alongside streets and the police, as a typical publicly funded good.', 'FALSE — This is the opposite of the free-rider problem the book describes: defence, like other public goods, is very hard to withhold from non-paying households.', 'FALSE — The book classifies goods like defence as public goods precisely because they cannot easily exclude non-payers, not as private goods.', 'FALSE — The book supports government provision of such goods because of the free-rider problem, not mandatory full privatisation.', 'FALSE — The book does not draw this conclusion; uneven individual usage is not presented as grounds for abolishing tax-funded provision of public goods.'], '4/5', 7, 'full' ),
( '2.4', 'CASE 2.4.08', 'Dimitar''s unemployment benefit after the factory layoffs', 'After being laid off from a factory, Dimitar starts receiving a monthly unemployment benefit from the state, funded by taxes collected from other working households and businesses. He does not provide any goods, services or labour directly in exchange for this payment. Evaluate the statements about government transfers.', ARRAY['Dimitar''s unemployment benefit is an example of a government transfer, a payment made without receiving a good or service directly in return, as described in the book.', 'Such transfers are typically financed through taxes paid by other households and businesses, illustrating the government''s redistributive role mentioned in the book.', 'Because Dimitar receives money from the state, the book classifies his benefit as wages earned through labour in the ordinary circular flow.', 'Subsidies and transfers are examples of how governments can support households or businesses beyond simply providing public goods like streets or defence.', 'The book states that once a person receives any government transfer, they are automatically excluded from the normal circular flow of wages and spending in the future.'], ARRAY[true, true, false, true, false], ARRAY['TRUE — A payment made without a direct good or service in return matches the book''s description of a government transfer.', 'TRUE — Financing such transfers through taxes on other households and businesses matches the book''s description of the government''s redistributive role.', 'FALSE — Wages are payment for labour actually supplied to a business; Dimitar''s benefit is specifically a transfer, not wages, since he provides no labour in return.', 'TRUE — The book presents subsidies and transfers as additional ways governments support households and businesses, distinct from providing public goods.', 'FALSE — Nothing in the book suggests receiving a transfer permanently excludes someone from future work, wages or spending in the circular flow.'], '3/5', 8, 'full' ),
( '2.4', 'CASE 2.4.09', 'Merrowfield debates privatising its school and its hospital', 'In the town of Merrowfield, the primary school and the local hospital are both run and largely funded by the government rather than by private companies charging market prices. A newly elected councillor proposes selling both to private investors to "make them more efficient." Evaluate the statements.', ARRAY['Education and health care are examples the book gives of services that are often provided publicly rather than left entirely to private markets.', 'The book insists that education and health care must always be one hundred percent privately owned everywhere, since government involvement is said to be illegal.', 'Because schools and hospitals serve many people, the book classifies them as pure public goods in exactly the same way as streets or national defence, with identical free-rider characteristics.', 'If the councillor''s privatisation plan went ahead, the school and hospital would then be funded mainly through direct payments from households rather than through general taxation.', 'The book claims that government transfers and public provision of services like health and education have no relationship to the taxes collected from households and businesses.'], ARRAY[true, false, false, true, false], ARRAY['TRUE — The book names education and health care as services often provided publicly rather than purely through private markets.', 'FALSE — This is an unsupported overstatement; the book does not claim government involvement in these sectors is illegal.', 'FALSE — The book distinguishes education and health as often publicly provided but does not equate them exactly with pure non-excludable public goods like streets or defence, which have stricter free-rider characteristics.', 'TRUE — Privatisation would shift funding toward direct payments by users rather than general taxation.', 'FALSE — The book directly links public provision of services like education and health to funding from taxes collected from households and businesses.'], '4/5', 9, 'full' ),
( '2.4', 'CASE 2.4.10', 'Welding, painting and delivery: three departments at CarParts Inc.', 'At CarParts Inc., the welding department only welds metal frames, the painting department only sprays finished frames, and a separate logistics department only manages deliveries to customers. No single worker performs all three tasks personally. Evaluate the statements about division of labour.', ARRAY['Splitting welding, painting and logistics into separate departments is an example of division of labour within a single firm, as described in the book.', 'The book notes that such specialisation can make each department more efficient at its own narrow task compared with workers doing everything themselves.', 'A possible disadvantage the book mentions is that workers doing only one repetitive task, such as welding all day, may find the work more boring than varied work.', 'Because each department only does one task, the book states this arrangement removes all risk for CarParts Inc., since specialised departments can never become obsolete.', 'If welding technology or car frame design changed enough that welding was no longer needed, the book''s warning about specialisation carrying a risk of obsolescence would apply directly to that department.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — Splitting tasks into departments within one company is the book''s example of division of labour within a firm.', 'TRUE — The book links such specialisation to efficiency gains from workers focusing on narrow tasks.', 'TRUE — The book lists boredom from repetitive, narrow tasks as a disadvantage of specialisation.', 'FALSE — This contradicts the book, which specifically warns that a disadvantage of specialisation is the risk of a narrow skill or task becoming obsolete.', 'TRUE — This is exactly the obsolescence risk the book associates with narrow specialisation.'], '3/5', 10, 'full' ),
( '2.4', 'CASE 2.4.11', 'A family shoe workshop divides cutting, stitching and delivery', 'In a small family shoe workshop, one parent only cuts the leather pieces, the other only stitches them together, and their teenage child only handles deliveries to nearby shops. Each family member has become quite skilled at their own single task. Evaluate the statements.', ARRAY['This is an example of division of labour at the household level, one of the levels the book describes alongside firms and international trade.', 'Because they are family members rather than employees, the book states this arrangement cannot be considered division of labour at all.', 'The book claims that division of labour only ever brings advantages and never carries any disadvantages, no matter the setting.', 'The book states that reduced flexibility is an advantage, not a disadvantage, of specialisation, since specialised workers become impossible to replace.', 'The book states that specialisation between family members inside a household is identical in every respect to specialisation between two entirely separate businesses trading with each other.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — The book explicitly recognises division of labour at the household level, alongside firms and international trade.', 'FALSE — Family members can absolutely engage in division of labour according to the book; being unpaid or related does not exclude the concept.', 'FALSE — The book lists disadvantages of specialisation, such as boredom, reduced flexibility, and risk of obsolescence, so this claim of no disadvantages is wrong.', 'FALSE — The book lists reduced flexibility as a disadvantage of specialisation, not an advantage.', 'FALSE — This overstates the equivalence; while the general logic of specialisation applies broadly, the book distinguishes different levels (household, firm, between firms, international) rather than treating them as identical in every respect.'], '4/5', 11, 'full' ),
( '2.4', 'CASE 2.4.12', 'From cotton field to finished shirt across three countries', 'Raw cotton is grown on farms in one country, shipped to a second country where it is spun into thread and woven into fabric, and then sewn into finished shirts in a third country before being sold to customers worldwide. Each country specialises in a different stage of production. Evaluate the statements.', ARRAY['This example illustrates international division of labour, one of the levels of specialisation the book describes.', 'It also shows division of labour between firms operating at different levels of production — growing cotton, spinning thread, and sewing shirts are different production stages.', 'The book suggests such specialisation can raise overall efficiency, since each country focuses on the stage where it has an advantage rather than each country trying to do everything itself.', 'Because three different countries are involved, the book classifies this only as division of labour between firms at the same production level, since all firms are equally involved in "making shirts."', 'The book claims that once international division of labour exists, no country involved can ever be negatively affected by changes in demand, since specialisation always protects against risk.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Specialisation spread across countries is exactly the book''s example of international division of labour.', 'TRUE — Growing, spinning and sewing are different production stages, matching the book''s category of division of labour between firms at different levels.', 'TRUE — The book links such specialisation across countries to efficiency gains from each focusing on its strongest stage.', 'FALSE — Growing raw cotton, spinning thread, and sewing shirts are different production stages, so this is division of labour between firms at different levels, not the same level.', 'FALSE — This contradicts the book''s own warning that specialisation carries a risk if demand for a specialised stage or product disappears.'], '3/5', 12, 'full' ),
( '2.4', 'CASE 2.4.13', 'Reading the arrows on a circular-flow diagram', 'A textbook diagram shows two arrows between households and businesses: one arrow labelled "labour" pointing from households to businesses, and an opposite arrow labelled "wages" pointing from businesses to households. A second pair of arrows shows "goods and services" flowing from businesses to households, and "payments" flowing back from households to businesses. Evaluate the statements about this circular-flow diagram.', ARRAY['This diagram matches the book''s circular-flow model, in which households supply labour to businesses in exchange for wages.', 'The diagram also matches the book''s model of businesses supplying goods and services to households in exchange for payments.', 'Together, these two flows form a continuous circular flow of resources and money between households and businesses, as the book describes.', 'If a government sector were added, the book''s extended model would also show taxes flowing from households and businesses to the government, and public goods or transfers flowing back.', 'The circular-flow model reflects the book''s basic idea that households and businesses continuously exchange resources with one another to meet their needs given limited resources.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Labour flowing from households to businesses in exchange for wages is exactly the book''s circular-flow model.', 'TRUE — Goods and services flowing from businesses to households in exchange for payments is the other half of the book''s model.', 'TRUE — Together these flows form the continuous circular flow the book describes.', 'TRUE — Adding a government sector with taxes flowing in and public goods or transfers flowing back matches the book''s extended circular-flow picture.', 'TRUE — This captures the book''s underlying point that households and businesses continuously exchange resources under conditions of scarcity.'], '2/5', 13, 'full' ),
( '2.4', 'CASE 2.4.14', 'One bicycle sale and three functions of money', 'A student sells her old bicycle to a classmate for forty euros. The buyer transfers the money electronically, both agree the bike is "worth" forty euros, and the seller plans to keep some of that money in her account for future use rather than spending it immediately. Evaluate the statements about money''s functions.', ARRAY['This single transaction illustrates all three functions of money described in the book: the euros act as a medium of exchange for the sale, a unit of account expressing the bike''s value, and a store of value for the money the seller keeps.', 'Even though the payment was electronic rather than physical cash, it still functions as a medium of exchange, since what matters is that it is widely accepted in exchange for goods.', 'The bike''s price of forty euros demonstrates money''s role as a unit of account, since it expresses the bike''s value in a common, comparable unit.', 'The book claims that money can only ever perform one of its three functions in a single transaction, never more than one at a time.', 'Because the seller plans to keep some of the money for later use rather than spending it immediately, it is also functioning as a store of value in this transaction.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — This transaction touches all three functions the book assigns to money: medium of exchange, unit of account, and store of value.', 'TRUE — Being electronic rather than physical cash does not remove money''s medium-of-exchange function, which depends on general acceptance, not physical form.', 'TRUE — Pricing the bike in euros expresses its value in a common unit, which is the unit-of-account function described in the book.', 'FALSE — The book does not limit money to one function per transaction; a single transaction can involve several of money''s functions at once, as this example shows.', 'TRUE — Keeping money for future use rather than spending it immediately is the store-of-value function described in the book.'], '3/5', 14, 'full' ),
( '2.4', 'CASE 2.4.15', 'A consultant studies a bolt-tightening assembly line', 'A workplace consultant studies an assembly line where each worker repeats exactly one small motion, such as tightening a single bolt, all day long for years. She notes that productivity per worker is high, but several employees report the work feels monotonous and say they would struggle to switch to a completely different role. Evaluate the statements.', ARRAY['High productivity from repeating one narrow task reflects the efficiency gains the book associates with division of labour.', 'The workers'' complaints about monotony match a disadvantage the book explicitly mentions: highly specialised work can become boring.', 'Their difficulty switching to a different role has nothing to do with division of labour, since the book states flexibility is unrelated to specialisation.', 'The book claims that division of labour has no disadvantages at all once productivity increases, since higher output always outweighs any other concern.', 'Because the workers are unhappy, the book concludes that division of labour should never be used in modern workplaces.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — The book directly links narrow specialisation with productivity gains from division of labour.', 'TRUE — The book lists boredom from repetitive, highly specialised tasks as a disadvantage.', 'FALSE — This contradicts the book, which specifically identifies reduced flexibility as a disadvantage linked to specialisation.', 'FALSE — The book explicitly lists disadvantages of division of labour (boredom, reduced flexibility, obsolescence risk), so this blanket claim is wrong.', 'FALSE — The book presents advantages and disadvantages of division of labour without concluding it should never be used; it is a trade-off, not an outright rejection.'], '3/5', 15, 'full' ),
( '2.4', 'CASE 2.4.16', 'Whitfield & Sons: the whip maker automobiles left behind', 'A century ago, Whitfield & Sons specialised entirely in manufacturing buggy whips for horse-drawn carriages, employing skilled workers who did nothing else. When automobiles rapidly replaced horse-drawn carriages, demand for buggy whips collapsed and the highly specialised firm struggled to adapt to making anything else. Evaluate the statements about division of labour and specialisation.', ARRAY['Whitfield & Sons'' deep specialisation in one product reflects the kind of division of labour and specialisation the book describes as increasing efficiency in normal times.', 'The firm''s struggle to adapt after demand collapsed illustrates a disadvantage the book associates with specialisation: the risk of a specialised product or skill becoming obsolete.', 'This example also shows why the book notes that highly specialised firms or workers can be less flexible when circumstances change suddenly.', 'Because Whitfield & Sons specialised so thoroughly, the book states this actually eliminated all risk for the firm, since specialisation is described as always safer than producing many different products.', 'If Whitfield & Sons had instead produced a wider range of unrelated products from the start, it might have been less exposed to this particular risk, consistent with the book''s discussion of specialisation''s downsides.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — Deep specialisation in one product is exactly the kind of division of labour the book links to efficiency gains under normal conditions.', 'TRUE — Struggling after demand collapse is a clear real-world illustration of the obsolescence risk the book associates with specialisation.', 'TRUE — Reduced flexibility when circumstances change suddenly is another disadvantage of specialisation the book raises.', 'FALSE — This contradicts the book, which treats deep specialisation as carrying more risk if the specialised product or skill becomes obsolete, not less.', 'TRUE — A broader product range would have reduced this specific risk, consistent with the book''s discussion of specialisation''s downsides.'], '3/5', 16, 'full' ),
( '2.4', 'CASE 2.4.17', 'Ashgrove and Elmridge: two chair makers, one market', 'Two competing furniture workshops, Ashgrove Woodworks and Elmridge Furniture, both buy timber and independently manufacture and sell finished wooden chairs to local shops. Neither workshop supplies parts or materials to the other; they simply compete for the same customers. Evaluate the statements about division of labour.', ARRAY['Ashgrove and Elmridge operate at the same level of production — both turning timber into finished chairs — which the book describes as division of labour between firms at the same level.', 'Because both workshops make chairs, the book classifies them as a single combined firm engaged in division of labour within one company.', 'The book states that firms operating at the same production level, like these two chair makers, cannot be said to specialise at all, since specialisation only applies between different production stages.', 'If Ashgrove instead started buying its timber from a separate logging company rather than harvesting trees itself, that relationship would illustrate division of labour between firms at different production levels.', 'The book claims that competition between firms at the same level, such as Ashgrove and Elmridge, always eliminates any disadvantages of specialisation, such as the risk of becoming obsolete.'], ARRAY[true, false, false, true, false], ARRAY['TRUE — Two separate firms both turning timber into chairs matches the book''s category of division of labour between firms at the same production level.', 'FALSE — Ashgrove and Elmridge remain two separate, competing firms; the book does not treat competing firms as a single combined company just because they make the same product.', 'FALSE — The book does not restrict specialisation to cross-level cases only; firms at the same level, like these two chair makers, still specialise in furniture-making rather than, for example, growing their own timber.', 'TRUE — Buying timber from a separate logging company would be division of labour between firms at different production levels, as the book describes.', 'FALSE — Being at the same production level does not eliminate the disadvantages of specialisation the book raises, such as obsolescence risk.'], '4/5', 17, 'full' ),
( '2.4', 'CASE 2.4.18', 'Norrland Timber sells logs; Elmridge turns them into furniture', 'Norrland Timber only fells trees and sells raw logs, while a separate company, Elmridge Furniture, buys those logs to manufacture finished chairs and tables. Neither company tries to perform the other''s task. Evaluate the statements about division of labour.', ARRAY['Norrland Timber and Elmridge Furniture illustrate division of labour between firms operating at different levels of production, one supplying raw material and the other finished goods.', 'This kind of specialisation can increase overall efficiency, since each firm focuses on the stage of production where it has developed particular expertise, as the book suggests.', 'Because the two firms are separate companies, the book states this cannot count as "division of labour" at all, since that term applies only within a single firm or household.', 'A disadvantage the book raises here is that if demand for finished furniture collapsed, Norrland Timber''s specialised reliance on selling logs to furniture makers could leave it vulnerable.', 'The book claims that firms at different production levels, unlike firms at the same level, are never able to trade with one another.'], ARRAY[true, true, false, true, false], ARRAY['TRUE — Supplying raw material versus finished goods at different production stages matches the book''s category of division of labour between firms at different levels.', 'TRUE — The book links such specialisation between firms to efficiency gains from each focusing on its own stage.', 'FALSE — The book explicitly recognises division of labour between separate firms, including at different production levels, not only within a single firm or household.', 'TRUE — Reliance on one downstream buyer''s demand is exactly the kind of vulnerability the book associates with specialisation.', 'FALSE — This is self-contradictory given the premise, since Norrland Timber selling logs to Elmridge Furniture is itself trade between firms at different production levels.'], '3/5', 18, 'full' ),
( '2.4', 'CASE 2.4.19', 'A lighthouse, unpaying ships, and a stubborn free-rider problem', 'An entrepreneur considers building a private lighthouse to help ships navigate a dangerous coastline, planning to charge each passing ship a fee for using its light. She soon realises that once the lighthouse is built, she has no practical way to stop ships that refuse to pay from still seeing and benefiting from its light at night. Evaluate the statements.', ARRAY['This scenario illustrates the free-rider problem the book describes, where those who do not pay cannot easily be excluded from benefiting once a good is provided.', 'Because the entrepreneur thought of the idea first, the book states she would legally be able to force every ship to pay regardless of the free-rider problem.', 'The free-rider problem described in the book only applies to goods provided by the government, never to privately proposed projects like this lighthouse.', 'The book concludes that lighthouses and similar goods with free-rider problems are always most efficiently provided by division of labour between two competing private firms.', 'Since ships benefit from the light without paying, the book states this proves that money has stopped working as a medium of exchange in this scenario.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — The inability to exclude non-paying users from a benefit once it exists is exactly the free-rider problem the book describes.', 'FALSE — Having the idea first does not solve the practical exclusion problem the book highlights; legal ownership does not automatically overcome the free-rider issue.', 'FALSE — The book''s free-rider logic explains why goods like this are often provided by government precisely because private provision runs into this same problem, regardless of who proposes it.', 'FALSE — This is an unsupported claim; the book''s point about free riders relates to why governments often step in, not to a preference for competing private firms.', 'FALSE — This is an unrelated, nonsensical connection; the free-rider problem concerns exclusion from a good, not money''s function as a medium of exchange.'], '4/5', 19, 'full' ),
( '2.4', 'CASE 2.4.20', 'A century of division of labour: gains and recurring downsides', 'A business school case study reviews a century of manufacturing history, noting that division of labour and specialisation — whether within a household, within a firm''s departments, between firms at the same production level, between firms at different levels, or across countries internationally — generally raised output and efficiency. The same case study also lists recurring downsides that appeared across many of these examples. Evaluate the statements.', ARRAY['The book identifies exactly these levels of division of labour: within a household, within a firm, between firms at the same level, between firms at different levels, and internationally.', 'Across these levels, the book associates division of labour with efficiency gains, since each unit focuses on the task or stage it performs best.', 'The book also lists disadvantages that can appear at any of these levels, including work becoming more boring for those doing narrow, repetitive tasks.', 'Reduced flexibility is another disadvantage the book raises, since workers, departments or firms that specialise narrowly may struggle to switch to different tasks if needed.', 'A further risk the book highlights is that a specialised task, product, or skill can become obsolete, leaving the specialised household, firm, or country worse off if demand disappears.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — These are exactly the levels of division of labour the book describes.', 'TRUE — The book associates specialisation at all these levels with efficiency gains from focusing on one''s strongest task or stage.', 'TRUE — Boredom from narrow, repetitive tasks is one of the disadvantages the book lists.', 'TRUE — Reduced flexibility is another disadvantage the book explicitly raises.', 'TRUE — The risk of a specialised task, product or skill becoming obsolete is a further disadvantage the book highlights.'], '3/5', 20, 'full' ),
( '2.5', 'CASE 2.5.01', 'Nordkasel''s bakeries versus Kelvara''s state bread quota', 'In the country of Nordkasel, hundreds of independent bakeries decide for themselves how much flour to buy, what bread to bake, and what price to charge; the government limits itself mainly to enforcing contracts and protecting private property. Across the border in Kelvara, a central planning ministry decides how many loaves each state bakery must produce, fixes the price of bread nationwide, and owns the flour mills and bakeries outright. A student comparing the two countries writes the following notes for economics class.', ARRAY['In Nordkasel, the price of bread is mainly determined by supply and demand between many independent bakeries and customers, which is typical of a free market economy.', 'In Kelvara, because the state owns the mills and bakeries and fixes prices centrally, this matches the book''s description of a planned economy, where government decides what is produced and at what price.', 'Because Nordkasel''s government enforces contracts and property rights, it is acting as a planned economy, since planned economies always start with a legal framework.', 'In a planned economy such as Kelvara, workers generally have less freedom to choose their employer or occupation than in a free market economy like Nordkasel, because the state directs resources including labour.', 'Since Kelvara''s bakeries are state owned, prices there will automatically fall below Nordkasel''s market prices, because state ownership always makes goods cheaper.'], ARRAY[true, true, false, true, false], ARRAY['TRUE — Bread prices arising from many independent bakeries responding to costs and customers, with government limited mainly to enforcing contracts and property rights, matches the book''s description of a free market economy.', 'TRUE — A ministry that owns the mills/bakeries, fixes nationwide prices, and dictates output quantities is exactly the book''s picture of a planned economy: the state decides what is produced, controls the means of production, and sets prices.', 'FALSE — Enforcing contracts and protecting property is the minimal legal-framework role the book assigns to government in a free market economy, not a sign of central planning; planned economies go far beyond this by directing output and prices.', 'TRUE — Because a planned economy directs resources including labour, job choice is typically more restricted than under a free market, where individuals can generally seek out employers themselves.', 'FALSE — The book does not claim state ownership automatically lowers prices; planned-economy prices are set by the planning authority and can be higher, lower, or simply fixed regardless of cost.'], '3/5', 1, 'full' ),
( '2.5', 'CASE 2.5.02', 'A civics class maps three economic systems', 'A civics teacher summarises three economic systems for her class before the students visit a local employment fair: a free market economy, an eco-social (social) market economy, and a planned economy. She distributes the following statements and asks the students to mark each true or false based on their textbook chapter on economic systems.', ARRAY['In a free market economy, most economic decisions — what is produced, how, and for whom — are left to private individuals and businesses interacting through supply and demand, with the government mainly providing a legal framework.', 'In a planned economy, the government (or a central planning authority) decides what goods and services are produced, controls the means of production, and typically sets prices itself.', 'A social or eco-social market economy keeps market mechanisms such as private business and competition, but the government also intervenes to support poorer members of society and to protect the environment.', 'In a planned economy, citizens usually have less choice over which job to take or which products to buy than in a free market economy, because resources and production are centrally directed.', 'Very few, if any, countries in the world operate as a completely pure free market or a completely pure planned economy; most real economies combine elements of both to different degrees.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — This matches the book''s core definition of a free market economy: private actors, supply and demand, and government confined mainly to a legal framework.', 'TRUE — This matches the book''s definition of a planned economy: a central authority decides output, controls the means of production, and usually sets prices.', 'TRUE — The book describes a social/eco-social market economy as retaining market mechanisms while government intervenes to support the disadvantaged and protect the environment.', 'TRUE — Centrally directed resource allocation in a planned economy typically leaves citizens less freedom over jobs and purchases than a free market economy does.', 'TRUE — The book frames these systems as a spectrum; almost all real economies mix elements rather than sitting at either pure extreme.'], '2/5', 2, 'full' ),
( '2.5', 'CASE 2.5.03', 'A pollution levy in eco-social Ravenholt', 'Two chemical factories operate in different countries. In Talmoor, a free market economy, the factory only has to follow the general legal framework and the government does not otherwise interfere with its production decisions or prices. In Ravenholt, an eco-social market economy, the factory must additionally pay a pollution levy and follow environmental limits that the government sets specifically to protect rivers and forests near the plant, while businesses still compete for customers and set their own prices. Evaluate the statements a student wrote about this comparison.', ARRAY['Ravenholt''s approach of taxing pollution and setting environmental limits while still allowing private competition matches the book''s description of an eco-social market economy, which protects the environment alongside market forces.', 'Because Talmoor is a free market economy, its government does not need any legal framework at all, since laissez-faire means zero government activity of any kind.', 'An eco-social market economy like Ravenholt is defined mainly by the government owning all factories to directly control pollution, similar to a planned economy.', 'In Talmoor''s free market, prices for chemicals would be centrally fixed by a planning ministry rather than resulting from supply and demand.', 'Because Ravenholt has environmental regulation, it can no longer be considered any kind of market economy, since only pure free markets qualify as market economies.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Ravenholt keeps private ownership and price competition while the state taxes pollution and sets environmental limits, matching the book''s description of an eco-social market economy protecting the environment within a market framework.', 'FALSE — A free market economy still needs a basic legal framework (e.g. property rights, contract enforcement); ''zero government activity of any kind'' is not the book''s definition of laissez-faire.', 'FALSE — An eco-social market economy is defined by market mechanisms plus targeted social/environmental intervention, not by the state owning all factories, which is instead a feature of a planned economy.', 'FALSE — In a free market economy prices are formed by supply and demand between private actors, not fixed by a planning ministry; that describes a planned economy.', 'FALSE — Environmental regulation alongside private competition is precisely what the book calls an eco-social market economy; it does not stop being a market economy.'], '4/5', 3, 'full' ),
( '2.5', 'CASE 2.5.04', 'Nordlandia''s competing bike makers, Kelmoria''s state works', 'In Nordlandia, several privately owned bicycle factories compete for customers, setting their own prices, while the government funds unemployment benefits and requires factories to treat wastewater before it reaches rivers. In Kelmoria, a single state bicycle works, owned and directed by the ministry of industry, is told each year exactly how many bicycles of each model to produce and at what price to sell them; workers are assigned to the factory by a labour office rather than applying for the job themselves.', ARRAY['Nordlandia''s combination of private, competing factories with government-funded welfare and environmental rules fits the book''s description of a social/eco-social market economy.', 'Kelmoria''s system, where the ministry decides quantities and prices and controls the state factory, matches the book''s description of a planned economy.', 'In Kelmoria, workers being assigned to the bicycle factory rather than applying themselves illustrates the more limited job choice typically associated with planned economies.', 'Because Nordlandia''s factories are privately owned and set their own prices, the government there cannot also fund unemployment benefits, since that would turn it into a planned economy.', 'Nordlandia''s factories competing on price for bicycles shows that market forces of supply and demand are still at work there, alongside the government''s social and environmental role.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — Private, competing factories combined with government-funded welfare and environmental requirements is the book''s picture of a social/eco-social market economy.', 'TRUE — A ministry-owned factory told exactly how much to produce and at what price is the book''s definition of a planned economy.', 'TRUE — Workers being assigned by a labour office rather than applying themselves illustrates the more limited job choice the book associates with planned economies.', 'FALSE — Funding unemployment benefits alongside private, price-setting factories is exactly what the book calls a social/eco-social market economy, not a planned one; welfare spending alone does not make a system planned.', 'TRUE — Factories competing on price for customers shows supply-and-demand forces are still operating in Nordlandia, alongside its social and environmental policies.'], '3/5', 4, 'full' ),
( '2.5', 'CASE 2.5.05', 'Vezmania''s shoe factories before and after 1990', 'Before 1990, the fictional country of Vezmania ran a planned economy: a central bureau decided how many pairs of shoes each state-owned factory would make, fixed their price nationwide, and assigned workers to specific factories. After 1990, Vezmania began transforming its economy: it sold many state factories to private owners, let shoe prices be set by supply and demand, and allowed workers to apply for jobs of their choice, while keeping some state support for pensions and the unemployed.', ARRAY['Before 1990, Vezmania''s system — central decisions on quantities, fixed prices, and worker assignment — matches the book''s description of a planned economy.', 'After the reforms, Vezmania moved further from a free/social market economy and closer to a purely planned economy, since it kept some state pensions.', 'Vezmania''s post-1990 mix of private ownership, market-based prices and some state welfare support is consistent with the book''s idea that many real economies are market-oriented mixed systems rather than pure free markets.', 'Selling state factories to private owners and letting prices be set by supply and demand are steps that make an economy more planned, according to the book.', 'Before 1990, because workers were assigned to specific factories, this shows Vezmania actually had more job choice than a free market economy would offer.'], ARRAY[true, false, true, false, false], ARRAY['TRUE — Central decisions on output quantities, fixed nationwide prices, and assigned workers are the book''s hallmark features of a planned economy.', 'FALSE — Keeping some welfare support like pensions while privatising and freeing prices is a move toward a social/market-oriented system, not toward a purely planned economy; the book does not treat any welfare spending as automatically ''planned''.', 'TRUE — Combining private ownership, market-based prices, and some state welfare fits the book''s point that most real economies are mixed, market-oriented systems rather than pure free markets.', 'FALSE — Privatisation and letting prices respond to supply and demand are, according to the book, steps away from a planned economy and toward a market economy, not the reverse.', 'FALSE — Assigning workers to fixed factories restricts job choice compared with a free market, where individuals can apply to employers of their choosing; it does not mean more choice.'], '3/5', 5, 'full' ),
( '2.5', 'CASE 2.5.06', 'Yanshu''s private shops and state-run railway', 'In Yanshu, most consumer goods — clothing, restaurants, electronics — are produced and priced by private companies competing for customers. However, a handful of strategic industries, such as electricity generation and the national railway, remain fully owned and directed by the state, which sets both their output levels and prices. A visiting analyst summarises Yanshu''s system for a report.', ARRAY['Yanshu''s mixture of largely private, competitively priced consumer goods together with a few fully state-directed strategic industries shows that real economies often combine market and planned elements rather than being purely one or the other.', 'Because most consumer goods in Yanshu are privately produced, the state-owned railway and electricity company must also set their prices purely through supply and demand, since no country mixes systems.', 'Yanshu should be classified as a pure free market economy, since the majority of goods are produced privately.', 'The fact that Yanshu''s government directs quantities and prices in electricity and rail has no relation to the book''s description of a planned economy, since planned economies only ever cover 100% of the economy.', 'In Yanshu, private companies compete for customers in most sectors, which means the government cannot also own any businesses at all, according to the book''s definitions.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Largely private, competitively priced consumer goods sitting alongside a few fully state-directed strategic industries illustrates the book''s point that real economies often mix market and planned features.', 'FALSE — The book does not claim mixed systems force every sector to use the same pricing method; state-directed industries can keep centrally set prices even while most consumer goods are market-priced.', 'FALSE — A pure free market economy has essentially no state-owned, state-directed industries; Yanshu''s state-run electricity and rail sector rules this out.', 'FALSE — Directing output and prices in specific industries is precisely the kind of government control over production the book associates with planned economies, even if it applies to only part of the economy.', 'FALSE — Private competition and state-owned businesses can coexist within one country; private competition elsewhere does not rule out state ownership in specific sectors.'], '3/5', 6, 'full' ),
( '2.5', 'CASE 2.5.07', 'Ration coupons in a planned-economy town', 'In a planned economy that a history class is studying, households received ration coupons for clothing and food because the state decided in advance how much of each good would be produced and distributed, rather than relying on prices to balance what shops offered with what people wanted to buy. The teacher then asks the class to evaluate the following statements about planned economies in general.', ARRAY['In a planned economy, because prices and quantities are often fixed centrally rather than adjusting to supply and demand, mismatches between what is available and what people want (such as needing ration coupons) can occur.', 'A defining feature of a planned economy, according to the book, is that the government (rather than private owners) controls the means of production, such as factories and land used for manufacturing.', 'In a planned economy, the range of products available to consumers is typically more limited than in a free market economy, since a central authority decides what gets produced.', 'The use of ration coupons in this example reflects limited consumer choice, which the book associates with planned rather than free market economies.', 'A free market economy, by contrast, generally relies on prices moving up or down to balance the amount of a good supplied with the amount demanded, without ration coupons.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — When prices and quantities are fixed centrally rather than set by supply and demand, mismatches between what''s produced and what people want can arise, which the book links to planned economies.', 'TRUE — Government (rather than private owners) controlling the means of production is one of the book''s defining features of a planned economy.', 'TRUE — A central authority deciding what gets produced typically narrows the range of products on offer compared with a free market economy.', 'TRUE — Rationing consumer purchases reflects the more limited consumer choice the book associates with planned rather than free market economies.', 'TRUE — In a free market economy, prices moving in response to supply and demand — rather than rationing — is the book''s standard mechanism for balancing what''s offered with what''s wanted.'], '2/5', 7, 'full' ),
( '2.5', 'CASE 2.5.08', 'Daniel in Ostbrandt, Mia in Suderland', 'Daniel grew up in Ostbrandt, a planned economy where the state labour office assigned school leavers to specific jobs in state-owned enterprises based on national production needs. His pen pal Mia lives in Suderland, a free market economy, where she can apply to any employer she likes, and companies compete to attract staff by offering higher wages or better conditions. They write to each other about how careers work in their countries.', ARRAY['In Ostbrandt, Daniel''s limited ability to choose his own job reflects the more restricted job choice typically found in a planned economy.', 'In Suderland, companies competing to attract staff with wages and conditions reflects how a free market economy relies on supply and demand, including in the labour market.', 'Because Ostbrandt is a planned economy, its government must also fix the prices of all consumer goods, since job assignment and price-setting are the exact same policy tool according to the book.', 'Suderland''s system, where individuals choose employers and firms compete for workers, is consistent with the book''s description of a free market economy relying on private decision-making.', 'Mia having more job choice than Daniel proves that free market economies never have any unemployment or job insecurity.'], ARRAY[true, true, false, true, false], ARRAY['TRUE — Being assigned a job rather than choosing one reflects the more restricted job choice the book associates with planned economies.', 'TRUE — Firms competing for staff through wages and conditions shows the labour market responding to supply and demand, as expected in a free market economy.', 'FALSE — The book does not treat job assignment and price-fixing as ''the exact same policy tool''; a planned economy commonly directs both, but that is not because they are identical, and the claim overstates what the book actually says.', 'TRUE — Individuals choosing employers while firms compete for workers is consistent with the book''s description of how a free market economy operates, including in the labour market.', 'FALSE — Greater job choice in a free market economy does not mean the book claims such economies are free of unemployment or job insecurity; the book makes no such guarantee.'], '3/5', 8, 'full' ),
( '2.5', 'CASE 2.5.09', 'Baerholm''s competing furniture shops and tax-funded safety net', 'In Baerholm, a social market economy, private companies compete for customers and set their own prices for goods such as furniture and clothing. At the same time, the government collects income tax to fund unemployment benefits, public healthcare, and support payments for low-income families. A visiting journalist writes a short report on how Baerholm''s economy works.', ARRAY['Baerholm''s combination of competing private businesses with tax-funded unemployment benefits and healthcare for the poor matches the book''s description of a social (eco-social) market economy.', 'Because the government funds healthcare and unemployment benefits, Baerholm must be a planned economy, since only planned economies provide any welfare support.', 'In Baerholm, furniture and clothing prices are still mainly shaped by competition among private companies rather than fixed centrally by the state, which is consistent with market-based pricing.', 'A social market economy, by the book''s definition, requires the government to own all businesses that provide healthcare or unemployment support.', 'Supporting low-income families through tax-funded payments means Baerholm''s businesses no longer compete with each other for customers.'], ARRAY[true, false, true, false, false], ARRAY['TRUE — Competing private businesses combined with tax-funded unemployment benefits, healthcare, and support for low-income families matches the book''s description of a social (eco-social) market economy.', 'FALSE — Funding welfare programmes through taxation is a feature the book associates with a social market economy, not exclusively with planned economies; plenty of market economies provide some welfare support.', 'TRUE — Prices still being shaped by competition among private firms, rather than fixed by the state, is consistent with market-based pricing continuing alongside welfare spending.', 'FALSE — The book does not require government ownership of healthcare or benefit-providing businesses for a system to count as a social market economy; taxation-funded transfers are enough.', 'FALSE — Funding welfare through taxes does not stop businesses from competing for customers; the two can and do coexist in a social market economy.'], '3/5', 9, 'full' ),
( '2.5', 'CASE 2.5.10', 'Ranking countries between two economic extremes', 'An economics research team ranks several fictional countries on a scale from ''closer to a pure free market economy'' to ''closer to a pure planned economy'', noting that none of the countries sit exactly at either extreme. They summarise their general findings for a school textbook appendix.', ARRAY['A pure free market economy, with essentially no government intervention beyond a basic legal framework, is mainly a theoretical benchmark rather than something found in exactly that form in the real world.', 'A pure planned economy, where the state controls all production, all prices, and all resource allocation, is likewise rarely, if ever, found in its complete form today.', 'Most real-world economies sit somewhere between the two extremes, combining market elements (private business, competition) with varying degrees of government intervention, such as welfare or regulation.', 'Because no country is a perfectly pure free market, it follows that every country in the world must therefore be classified as a planned economy.', 'Government intervention in a market-oriented economy can range from minimal (mainly legal framework) to more extensive (welfare, environmental protection), without necessarily making the whole system a planned economy.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — The book presents a pure free market (minimal government, only a legal framework) largely as a theoretical benchmark rather than a real-world case.', 'TRUE — Likewise, a pure planned economy with total state control over production, prices and resources is presented as rare in its complete form.', 'TRUE — The book emphasises that most real economies combine market elements with varying degrees of government intervention, sitting between the two extremes.', 'FALSE — Not being a pure free market does not make a country a planned economy; the book describes a spectrum with market-oriented mixed economies in between, not just two categories.', 'TRUE — Government intervention can vary in degree (from minimal to extensive) within what the book still calls market-oriented or social market economies, without turning them into planned economies.'], '3/5', 10, 'full' ),
( '2.5', 'CASE 2.5.11', 'Tomato prices at Lindenau market versus a state farm''s price list', 'At the Lindenau farmers'' market, independent farmers each decide how to price their own tomatoes based on their costs and what customers seem willing to pay that week. At a state farm cooperative in a nearby planned region, a central agricultural office issues one fixed price list that every farm must use for tomatoes, regardless of local costs or how quickly they sell.', ARRAY['The Lindenau farmers setting their own tomato prices based on costs and customer willingness to pay is typical of price formation in a free market economy.', 'The state farm cooperative''s single fixed price list issued centrally is typical of a free market economy, since fixed prices make trading simpler for everyone.', 'Because the state farm''s price is fixed, tomatoes there can never be in short supply or oversupply, unlike in a free market.', 'The independent farmers at Lindenau must be part of a planned economy, since farmers markets always involve the government setting stall fees and prices.', 'A central agricultural office issuing one uniform price for all farms shows that the market, not the government, is determining tomato prices in that region.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Independent sellers pricing goods based on their own costs and customer willingness to pay is the book''s description of price formation in a free market economy.', 'FALSE — A single, centrally fixed price list issued by an authority is the book''s description of a planned economy''s pricing, not a free market''s.', 'FALSE — The book does not claim fixed prices prevent surpluses or shortages; mismatches between quantity offered and quantity wanted can still occur even under fixed pricing.', 'FALSE — Farmers freely setting their own prices at a market is a free market feature, not evidence of central planning; the book does not require government-set stall fees for a market to exist.', 'FALSE — A single uniform price set by a central office is the opposite of market-determined pricing; it shows government, not supply and demand, setting the price in that region.'], '4/5', 11, 'full' ),
( '2.5', 'CASE 2.5.12', 'A paper mill''s fine, subsidy, and free-set prices', 'In the eco-social market economy of Greenholt, a paper mill is privately owned and sets its own prices for paper, but it must pay a government-imposed fine for every tonne of untreated waste it releases into the river, and it receives a small subsidy if it switches to recycled wood pulp. A student is asked to relate this to the textbook''s description of economic systems.', ARRAY['The paper mill being privately owned and free to set its own prices, combined with government fines and subsidies aimed at protecting the river, fits the book''s description of an eco-social market economy.', 'Because the mill must pay pollution fines, Greenholt''s government must also be deciding how much paper the mill is allowed to produce each year, since environmental rules and production quotas are the same thing in the book.', 'The subsidy for switching to recycled wood pulp is an example of government intervention aimed at protecting the environment, which the book associates with eco-social market economies rather than pure free markets.', 'A pure free market economy, as defined in the book, would typically include government fines and subsidies targeted at specific environmental outcomes like this one.', 'Because the mill remains privately owned, Greenholt cannot be considered any kind of market economy once environmental fines are introduced.'], ARRAY[true, false, true, false, false], ARRAY['TRUE — Private ownership and free pricing combined with government fines and subsidies aimed at protecting the environment is the book''s picture of an eco-social market economy.', 'FALSE — The book does not equate environmental fines with production quotas; the mill can still decide its own output level and prices while facing a pollution charge.', 'TRUE — A subsidy encouraging a more environmentally friendly production method is the kind of environmental intervention the book associates with eco-social, rather than purely free, market economies.', 'FALSE — Targeted environmental fines and subsidies are a defining feature the book uses to distinguish an eco-social market economy from a pure free market, which relies mainly on a basic legal framework.', 'FALSE — Remaining privately owned while facing environmental rules does not remove a system from being a market economy; the book explicitly describes this combination as an eco-social market economy.'], '3/5', 12, 'full' ),
( '2.5', 'CASE 2.5.13', 'Feldgau''s minimum wage and free-pricing companies', 'In Feldgau, a social market economy, the government sets a minimum wage and requires paid holiday leave for workers, and it funds a public pension system through payroll taxes. At the same time, private companies in Feldgau are completely free to decide what products to manufacture, how much to produce, and what prices to charge, based on what they think customers want. An economics textbook uses Feldgau to illustrate the following statements.', ARRAY['Feldgau''s government intervening to protect workers (minimum wage, paid leave) and fund pensions, while leaving production and pricing decisions to private companies, illustrates a social market economy rather than a planned one.', 'Unlike a planned economy, Feldgau''s government does not decide what products companies must manufacture or at what price they must sell them.', 'The presence of a minimum wage and public pension system shows that Feldgau''s government intervenes to support workers and, more broadly, less advantaged members of society.', 'Because companies in Feldgau still decide their own output and prices, market forces of supply and demand continue to operate there, just alongside social protections.', 'A social market economy like Feldgau''s differs from a free market economy mainly in the degree of government intervention aimed at social protection, not in who controls the means of production.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Government support for workers and pensions alongside private firms freely deciding output and price is the book''s description of a social market economy.', 'TRUE — Unlike a planned economy, a social market economy leaves output and pricing decisions to private businesses rather than the state.', 'TRUE — Minimum wage laws and public pensions are examples of the book''s idea that a social market economy''s government intervenes to support workers and less advantaged citizens.', 'TRUE — Firms still setting their own output and prices means supply-and-demand forces continue to operate, even alongside social protections.', 'TRUE — The book distinguishes a social market economy from a free market economy mainly by the degree of social intervention, not by who controls the means of production, which remains private in both.'], '2/5', 13, 'full' ),
( '2.5', 'CASE 2.5.14', 'One state bakery in Kirengrad, a dozen bakeries in Alvingen', 'In the planned town of Kirengrad, the only bakery is state-run and offers exactly two types of bread decided annually by the regional planning office. In the market town of Alvingen, a dozen independently owned bakeries compete, together offering dozens of bread varieties, with each bakery adjusting its recipes and prices based on what customers buy.', ARRAY['Kirengrad''s limited bread selection, decided by a planning office rather than by competing businesses, reflects the more restricted product choice typically associated with planned economies.', 'Alvingen''s dozen competing bakeries offering many varieties and adjusting prices to customer demand is typical of how a free market economy operates.', 'Because Kirengrad has only one bakery, it must be a monopoly created by market competition rather than an outcome of government planning.', 'In Alvingen, if a bakery consistently offers bread nobody wants to buy, market pressure (falling sales) rather than a planning office is what would push it to change its products or prices.', 'A planned economy such as Kirengrad''s typically offers a wider range of consumer products than a free market economy, since central planners can foresee every taste.'], ARRAY[true, true, false, true, false], ARRAY['TRUE — A single state bakery offering a limited, centrally decided range of bread matches the book''s point that planned economies typically restrict consumer product choice.', 'TRUE — Multiple competing bakeries adjusting recipes and prices to what customers buy illustrates how a free market economy responds to supply and demand.', 'FALSE — Kirengrad''s single bakery exists because a planning office decided so, not because of market competition; the book distinguishes a government-created sole supplier under planning from market-driven concentration.', 'TRUE — In a free market, falling sales (rather than a planning office) is the signal that pushes businesses to change products or prices.', 'FALSE — The book associates planned economies with narrower, centrally decided product ranges, not wider variety, since central planners cannot anticipate every individual preference the way a competitive market can respond to them.'], '4/5', 14, 'full' ),
( '2.5', 'CASE 2.5.15', 'Vartok Steel Works after privatisation', 'The state-owned Vartok Steel Works, once directed entirely by a central industry ministry that fixed its output and the price of every steel beam it sold, was sold to private investors last year. The new private owners now decide themselves how much steel to produce and what prices to charge customers, though a new environmental law still requires them to limit smoke emissions and the government still pays unemployment benefits to laid-off workers.', ARRAY['Before privatisation, Vartok Steel Works being directed by a ministry that fixed output and prices matches the book''s description of a planned economy.', 'After privatisation, the owners deciding output and prices themselves shows the mill is now operating more like a business in a market economy.', 'The continuing environmental law limiting emissions and government-funded unemployment benefits suggest the wider economy still has features of a social/eco-social market economy rather than a purely unregulated free market.', 'Because Vartok Steel Works is now privately owned, it follows automatically that the whole country has become a completely pure free market economy with no government intervention anywhere.', 'The shift from ministry-fixed output and prices to owner-determined output and prices is an example of a move away from planned-economy characteristics toward market-based ones.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — A ministry fixing both output and prices for a state-owned firm is the book''s definition of a planned economy in action.', 'TRUE — Owners now deciding output and prices themselves shows the firm behaving as it would in a market economy.', 'TRUE — Continued environmental regulation and state-funded unemployment benefits suggest the broader system still has social/eco-social market features rather than being an unregulated free market.', 'FALSE — Privatising one firm does not mean the whole country becomes a purely free market economy with no government role anywhere; the same example still shows ongoing regulation and welfare spending.', 'TRUE — Moving from ministry-fixed output/prices to owner-determined output/prices is exactly the kind of shift the book describes from planned toward market-based characteristics.'], '3/5', 15, 'full' ),
( '2.5', 'CASE 2.5.16', 'Solmark''s council-run refrigerator factory', 'In the region of Solmark, a regional council decides each year exactly how many refrigerators the single state-owned appliance factory must produce, sets the price at which they must be sold in every shop, and assigns newly trained engineers to work there rather than letting them apply elsewhere.', ARRAY['Solmark''s system — central quantity decisions, fixed prices, and assigned jobs — matches the book''s description of a planned economy.', 'Because refrigerators are sold in shops to ordinary customers, Solmark''s system must actually be a free market economy, since any retail sale automatically counts as free market activity.', 'Assigning engineers to the factory rather than letting them choose their employer is typical of a free market economy''s approach to labour.', 'The regional council fixing both output and price is a normal feature of a purely free market economy, according to the book.', 'Solmark''s single state-owned factory deciding its own prices independently of the council shows market forces are fully at work here.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Centrally decided output quantities, fixed prices, and assigned jobs match the book''s definition of a planned economy.', 'FALSE — Selling goods to customers in shops happens under both planned and free market economies; retail sale alone does not determine which system is in place.', 'FALSE — Assigning workers rather than letting them apply is the book''s example of restricted job choice under a planned economy, not a free market one.', 'FALSE — Central fixing of both output and price by an authority is the opposite of free market pricing, which the book says results from supply and demand between private actors.', 'FALSE — The factory does not set its own prices in this scenario; the regional council does, which is a planned-economy feature, not evidence of market forces.'], '4/5', 16, 'full' ),
( '2.5', 'CASE 2.5.17', 'Ashenvale''s progressive tax and insulation grants', 'The government of Ashenvale introduces a progressive income tax, using part of the revenue to fund free school meals for children from low-income families and grants for insulating older homes to cut energy use. Private businesses in Ashenvale continue to set their own prices and compete for customers as before.', ARRAY['Ashenvale''s progressive tax funding support for low-income families, alongside businesses that still compete and set their own prices, is consistent with the book''s description of a social (eco-social) market economy.', 'Because the government introduced a new tax, Ashenvale''s businesses can no longer be considered private, since taxation always implies state ownership according to the book.', 'The home insulation grants, which reduce energy use, are an example of government intervention aimed at protecting the environment, a feature associated with eco-social market economies.', 'Progressive taxation to fund welfare programmes is a policy tool that, according to the book, is only ever used in planned economies and never in market economies.', 'Because businesses in Ashenvale still set their own prices, no government intervention of any kind (including taxation for welfare) can be occurring at the same time.'], ARRAY[true, false, true, false, false], ARRAY['TRUE — A progressive tax funding support for low-income households, alongside businesses still competing and pricing freely, matches the book''s description of a social (eco-social) market economy.', 'FALSE — Introducing a tax does not make businesses state-owned; the book treats taxation for welfare as compatible with privately owned, competing businesses in a social market economy.', 'TRUE — Grants that reduce energy use are the kind of environmental intervention the book associates with an eco-social market economy.', 'FALSE — The book associates redistributive taxation with social/eco-social market economies as much as, or more than, with planned economies; it is not exclusive to planned systems.', 'FALSE — Businesses continuing to set their own prices does not rule out simultaneous government intervention like taxation for welfare; the book describes exactly this combination as a social market economy.'], '3/5', 17, 'full' ),
( '2.5', 'CASE 2.5.18', 'Shop A''s own prices versus Shop B''s nationwide price list', 'A retail-studies class compares two shops. Shop A is independently owned; its manager sets prices based on costs, competitors, and customer demand, and can stock whatever products she believes will sell. Shop B belongs to a network where a central planning office issues one fixed nationwide price list for every product and decides which items each branch is allowed to stock. The class discusses which economic system each shop reflects.', ARRAY['Shop A''s manager setting prices based on costs, competitors and customer demand is a small-scale example of how prices are formed in a free market economy.', 'Shop B''s central planning office fixing nationwide prices and deciding what each branch may stock reflects characteristics the book associates with a planned economy.', 'In Shop A''s system, if customers stop buying a product, the manager can respond by changing price or stock without needing approval from a central authority, unlike Shop B.', 'Shop B''s approach limits the individual branch''s ability to respond directly to local supply and demand, since decisions are made centrally instead.', 'Comparing Shop A and Shop B illustrates the book''s broader distinction between market economies, where private decision-makers respond to supply and demand, and planned economies, where a central authority makes those decisions.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — A manager setting prices based on costs, competitors, and demand is a small-scale illustration of free market price formation.', 'TRUE — A central office fixing nationwide prices and dictating branch stock matches the book''s description of a planned economy''s characteristics.', 'TRUE — The ability to adjust price or stock without central approval, in response to customers, is a hallmark of a free market economy that Shop B''s system lacks.', 'TRUE — Centrally made decisions prevent individual branches from responding directly to local supply and demand conditions, which the book links to planned economies.', 'TRUE — The contrast between Shop A and Shop B mirrors the book''s broader distinction between market economies (private decision-making, supply and demand) and planned economies (central authority decisions).'], '2/5', 18, 'full' ),
( '2.5', 'CASE 2.5.19', 'Birkenfeld''s childcare and solar panel subsidies', 'The government of Birkenfeld offers a subsidy to parents who place their children in registered childcare, so they can continue working, and a separate grant to homeowners who install solar panels on their roofs. Private childcare providers and solar panel installers still compete with each other on price and quality for customers.', ARRAY['The childcare subsidy, aimed at supporting working parents, reflects the kind of government support for households that the book associates with a social (eco-social) market economy.', 'The solar panel grant, aimed at encouraging cleaner energy, reflects the environmental-protection role the book associates with an eco-social market economy.', 'Because childcare providers and installers still compete on price and quality, market mechanisms continue to operate in Birkenfeld alongside the government subsidies.', 'Introducing these two subsidies means the government must now also own all childcare centres and solar panel companies, since subsidies always imply state ownership.', 'Because Birkenfeld''s government offers subsidies, it must be a planned economy, since only planned economies allow any form of government spending.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — A subsidy supporting working parents'' access to childcare reflects the kind of household support the book associates with a social (eco-social) market economy.', 'TRUE — A grant encouraging cleaner energy reflects the environmental-protection role the book associates with an eco-social market economy.', 'TRUE — Providers still competing on price and quality shows market mechanisms remain active alongside the government subsidies.', 'FALSE — The book does not treat subsidies as requiring state ownership of the subsidised businesses; providers can remain private while receiving a subsidy.', 'FALSE — Offering subsidies does not, by itself, make a system a planned economy; the book explicitly describes subsidies as one tool used in social/eco-social market economies alongside private competition.'], '3/5', 19, 'full' ),
( '2.5', 'CASE 2.5.20', 'A class project on the economic-systems spectrum', 'For a final class project, students summarise what they learned about economic systems across the chapter, using examples from a free-market-leaning country, a social-market-leaning country, and a formerly planned country that transformed into a market-oriented one after reforms.', ARRAY['A country leaning toward a free market economy relies mainly on private decision-making and competition, with government limited largely to providing a legal framework.', 'A country leaning toward a social/eco-social market economy keeps market mechanisms but has the government intervene more to support the poor and protect the environment.', 'A formerly planned economy that transforms toward a market-oriented system typically involves privatising state-owned enterprises and allowing prices to be set more by supply and demand.', 'Once a formerly planned economy begins allowing some private business, it must, according to the book, immediately become a pure free market economy with no state involvement left.', 'In practice, most economies combine market elements with some degree of government intervention, meaning the three systems described in the book are best understood as points along a spectrum rather than strictly separate categories.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — Reliance on private decision-making, competition, and a minimal legal-framework government matches the book''s description of a free market economy.', 'TRUE — Keeping market mechanisms while having government support the poor and protect the environment matches the book''s description of a social/eco-social market economy.', 'TRUE — Privatisation and letting prices respond more to supply and demand are typical steps the book associates with a formerly planned economy transforming toward a market-oriented one.', 'FALSE — The book presents these systems as a spectrum; allowing some private business does not instantly eliminate all state involvement or make an economy a pure free market.', 'TRUE — The book''s overall framing treats free market, social/eco-social market, and planned economies as points along a spectrum rather than strictly separate, all-or-nothing categories.'], '3/5', 20, 'full' ),
( '2.6', 'CASE 2.6.01', 'Haggling over tulips at Campo de'' Fiori', 'Every morning at the Campo de'' Fiori in Rome, flower sellers set up stalls and haggle face-to-face with customers over bunches of tulips and roses, agreeing on a price on the spot. A tourist watching this scene asks her economics-teacher friend how this relates to the textbook''s definition of a market.', ARRAY['According to the book, a market exists wherever buyers and sellers communicate to agree on the conditions of an exchange, and the Rome flower stalls are one physical example of this.', 'The book defines a market strictly as a specific building or physical location, so exchanges that happen over the phone or online would not count as markets at all.', 'The face-to-face haggling over price at the flower stalls is one way buyers and sellers can communicate to reach agreement, but the book notes markets can also work through other channels such as phone or internet.', 'Because the flower sellers negotiate individually with each customer, this scene cannot be called a market, since the book says markets always require a single fixed price with no negotiation.', 'A market, as defined in the book, requires that buyers and sellers physically shake hands to finalise a deal, otherwise no real exchange has taken place.'], ARRAY[true, false, true, false, false], ARRAY['TRUE — The book defines a market as any situation where buyers and sellers communicate to agree on the conditions of an exchange; the Rome flower stalls are a physical example of this.', 'FALSE — The book explicitly notes markets can be physical or virtual (e.g. eBay, Amazon, phone orders), so it does not restrict ''market'' to a specific building or location.', 'TRUE — Face-to-face negotiation is one channel of communication the book mentions, alongside others such as phone or internet, for reaching agreement in a market.', 'FALSE — The book does not require a single fixed, non-negotiable price for something to count as a market; negotiated prices, as at the flower stalls, are still market exchanges.', 'FALSE — The book does not require physical handshakes to finalise an exchange; agreements reached by phone or online are still treated as markets.'], '3/5', 1, 'full' ),
( '2.6', 'CASE 2.6.02', 'A second-hand guitar and new strings, bought online', 'Liam buys a second-hand guitar on an online auction site and, a week later, orders new guitar strings from a large online retailer. In both cases he never meets the seller in person; he simply browses listings, compares prices, and pays online.', ARRAY['Liam''s online auction purchase is an example of a market where buyers and sellers communicate the conditions of exchange virtually rather than meeting physically.', 'Ordering guitar strings from a large online retailer is also a market, even though there is no physical marketplace building involved.', 'Both purchases show that, according to the book, a market can be understood as any setting — physical or virtual — in which buyers and sellers agree on how an exchange will take place.', 'Because Liam never meets the sellers face-to-face, neither of his purchases can be classified as taking place in a market, since the book requires in-person contact for something to count as a market.', 'Comparing prices across different online listings before buying is consistent with how the book describes buyers and sellers interacting within a market, even in a virtual setting.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — Buying on an online auction site, where buyer and seller never meet, is an example of a virtual market as the book describes it.', 'TRUE — Ordering from a large online retailer is likewise a market, even without a physical marketplace location.', 'TRUE — Both purchases fit the book''s broader definition of a market as any setting, physical or virtual, where buyers and sellers agree on exchange conditions.', 'FALSE — The book explicitly gives virtual examples like eBay and Amazon as markets, so in-person contact is not required for a transaction to count as a market.', 'TRUE — Comparing prices across online listings before buying is consistent with buyers and sellers interacting within a market, even virtually.'], '2/5', 2, 'full' ),
( '2.6', 'CASE 2.6.03', 'A hardware shop that mostly sells by phone', 'A small hardware shop takes most of its orders by telephone: customers call in, ask about prices and availability of tools, and agree over the phone to have items delivered. The shop owner also occasionally sells tools face-to-face to walk-in customers.', ARRAY['According to the book, a market is any situation where buyers and sellers communicate the conditions under which an exchange will happen, regardless of whether they meet physically.', 'The phone orders at the hardware shop are a market transaction, since the buyer and seller communicate and agree on price, product and delivery.', 'The walk-in, face-to-face sales at the same shop are also a market transaction, just conducted through a different channel of communication.', 'The book''s examples of markets, such as a flower market or online platforms like eBay or Amazon, show that markets can take many different physical or virtual forms.', 'Whether a customer contacts the hardware shop by phone or in person, both situations count as the same underlying concept: a market where an exchange is negotiated.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — This matches the book''s general definition of a market: buyers and sellers communicating the conditions of an exchange, regardless of physical presence.', 'TRUE — Phone orders where price, product and delivery are agreed constitute a market transaction under this definition.', 'TRUE — Face-to-face sales at the same shop are also a market transaction, simply using a different communication channel.', 'TRUE — The book''s own examples (a flower market, eBay, Amazon) show markets taking many physical or virtual forms.', 'TRUE — Whether by phone or in person, both are instances of the same underlying concept the book describes as a market.'], '2/5', 3, 'full' ),
( '2.6', 'CASE 2.6.04', 'A warehouse job posted on a recruitment platform', 'A logistics company posts a job opening for a warehouse worker on an online recruitment platform. Several candidates apply, and the company eventually agrees on a wage and start date with one applicant. A student is asked which type of market this illustrates and evaluates the following claims.', ARRAY['This scenario is an example of the labour market, where employers and workers negotiate the terms — such as wages — under which work will be exchanged for pay.', 'Because the negotiation happens online rather than at a physical job centre, the book says this cannot be considered a market of any kind.', 'This scenario should be classified as a housing market transaction, since it involves an online platform.', 'The company posting the job is acting as a buyer of housing services in this transaction, according to the book''s classification of market types.', 'Because only one candidate is hired, no market has actually taken place, since the book requires many buyers and many sellers to be present for something to count as a market.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Employers and workers agreeing on wages and terms for work is the book''s example of the labour market.', 'FALSE — The book gives online platforms (like eBay/Amazon) as valid examples of markets, so an online negotiation is still a market, including in the labour market.', 'FALSE — Negotiating a job and wage is a labour market transaction, not a housing market one; housing markets involve buildings or living space, not employment.', 'FALSE — The company is a buyer of labour (hiring a worker), not a buyer of housing services; this is a labour market transaction.', 'FALSE — The book does not require many buyers and many sellers to be simultaneously present for a single negotiated deal to count as a market exchange.'], '4/5', 4, 'full' ),
( '2.6', 'CASE 2.6.05', 'Rising rent for apartments near Marlow station', 'In the city of Marlow, more people want to rent apartments near the new train station than there are apartments available at the current rent. Landlords notice long queues of applicants for every vacancy and begin asking for higher rent, which most tenants reluctantly accept, while a few decide to look for housing further away.', ARRAY['This situation, where landlords near the station and tenants negotiate rent, is an example of the housing market, one of the market types described in the book.', 'More applicants wanting apartments than are available at the current rent describes a shortage, and the book explains that rising prices are one way markets respond to this.', 'As rent rises, according to the law of demand, at least some tenants are expected to look for cheaper housing further away rather than pay the higher price, all else being equal.', 'A shortage occurs, according to the book, when sellers offer more of a good than buyers want to purchase at the current price.', 'Rising rent near the station shows that landlords are ignoring supply and demand altogether and are instead following government price controls.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Landlords and tenants negotiating rent for apartments is the book''s example of the housing market.', 'TRUE — More applicants than available apartments at the current rent describes a shortage, and the book notes prices tend to rise in response to such imbalances.', 'TRUE — By the law of demand, a higher rent is expected to lead at least some tenants to seek cheaper alternatives, all else being equal.', 'FALSE — This describes a shortage (demand exceeding supply at the current price), not a surplus, which the book defines as supply exceeding demand at the current price.', 'FALSE — The scenario describes landlords responding to supply and demand themselves, not government-imposed price controls.'], '3/5', 5, 'full' ),
( '2.6', 'CASE 2.6.06', 'Sofia''s savings account and her uncle''s shares', 'Sofia deposits her savings into a bank account that pays her interest, while the bank uses depositors'' money to make loans to other customers. Separately, her uncle buys shares of a company through a stock exchange, hoping their value will rise over time. A finance class discusses which market types these situations belong to.', ARRAY['Sofia''s bank deposit and the bank''s lending activity relate to the money market, one of the market types described in the book where funds are supplied and demanded.', 'Her uncle buying company shares on a stock exchange relates to the capital market, where longer-term funding and investment are exchanged.', 'Because both examples involve money changing hands, the book classifies them as the exact same market type with no distinction between money and capital markets.', 'Sofia''s bank deposit should be classified as a commodity market transaction, since money is being handled like a physical good.', 'Buying shares on a stock exchange is, according to the book, an example of the labour market rather than the capital market.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Deposits and loans intermediated through a bank relate to the money market, one of the market types the book lists.', 'TRUE — Buying shares on a stock exchange relates to the capital market, where longer-term investment funds are exchanged.', 'FALSE — The book distinguishes the money market from the capital market; they are not treated as identical just because both involve money.', 'FALSE — A bank deposit is a money market transaction involving funds, not a commodity market transaction involving standardised physical goods.', 'FALSE — Buying shares is a capital market transaction, not a labour market one, since no work-for-wages exchange is involved.'], '3/5', 6, 'full' ),
( '2.6', 'CASE 2.6.07', 'Trading wheat and oil contracts on an exchange', 'On a global commodities exchange, traders buy and sell standardised contracts for wheat and crude oil, agreeing on price and quantity without ever seeing the physical grain or oil in person. A student researching different market types summarises what she has learned.', ARRAY['Trading standardised wheat and oil contracts on an exchange is an example of the commodity market, one of the market types mentioned in the book.', 'This is distinct from the labour market, where what is exchanged is work in return for wages, rather than raw materials or standardised goods.', 'It is also distinct from the housing market, where what is exchanged is the use or ownership of buildings and land.', 'The book lists several types of markets — including consumer, labour, housing, money, capital and commodity markets — each defined by what is being exchanged.', 'As with other markets described in the book, buyers and sellers in the commodity market communicate and agree on the conditions of exchange, even without meeting face-to-face.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Trading standardised wheat and oil contracts matches the book''s description of the commodity market.', 'TRUE — The labour market involves work exchanged for wages, which is a different type of exchange from trading raw materials.', 'TRUE — The housing market involves the use or ownership of buildings/land, distinct from commodity trading.', 'TRUE — The book lists consumer, labour, housing, money, capital and commodity markets as distinct types, defined by what is exchanged.', 'TRUE — As in other market types the book describes, communication and agreement between buyers and sellers define the commodity market too, even without face-to-face contact.'], '2/5', 7, 'full' ),
( '2.6', 'CASE 2.6.08', 'Trying on t-shirts at a clothing shop', 'A clothing shop sells t-shirts directly to everyday customers who walk in, try them on, and pay at the till. A student classifies this transaction for a homework assignment.', ARRAY['This t-shirt purchase is an example of the consumer market, where households buy goods and services for their own personal use.', 'Because clothing is involved, this must be classified as the labour market, since clothing is made by workers.', 'This transaction should be classified as the capital market, since money changes hands when the customer pays.', 'Since the shop is a business, the book classifies every sale it makes as part of the housing market rather than the consumer market.', 'Because the customer tries on the t-shirt before buying, the book says this cannot count as a market transaction, since trying on goods is excluded from its market definition.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Households buying goods for personal use, like t-shirts, is the book''s example of the consumer market.', 'FALSE — The consumer market is about goods bought for personal use; who manufactured the clothing does not reclassify the sale as a labour market transaction.', 'FALSE — Paying for a t-shirt at the till is a consumer market transaction, not a capital market one, since no investment or long-term financing is involved.', 'FALSE — A shop selling clothing to individual customers is a consumer market transaction; the book does not classify ordinary retail sales as the housing market.', 'FALSE — The book''s definition of a market does not exclude transactions simply because a customer tries on a product first.'], '2/5', 8, 'full' ),
( '2.6', 'CASE 2.6.09', 'A strawberry farmer''s harder-to-reach fields', 'A strawberry farmer notices that at a low price, he is only willing to harvest fruit from his best, easiest-to-reach fields. When the price rises, it becomes worthwhile for him to also harvest from further, harder-to-reach fields, even though picking there costs him more per basket. All other conditions, such as weather and demand for other fruits, stay the same.', ARRAY['The farmer offering more strawberries as the price rises illustrates the law of supply: as price increases, the quantity supplied tends to increase, ceteris paribus.', 'The fact that harvesting from the harder-to-reach fields costs more per basket reflects the book''s idea that producing additional units often involves rising marginal cost.', 'The phrase ''ceteris paribus'' in this context means that other factors, such as weather or demand for other fruit, are assumed to stay unchanged while we consider the effect of price on quantity supplied.', 'Because harvesting the extra fields costs more, the farmer would only be willing to supply that extra amount if the higher price makes it worthwhile, which is consistent with the law of supply.', 'The law of supply, as described in the book, states that as the price of a good rises, sellers are generally willing to offer less of it.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Offering more strawberries as price rises, other things equal, illustrates the law of supply.', 'TRUE — Higher cost per basket from harder-to-reach fields reflects the book''s idea of rising marginal cost as more is produced.', 'TRUE — ''Ceteris paribus'' means other relevant factors are held constant while examining the price–quantity relationship, exactly as used here.', 'TRUE — The farmer only harvests the costlier fields because the higher price makes it worthwhile, matching the logic behind the law of supply.', 'FALSE — The law of supply states that as price rises, sellers are generally willing to supply more, not less; this statement reverses the relationship.'], '3/5', 9, 'full' ),
( '2.6', 'CASE 2.6.10', 'A €2 cone becomes a €3.50 cone at the beach', 'At a beachside kiosk, an ice cream cone costs €2 and sells briskly on hot days. When the owner raises the price to €3.50 during a heatwave to see what happens, fewer customers buy a cone, even though the weather is just as hot as before.', ARRAY['Fewer people buying ice cream after the price rise, with weather held constant, illustrates the law of demand: as price rises, quantity demanded tends to fall, all else being equal.', 'The book links the law of demand partly to the idea that each additional unit of a good tends to bring the buyer somewhat less additional satisfaction or utility, making a higher price less worth paying.', 'Because the weather stayed the same, the drop in ice cream sales after the price increase can reasonably be attributed mainly to the price change rather than to the weather.', 'The law of demand states that as the price of a good falls, buyers are generally willing to purchase less of it.', 'Since some customers still bought ice cream at €3.50, the law of demand must be false, because it predicts that literally nobody would buy the good after any price increase.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Fewer cones bought at the higher price, weather held constant, illustrates the law of demand.', 'TRUE — The book links demand partly to diminishing additional satisfaction from extra units, making a higher price less attractive.', 'TRUE — With weather constant, the price change is the reasonable explanation for the drop in quantity demanded.', 'FALSE — The law of demand states that as price falls, buyers are generally willing to buy more, not less; this reverses the relationship.', 'FALSE — The law of demand describes a general tendency for quantity demanded to fall as price rises, not that demand must fall to exactly zero; some customers still buying is not a contradiction.'], '3/5', 10, 'full' ),
( '2.6', 'CASE 2.6.11', 'Weekly apple prices settle at the Millbrook market', 'At the Saturday market in Millbrook, apple sellers gradually adjust their price each week. When they set the price too high, apples are left unsold at the end of the day; when they set it too low, they run out early with customers still waiting. Eventually they settle on a price where, most weeks, the apples on offer are roughly matched by the amount customers want to buy.', ARRAY['The price where the quantity of apples offered roughly matches the quantity customers want to buy is what the book calls the equilibrium or market price.', 'Apples being left unsold at the end of the day when the price is set too high is an example of a surplus, since sellers offered more than buyers wanted at that price.', 'Running out of apples early when the price is too low is what the book calls a surplus, since sellers had prepared too much stock.', 'Because the sellers adjust prices themselves rather than a central authority, this process cannot lead to anything the book would call an equilibrium price.', 'Once the equilibrium price is reached, sellers have no further reason to ever change their price again, even later on if demand or costs shift, since the book states equilibrium is permanent and unaffected by shifts.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — The price at which quantity offered roughly matches quantity wanted is the book''s definition of the equilibrium or market price.', 'TRUE — Unsold apples at a high price is the book''s example of a surplus: quantity supplied exceeds quantity demanded at that price.', 'FALSE — Running out early at a low price is a shortage (quantity demanded exceeds quantity supplied), not a surplus; the statement mislabels the situation.', 'FALSE — The book describes equilibrium as arising from the independent adjustments of buyers and sellers themselves, not only from central authorities; sellers adjusting their own prices can still reach equilibrium.', 'FALSE — Equilibrium reflects a balance under current conditions; if demand or costs later shift, the book would expect the equilibrium price to shift too, not stay fixed forever.'], '4/5', 11, 'full' ),
( '2.6', 'CASE 2.6.12', 'Unsold umbrellas during a dry season', 'A shop imports a large batch of umbrellas priced at €25 each, expecting a rainy season. Instead, the weather stays dry for weeks, and only a handful of umbrellas sell at that price. Shelves remain full of unsold umbrellas until the shop drops the price to €12, after which sales pick up noticeably.', ARRAY['At €25, with only a handful selling and most remaining unsold, the shop faces a surplus: the quantity supplied exceeds the quantity customers want to buy at that price.', 'Cutting the price to €12 to move the unsold stock is consistent with the book''s idea that falling prices can help resolve a surplus by encouraging more buyers to purchase.', 'According to the law of demand, more customers being willing to buy umbrellas at €12 than at €25 is expected, since a lower price tends to increase quantity demanded, ceteris paribus.', 'If, instead, the shop had priced umbrellas very low during a sudden downpour and quickly sold out with customers still wanting more, that would have been an example of a shortage rather than a surplus.', 'Surpluses and shortages, as described in the book, arise when the price charged differs from the equilibrium (market) price at which quantity supplied and quantity demanded would roughly match.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Unsold umbrellas at €25 describe a surplus: quantity supplied exceeds quantity demanded at that price.', 'TRUE — Lowering the price to sell excess stock matches the book''s description of how surpluses tend to be resolved.', 'TRUE — More buying at the lower price is consistent with the law of demand.', 'TRUE — Selling out quickly with unmet demand describes a shortage, the opposite imbalance from a surplus.', 'TRUE — Both surpluses and shortages arise, per the book, when the price charged differs from the equilibrium price.'], '2/5', 12, 'full' ),
( '2.6', 'CASE 2.6.13', 'A concert sells out in minutes', 'A band releases concert tickets at €40 each. They sell out within minutes, and resale sites later show people offering far more than €40 to buy tickets from others, since far more fans wanted tickets than the venue had seats for.', ARRAY['Tickets selling out immediately at €40, with many more fans still wanting them, describes a shortage: quantity demanded exceeded quantity supplied at that price.', 'Tickets selling out quickly proves that the venue set the price too high relative to what fans were willing to pay.', 'This situation describes a surplus, since the venue had prepared a large supply of seats in advance.', 'Because resale prices are higher than €40, this shows that the original €40 price was above the equilibrium price for the tickets.', 'According to the law of supply, ticket sellers would be expected to offer fewer tickets as the price of tickets rises, which is why fans could not get tickets.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Fans wanting far more tickets than available at €40 describes a shortage: quantity demanded exceeds quantity supplied at that price.', 'FALSE — Selling out quickly shows demand exceeded supply at that price; it does not by itself prove the price was ''too high'' — if anything it suggests it was below what many fans were willing to pay.', 'FALSE — This is a shortage, not a surplus; a surplus would mean unsold tickets remaining, not fans left wanting more.', 'FALSE — Higher resale prices suggest the original price was below, not above, the equilibrium price, since demand clearly exceeded the supply available at €40.', 'FALSE — The law of supply concerns how much sellers offer as price changes; it does not explain why fans could not get tickets, which is a demand-side shortage at a fixed original price.'], '4/5', 13, 'full' ),
( '2.6', 'CASE 2.6.14', 'A pay rise and a trending pasta dish', 'After receiving a pay rise, several employees at a factory start eating lunch at a nearby restaurant more often, even though the restaurant has not changed its prices. Around the same time, a popular cooking show makes a particular pasta dish trendy, and the same restaurant notices many more customers specifically ordering that dish, again with no price change.', ARRAY['Employees eating out more often after a pay rise, with the restaurant''s prices unchanged, illustrates how a rise in income can shift demand for a good, as described in the book.', 'More customers ordering the trendy pasta dish without any price change illustrates how a shift in preferences or tastes can also shift demand for a good.', 'Both examples are demand shifters rather than movements caused by a change in the restaurant''s own price, since the price stayed the same in each case.', 'According to the book, income and preferences are among the factors, besides price, that can shift the demand for a good.', 'Because the restaurant''s price did not change, the book would say these changes in customer behaviour cannot be linked to demand at all.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — More lunches bought after a pay rise, with prices unchanged, illustrates income as a demand shifter.', 'TRUE — More orders of a trendy dish without a price change illustrates preferences/tastes as a demand shifter.', 'TRUE — Since the restaurant''s own price stayed the same in both cases, these are shifts of demand rather than movements caused by price.', 'TRUE — The book lists income and preferences among the non-price factors that can shift demand.', 'FALSE — The book does not require a price change for something to be linked to demand; shifts in demand are specifically changes that occur without a change in the good''s own price.'], '3/5', 14, 'full' ),
( '2.6', 'CASE 2.6.15', 'Coffee beans get pricier; tea and filters react', 'When the price of coffee beans rises sharply, some coffee drinkers switch to buying tea instead, so demand for tea increases even though tea''s own price has not changed. At the same time, demand for coffee filters falls, since people are brewing less coffee at home.', ARRAY['Tea being bought more often after coffee becomes pricier is an example of a substitute good: when the price of coffee rises, demand shifts toward tea.', 'Coffee filters being bought less often as people brew less coffee is an example of a complementary good: demand for a good used alongside coffee falls when less coffee is bought.', 'Both the tea and coffee-filter examples show that a good''s demand can shift due to changes in the price of a different, related good, not only its own price.', 'Because tea''s own price did not change, the book would say demand for tea could not possibly increase in this situation.', 'According to the book, coffee and coffee filters are examples of substitute goods, since they are bought around the same time.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Buyers switching to tea when coffee becomes pricier illustrates tea as a substitute for coffee.', 'TRUE — Falling demand for coffee filters as coffee brewing declines illustrates filters as a complement to coffee.', 'TRUE — Both examples show demand shifting due to another good''s price, one of the demand shifters the book describes besides a good''s own price.', 'FALSE — The book explains demand for a good can shift due to the price of a related substitute good, even without any change in the good''s own price; that is exactly the mechanism described here.', 'FALSE — Coffee and coffee filters are used together, making them complements, not substitutes; substitutes are goods that can replace one another, like coffee and tea.'], '3/5', 15, 'full' ),
( '2.6', 'CASE 2.6.16', 'A second bakery opens in Lindwick', 'For years, only one bakery served the town of Lindwick, and it supplied a certain number of loaves each day. When a second bakery opens nearby, the total number of loaves offered for sale in town each day rises noticeably, even though bread prices have not changed yet.', ARRAY['The total quantity of bread supplied in Lindwick increasing after a second bakery opens, with prices unchanged, illustrates how the number of suppliers can shift the overall supply of a good.', 'This is an example of a supply shifter rather than a movement along the supply curve, since bread''s own price did not change when the extra bakery opened.', 'According to the book, the number of suppliers in a market has no effect on the total quantity of a good supplied, only prices do.', 'Because a second bakery opened, the book would classify this as a change in demand for bread rather than a change in supply.', 'If the new bakery later closed down, the book would predict that the total supply of bread in town would rise even further, all else equal.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — More total bread offered after a new bakery opens illustrates the number of suppliers as a supply shifter.', 'TRUE — Since bread''s own price did not change, this is a shift of supply rather than a movement along the supply curve.', 'FALSE — The book explicitly lists the number of suppliers as one of the factors that can shift supply, alongside price.', 'FALSE — A change in the amount of bread supplied because of a new competing bakery is a supply-side change, not a demand-side one.', 'FALSE — The book would expect the opposite: fewer suppliers (the bakery closing) would tend to decrease total supply, not increase it further.'], '3/5', 16, 'full' ),
( '2.6', 'CASE 2.6.17', 'A new cutting machine at the furniture workshop', 'A furniture workshop invests in a new automated cutting machine that lets it produce chairs faster and more cheaply than with its old hand tools. Even before changing its selling price, the workshop finds it can now offer a larger quantity of chairs for sale each month than before.', ARRAY['The workshop being able to offer more chairs each month after adopting new technology, without changing price, illustrates how technology can shift supply, as described in the book.', 'Because production has become cheaper and faster, the workshop can profitably offer a larger quantity at the same price as before, which is consistent with an increase in supply.', 'This technology-driven change in supply is different from a movement along the supply curve, since the chair''s own price was not the trigger for the change in quantity offered.', 'The book lists factors such as the number of suppliers, technology, the price of resources used in production, and expectations about future prices as things that can shift supply besides the good''s own price.', 'If, instead, the price of the wood used to make chairs had risen sharply, the book would expect this to work in the opposite direction, tending to decrease supply rather than increase it.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Producing and offering more chairs after adopting new technology, without a price change, illustrates technology as a supply shifter.', 'TRUE — Cheaper, faster production allows a larger quantity to be profitably supplied at the same price, consistent with an increase in supply.', 'TRUE — Since the chair''s own price did not trigger the change, this is a shift of the whole supply relationship rather than a movement along it.', 'TRUE — The book lists number of suppliers, technology, resource prices, and price expectations as supply shifters besides a good''s own price.', 'TRUE — A rise in the price of a key input like wood would, per the book, be expected to decrease supply, the opposite effect of the technology improvement.'], '2/5', 17, 'full' ),
( '2.6', 'CASE 2.6.18', 'Cocoa bean prices squeeze a chocolate maker', 'A small chocolate maker relies on imported cocoa beans. When the world price of cocoa beans rises sharply, the chocolate maker finds it more expensive to produce each bar of chocolate and decides to offer fewer bars for sale at the same retail price as before.', ARRAY['The chocolate maker offering fewer bars after cocoa bean prices rose, with the chocolate''s own retail price unchanged, illustrates how a rise in the price of a key resource can decrease supply.', 'According to the book, a rise in the price of an input like cocoa beans should cause supply of chocolate to increase, since higher costs always lead producers to offer more.', 'Because the retail price of chocolate did not change, the book would say this cannot be an example of a shift in supply at all.', 'This situation should be classified as a shift in demand for chocolate, since demand and supply are affected by the exact same factors in the book.', 'If cocoa bean prices had instead fallen sharply, the book would predict that the chocolate maker would want to offer fewer bars for sale, all else equal.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Producing and offering fewer bars after cocoa prices rose, with the retail price unchanged, illustrates resource prices as a supply shifter that decreases supply.', 'FALSE — The book explains that a rise in the price of an input generally decreases supply, since production becomes more costly, not the reverse.', 'FALSE — A supply shift does not require the good''s own retail price to change; shifts caused by resource prices happen independently of the good''s own price.', 'FALSE — This is a supply-side change caused by input costs, not a demand-side change; demand and supply respond to different, though sometimes overlapping, sets of factors in the book.', 'FALSE — The book would expect falling input prices to make production cheaper and encourage suppliers to offer more, not fewer, bars, all else equal.'], '4/5', 18, 'full' ),
( '2.6', 'CASE 2.6.19', 'Grain farmers bet on higher prices ahead', 'In late summer, grain farmers hear forecasts suggesting that grain prices are likely to rise significantly in a few months. Even though today''s price has not changed yet, several farmers decide to store part of their harvest in silos instead of selling it all right away, planning to sell later once prices go up.', ARRAY['Farmers holding back grain today because they expect higher prices later illustrates how expectations about future prices can shift current supply, as described in the book.', 'Because today''s price has not changed, the reduction in grain offered for sale right now is a shift in supply caused by expectations, not a movement along the supply curve triggered by today''s price.', 'If farmers instead expected prices to fall sharply in the future, the book would expect at least some of them to want to sell more now rather than later, all else equal.', 'Price expectations are one of the factors, alongside number of suppliers, technology, and resource prices, that the book lists as able to shift supply.', 'According to the book, farmers'' expectations about future prices have no relevance to how much grain they are willing to supply today.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Farmers reducing sales today because they expect higher prices later illustrates price expectations as a supply shifter.', 'TRUE — Since today''s price is unchanged, the reduced quantity offered now reflects a shift in supply driven by expectations, not a price-driven movement along the curve.', 'TRUE — Expecting future prices to fall would, per the book''s logic, encourage selling more now rather than waiting, the opposite effect of expecting a rise.', 'TRUE — The book lists price expectations alongside number of suppliers, technology, and resource prices as factors that can shift supply.', 'FALSE — The book explicitly treats expectations about future prices as relevant to current supply decisions; farmers do act on such expectations.'], '3/5', 19, 'full' ),
( '2.6', 'CASE 2.6.20', 'Feldmoor''s rising prices and a rate hike', 'In the country of Feldmoor, the amount of money in circulation grows quickly for several years, while the number of goods and services being produced grows much more slowly. Shoppers notice that, on average, prices keep creeping up across many different goods, month after month. The central bank eventually responds by raising its key interest rate.', ARRAY['Feldmoor''s situation, where the money supply grows much faster than the amount of goods and services produced, matches the book''s description of inflation as, in simple terms, too many dollars chasing too few goods.', 'By raising interest rates, the central bank makes borrowing more expensive, which the book suggests should discourage some borrowing and spending.', 'Reduced borrowing and spending after the interest rate rise is meant, according to the book, to help slow the pace at which overall prices are rising.', 'According to the book, raising interest rates is expected to encourage households and businesses to borrow and spend more, which would fight inflation by increasing demand further.', 'Inflation, as described in the book, means that prices for every single good fall at exactly the same rate across the whole economy.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Money supply growing much faster than output, with broad price rises, matches the book''s simple description of inflation as too many dollars chasing too few goods.', 'TRUE — Higher interest rates make borrowing more expensive, which the book links to discouraging some borrowing and spending.', 'TRUE — Reduced borrowing and spending is the mechanism the book describes for how higher interest rates can help slow rising prices.', 'FALSE — The book explains that higher interest rates are meant to discourage, not encourage, borrowing and spending, thereby easing demand-driven price pressure.', 'FALSE — Inflation refers to a general, average rise in prices across many goods, not that every single price falls at an identical rate; the book does not describe inflation this way.'], '3/5', 20, 'full' ),
( '2.7', 'CASE 2.7.01', 'A fjord tollbridge and rows of near-identical fuel stations', 'In a Norwegian fjord region, a single company operates the only road tollbridge connecting two peninsulas, and the nearest alternative crossing is a ferry detour lasting about ninety minutes. Along the same highway, several roadside stations sell virtually identical diesel fuel at similar prices, and drivers switch between them without any real inconvenience. Evaluate the following statements using the book''s concepts of monopoly and near-perfect competition.', ARRAY['The tollbridge company is the only crossing point for that stretch of fjord, so it holds a local monopoly-like position even though many other bridges exist elsewhere in Norway.', 'Because drivers could instead take the ninety-minute ferry detour, the tollbridge automatically faces the book''s full theoretical model of perfect competition.', 'The diesel sold at the several roadside stations is close to identical, and with many outlets and easy switching between them, this local fuel market can come closer to near-perfect competition even though few real markets satisfy every theoretical condition exactly.', 'Perfect competition, as the book defines it, only requires that there are many sellers; full information, free entry and exit, and the absence of personal preference are not part of that definition.', 'If the tollbridge company could largely set its own price without losing many customers, that pricing power is itself a sign of weaker competition compared with a market that has many substitutable suppliers.'], ARRAY[true, false, true, false, true], ARRAY['TRUE — The book''s local monopoly-like idea applies to being the sole supplier within a relevant area (comparable to the ski-hut or theatre-bar examples), even if other bridges exist nationally.', 'FALSE — Having one distant, slower substitute does not create the book''s perfect competition, which needs many suppliers, full information, no entry/exit barriers and no personal preference; one ferry detour only slightly weakens, but does not remove, the monopoly-like position.', 'TRUE — Many outlets selling an almost identical, easily comparable product fits the book''s idea of a near-perfect competitive market, even though the book notes real markets rarely meet every criterion perfectly.', 'FALSE — The book lists several conditions for perfect competition together: many players so none influence price, full information, no entry/exit barriers, and no personal preference; having many sellers alone is not sufficient.', 'TRUE — Competition level depends on supplier numbers and substitute availability; a supplier able to set its own price largely unchecked signals weaker competition than one facing many comparable rivals.'], '3/5', 1, 'full' ),
( '2.7', 'CASE 2.7.02', 'A national railway line and three fast-moving domestic airlines', 'In a small European country, the national railway company owns the only mainline tracks connecting the capital to the northern border, a case similar to the book''s own railway example of monopoly; competing bus companies exist but take roughly twice as long door-to-door. Separately, three domestic airlines each hold a sizeable share of the short-haul flight market and are known to adjust their fares within hours of a rival''s announcement. Evaluate the statements using the book''s concepts of monopoly, oligopoly and cartels.', ARRAY['The railway company is a typical example of monopoly, since it is the sole supplier of that particular mainline rail service.', 'Competition level depends both on how many suppliers exist and on how available substitutes are, so the slower bus alternative weakens, without eliminating, the railway''s monopoly-like position.', 'The three domestic airlines, each holding a large market share and adjusting fares quickly in response to rivals, fit the book''s description of an oligopoly.', 'If the three airlines instead sat down and jointly fixed ticket prices to avoid competing, this would typically count as a cartel, which the book treats as generally illegal because competition laws are designed to protect customers.', 'A single supplier of a good or service, such as the railway here, is described in the book as a rare market structure in real life, since most goods have at least some competitors.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — The book uses a railway example to illustrate monopoly: a sole supplier of that specific service.', 'TRUE — The book ties competition level to both the number of suppliers and substitute availability; a slower substitute reduces but does not remove monopoly-like power.', 'TRUE — Oligopoly is defined in the book as a market with few suppliers each holding a relatively large share, with telecom and car-making cited as examples; airlines reacting quickly to rivals fits the same pattern.', 'TRUE — Negotiating shared prices instead of competing matches the book''s description of a cartel, generally viewed as illegal because laws are meant to support competition for customers'' benefit.', 'TRUE — The book notes that monopoly, a single supplier with no competitors, is rare in real life.'], '3/5', 2, 'full' ),
( '2.7', 'CASE 2.7.03', 'A tulip auction clock and a village''s only bakery', 'At a large flower auction, hundreds of independent tulip growers sell nearly identical bunches to hundreds of buyers each morning, with running prices displayed on a giant clock visible to everyone in the hall. Separately, a family-run bakery is the only bakery within fifty kilometres of a remote coastal village. Evaluate the statements using the book''s concepts of perfect competition and monopoly.', ARRAY['Because hundreds of growers sell nearly identical tulips to hundreds of buyers with openly visible prices, this auction is a real-world market that meets the book''s theoretical model of perfect competition in every single respect, without any exception.', 'The remote bakery, being the only one within fifty kilometres, fits the book''s example of a local monopoly-like supplier even though other bakeries exist across the country.', 'Perfect competition requires that buyers and sellers are so numerous that no single one can influence the market price, and the tulip auction''s visible price clock actually works against this, since it lets a handful of big buyers dictate the price for everyone else.', 'Because the flower auction has so many sellers, it must automatically be an oligopoly rather than a market approaching perfect competition.', 'A single remote bakery and a large flower auction necessarily represent the same level of competition, since both involve only one type of product being sold.'], ARRAY[false, true, false, false, false], ARRAY['FALSE — The book presents perfect competition as a theoretical model that real markets rarely, if ever, fulfil completely; claiming zero exceptions overstates even a near-perfect example like this auction.', 'TRUE — Being the sole supplier within a defined local area matches the book''s local monopoly-like examples, regardless of bakeries existing elsewhere.', 'FALSE — The auction''s visible clock reflects aggregate supply and demand among many participants rather than a few big buyers dictating price; that is the opposite of what undermines perfect competition.', 'FALSE — Oligopoly is defined by few suppliers with large shares; a market with hundreds of sellers is the opposite structure and instead approaches perfect competition.', 'FALSE — Competition level depends on supplier numbers and substitute availability for each specific market, not on how many product types are involved; a sole local bakery and a market with hundreds of sellers sit at opposite ends of the book''s spectrum.'], '5/5', 3, 'full' ),
( '2.7', 'CASE 2.7.04', 'Two dominant grocery chains and a handful of corner shops', 'In a small landlocked alpine country, two supermarket chains together account for the vast majority of grocery sales, and shoppers notice that when one chain runs a discount campaign, the other typically matches it within days. A handful of independent corner shops also operate in the capital, but they hold only a tiny combined share. Evaluate the statements using the book''s concepts of oligopoly, cartels and perfect competition.', ARRAY['Because only two chains hold the large majority of grocery sales, this is an example of an oligopoly rather than perfect competition.', 'The tendency of one chain to match the other''s discount campaigns within days illustrates the strong reaction to competitors'' moves that the book associates with oligopoly.', 'If the two chains instead agreed privately on shared minimum prices to avoid discount wars, that arrangement would typically be viewed as an illegal cartel under competition law.', 'The presence of a handful of independent corner shops with a tiny combined share means this grocery market already meets the book''s definition of perfect competition.', 'Competition laws in most countries exist partly to prevent this kind of grocery duopoly from freely restricting competition, since the book states such laws support competition because it benefits customers.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — Two suppliers holding the large majority of sales matches the book''s oligopoly definition of few suppliers with large market shares.', 'TRUE — Quickly matching a rival''s discount campaign is the strong competitive reaction the book links to oligopoly.', 'TRUE — Privately agreeing on shared prices instead of competing fits the book''s description of a cartel, usually treated as illegal.', 'FALSE — Perfect competition needs many sellers none of which can influence price, full information, no entry/exit barriers and no personal preference; two dominant chains plus a few tiny shops do not meet this.', 'TRUE — The book states that competition laws exist because rivalry between suppliers is generally seen as beneficial to customers.'], '3/5', 4, 'full' ),
( '2.7', 'CASE 2.7.05', 'A Highlands pharmacy and three undercutting city supermarkets', 'In a sparsely populated stretch of the Scottish Highlands, one small pharmacy is the only place to buy prescription medicine within fifty kilometres, with the next-nearest pharmacy reached only via a single-lane mountain road. Separately, three large supermarket chains in the nearest city compete fiercely for grocery customers and frequently undercut each other''s advertised prices. Evaluate the statements using the book''s concepts of monopoly, oligopoly, cartels and perfect competition.', ARRAY['The Highlands pharmacy being the sole supplier within fifty kilometres matches the book''s description of a local monopoly-like position, similar to the ski-hut or theatre-bar examples.', 'Because there is technically another pharmacy somewhere in the country, the Highlands pharmacy cannot be considered monopoly-like under the book''s definition, no matter how far away that other pharmacy is.', 'The three supermarket chains undercutting each other''s prices in the city are, by that description alone, engaged in an illegal cartel.', 'Fierce price competition among only three chains does not by itself prove the grocery market is close to perfect competition, since the book''s version of perfect competition also requires very many sellers, full information, and no entry or exit barriers.', 'A market can only ever be classified by the book as either a pure monopoly or perfect competition, with no other categories available.'], ARRAY[true, false, false, true, false], ARRAY['TRUE — The book''s local monopoly-like examples cover being the sole realistic supplier within a defined area, even if distant alternatives exist nationally.', 'FALSE — The book explicitly allows local monopoly-like status despite other suppliers existing elsewhere, especially when reaching them is impractical.', 'FALSE — Undercutting each other''s prices is active competition, the opposite of a cartel, which requires suppliers to agree together instead of competing.', 'TRUE — The book lists multiple conditions for perfect competition together — many sellers, full information, no barriers, no personal preference — so three fiercely competing chains alone are not enough.', 'FALSE — The book also recognises oligopoly (few suppliers with large shares) as a distinct category between monopoly and perfect competition.'], '4/5', 5, 'full' ),
( '2.7', 'CASE 2.7.06', 'A handful of advanced chip foundries and a pricing investigation', 'In the global semiconductor industry, only a handful of foundries have the technology to manufacture the most advanced computer chips, and each holds a substantial share of that specialised market; when one raises prices, competitors have historically followed within a similar timeframe. Regulators in several countries have investigated whether some of these foundries ever discussed prices together instead of competing independently. Evaluate the statements using the book''s concepts of oligopoly and cartels.', ARRAY['A market dominated by a handful of large suppliers, each with a substantial share, matches the book''s definition of an oligopoly.', 'The pattern of competitors following a price rise within a similar timeframe illustrates the strong reaction to rivals'' moves that the book links to oligopolistic markets.', 'If regulators found that some foundries had secretly discussed prices together instead of competing, this would fit the book''s description of a cartel, which is usually treated as illegal.', 'Competition level depends both on how many suppliers exist and on how available substitutes are, and with only a handful of firms capable of the most advanced manufacturing, the availability of real substitutes for that specific technology is limited.', 'Laws that support competition exist, according to the book, because vigorous rivalry between suppliers is generally seen as beneficial to customers.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Few large suppliers each with a substantial share is exactly the book''s definition of oligopoly.', 'TRUE — Following a rival''s price change quickly is the strong reactive behaviour the book associates with oligopoly.', 'TRUE — Secretly agreeing on prices instead of competing matches the book''s cartel description, usually illegal.', 'TRUE — The book explains competition level as a function of supplier numbers and substitute availability; few firms with unique advanced technology means few real substitutes.', 'TRUE — The book states competition laws exist because rivalry between suppliers is seen as good for customers.'], '3/5', 6, 'full' ),
( '2.7', 'CASE 2.7.07', 'A certified wheat exchange and a signature sourdough loaf', 'On an international commodity exchange, wheat of a single certified grade is traded by thousands of farmers and thousands of buyers, with prices published instantly online for anyone to see, and any farmer or trading firm can start buying or selling that grade with minimal restrictions. A separate specialty bakery two streets away sells a signature sourdough loaf that regular customers say tastes different from any other bakery in town. Evaluate the statements using the book''s concepts of perfect competition and oligopoly.', ARRAY['The wheat exchange''s combination of many traders, freely available price information, and low barriers to entry brings it closer to the book''s theoretical model of perfect competition than most real markets manage.', 'Perfect competition, as defined in the book, also requires that buyers have no personal preferences between suppliers because the goods on offer are essentially replaceable, a condition the standardised wheat grade broadly satisfies.', 'The specialty bakery''s uniquely flavoured sourdough loaf illustrates the personal-preference element that the book says prevents most real markets, including this one, from being genuinely perfectly competitive.', 'Because thousands of farmers trade on the wheat exchange, it must be an oligopoly, since oligopoly in the book is defined by having a very large number of participants.', 'Since perfect competition is only a theoretical model, the book states that no real market can ever come reasonably close to resembling it.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Many traders, transparent prices, and easy entry are exactly the conditions the book lists for approaching perfect competition.', 'TRUE — The book requires no personal preference and replaceable goods for perfect competition; a single certified grade satisfies this.', 'TRUE — A uniquely flavoured, branded product is the personal-preference/differentiation factor the book says keeps most real markets away from perfect competition.', 'FALSE — Oligopoly in the book means few suppliers with large shares, the opposite of the wheat exchange''s very large number of participants.', 'FALSE — The book notes that near-identical, standardised goods such as agricultural products can come close to perfect competition in real life, even if it is rarely achieved exactly.'], '4/5', 7, 'full' ),
( '2.7', 'CASE 2.7.08', 'The only hut on an isolated ski slope', 'At the top of an isolated ski slope reachable only by a single chairlift, one hut sells the only hot food and drinks available to skiers all day; the nearest alternative restaurant is at the base of the mountain, a forty-five-minute descent away. This mirrors the book''s own classic example of local, monopoly-like supply. Evaluate the statements using the book''s concepts of monopoly, competition level and cartels.', ARRAY['Because skiers could theoretically descend forty-five minutes to reach another restaurant, the hut faces just as much competition as a restaurant in a city centre surrounded by dozens of eateries.', 'The hut''s position as the sole food supplier reachable on the slope itself matches the book''s own ski-hut example of a local, monopoly-like supplier.', 'A monopoly, according to the book, is actually a very common market structure that most goods and services fall under in everyday life.', 'Since the chairlift only allows one route up the mountain, this scarcity of transport access automatically makes the hut a participant in an illegal cartel.', 'If a second, identical hut opened right next to the first one at the summit, the level of competition there would stay exactly the same as before, since the book says the number of suppliers never affects competition level.'], ARRAY[false, true, false, false, false], ARRAY['FALSE — A forty-five-minute descent is a far weaker substitute than dozens of nearby eateries; competition level reflects realistic substitute availability, which is not equivalent here.', 'TRUE — This is the book''s own ski-hut example of a sole local supplier being monopoly-like.', 'FALSE — The book describes monopoly, a single supplier with no competitors, as a rare market structure, not a common one.', 'FALSE — A cartel requires multiple suppliers agreeing together; a sole supplier constrained by geography is monopoly-like, not a cartel.', 'FALSE — The book states competition level is shaped by the number of suppliers and substitute availability, so adding a second supplier would change the level of competition.'], '4/5', 8, 'full' ),
( '2.7', 'CASE 2.7.09', 'Three mobile operators and a suspiciously similar price list', 'In a mid-sized European country, three mobile network operators together serve almost the entire population, each holding a substantial share of subscribers, and whenever one launches a cheaper data plan the others typically respond with a similar offer within weeks. Consumer groups have occasionally accused the operators of keeping prices unusually similar across the market. Evaluate the statements using the book''s concepts of oligopoly, cartels and perfect competition.', ARRAY['Three operators each holding a substantial share of subscribers fits the book''s description of an oligopoly, alongside its own examples of telecom and car-making markets.', 'The pattern of operators matching each other''s cheaper data plans within weeks illustrates the strong reaction between rivals that the book associates with oligopolistic competition.', 'If consumer groups'' suspicion were confirmed and the operators had actually agreed together to keep prices similar rather than compete, that would match the book''s description of a cartel, which is usually illegal.', 'Because there are only three operators, this market automatically satisfies the book''s requirement that no single supplier can influence the price, which is a hallmark of perfect competition.', 'Competition laws exist partly to prevent arrangements like undisclosed price coordination between the operators, because the book states such laws are meant to support competition for the benefit of customers.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — The book names telecoms directly as a typical oligopoly example: few suppliers, large shares each.', 'TRUE — Quickly matching a rival''s cheaper plan is the reactive rivalry the book links to oligopoly.', 'TRUE — Agreeing together on prices instead of competing fits the book''s cartel description, generally illegal.', 'FALSE — Having only three suppliers is the opposite of perfect competition''s requirement of many players none of which can influence price; oligopoly members typically can and do influence price and each other''s behaviour.', 'TRUE — The book states competition laws exist because rivalry, not coordination, is generally better for customers.'], '3/5', 9, 'full' ),
( '2.7', 'CASE 2.7.10', 'A dozen potters with distinctive glazes beside a napkin stall', 'At a weekly street fair, a dozen independent potters sell handmade ceramic mugs and bowls, each with distinctive glazes and shapes that regular customers say they can recognise from a distance. A separate stall two rows away sells plain white paper napkins that are essentially identical to napkins sold at every other stall in the fair. Evaluate the statements using the book''s concepts of perfect competition and oligopoly.', ARRAY['Because a dozen potters sell in the same market, this automatically meets the book''s definition of perfect competition regardless of how different their products look.', 'The fact that regular customers can recognise individual potters'' distinctive styles shows the personal-preference element that the book says works against a market being genuinely perfectly competitive.', 'The plain, identical paper napkins sold at every stall are closer to the book''s idea of replaceable goods without personal preference than the distinctive ceramic mugs are.', 'A dozen independent sellers is, according to the book, always classified as an oligopoly no matter what else is true about the market.', 'Since the potters compete for the same customers at the same fair, the book would describe them as operating a cartel.'], ARRAY[false, true, true, false, false], ARRAY['FALSE — Perfect competition also requires replaceable goods and no personal preference; distinctive, recognisable glazes work against that condition even with many sellers.', 'TRUE — Customers favouring particular potters'' recognisable styles is exactly the personal-preference factor the book says weakens perfect competition.', 'TRUE — Identical, unbranded napkins fit the book''s replaceable-goods, no-preference condition much better than distinctive handmade ceramics.', 'FALSE — Oligopoly in the book means few suppliers with large market shares, not simply any small headcount of independent sellers at a local fair.', 'FALSE — Competing for the same customers is ordinary rivalry, the opposite of a cartel, which requires suppliers to agree together instead of competing.'], '4/5', 10, 'full' ),
( '2.7', 'CASE 2.7.11', 'A continent''s steel producers and an antitrust inquiry', 'Across a continent, a small number of large steel producers account for most industrial steel output, and analysts note that these producers tend to announce price changes within days of one another rather than compete aggressively on price. Government antitrust investigators have periodically examined whether producers ever coordinated output levels to keep prices higher than they would otherwise be. Evaluate the statements using the book''s concepts of oligopoly and cartels.', ARRAY['A small number of large producers accounting for most of an industry''s output matches the book''s definition of an oligopoly.', 'Producers announcing price changes within days of each other, rather than undercutting aggressively, illustrates the strong reaction among rivals that the book links to oligopoly.', 'If investigators found producers had coordinated output levels to keep prices artificially high, that would match the book''s description of a cartel.', 'The book treats cartel-style agreements between suppliers as usually illegal because competition laws are designed to work in customers'' favour.', 'Competition level depends on the number of suppliers and the availability of substitutes, and with only a small number of large steel producers, the number-of-suppliers factor here points toward weaker competition than a market with many small producers would.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Few large suppliers dominating most output matches the book''s oligopoly definition.', 'TRUE — Announcing price changes in near lockstep instead of competing aggressively is the reactive pattern the book associates with oligopoly.', 'TRUE — Coordinating output to keep prices high instead of competing fits the book''s cartel description.', 'TRUE — The book states cartels are usually illegal because competition laws favour customers.', 'TRUE — The book ties competition level directly to supplier numbers and substitute availability; fewer, larger suppliers means weaker competitive pressure than many small ones.'], '3/5', 11, 'full' ),
( '2.7', 'CASE 2.7.12', 'A campus print shop''s deadline monopoly and identical cafés', 'Next to a university''s only entrance gate, a single print shop offers the sole nearby printing and binding service for thesis submissions with a strict same-day deadline; the next-closest print shop is a forty-minute bus ride across town. Meanwhile, the town''s several cafés compete for student customers by offering nearly identical coffee and pastries at similar prices. Evaluate the statements using the book''s concepts of monopoly and perfect competition.', ARRAY['Because the print shop is the only nearby option for students needing same-day printing before a deadline, it holds a local monopoly-like position similar to the book''s theatre-bar or ski-hut examples.', 'The several cafés selling nearly identical coffee and pastries at similar prices could be described as approaching near-perfect competition more closely than as a monopoly.', 'Because a bus ride across town could technically reach another print shop, the campus print shop cannot be considered monopoly-like under any circumstances, according to the book.', 'A local monopoly-like supplier such as the print shop is, according to the book, a common and typical situation that most markets fall into.', 'The number of suppliers and the availability of substitutes both help determine the level of competition, and a same-day deadline effectively narrows students'' realistic substitutes down to just the one nearby shop.'], ARRAY[true, true, false, false, true], ARRAY['TRUE — Sole realistic supplier within a practical area matches the book''s local monopoly-like examples, such as the theatre bar or ski hut.', 'TRUE — Many sellers of a near-identical, similarly priced product fits the book''s near-perfect competition idea better than a monopoly does.', 'FALSE — The book allows local monopoly-like status despite a distant alternative existing, especially when time pressure makes that alternative impractical.', 'FALSE — The book describes monopoly, including local monopoly-like situations, as a comparatively rare situation, not the typical case.', 'TRUE — A binding deadline reduces the realistically usable substitutes to the one nearby shop, which is exactly the substitute-availability factor the book ties to competition level.'], '3/5', 12, 'full' ),
( '2.7', 'CASE 2.7.13', 'A standardised herring auction beside a secret-recipe restaurant', 'At a fishing harbour, each morning''s catch of a single standardised grade of herring is sold at auction to dozens of wholesale buyers, with the auctioneer calling out prices that everyone in the hall can hear and see displayed on a screen. A separate boutique seafood restaurant nearby has built a loyal following for a secret-recipe sauce that no other restaurant can replicate. Evaluate the statements using the book''s concepts of perfect competition, personal preference and oligopoly.', ARRAY['The herring auction''s combination of a standardised product, many buyers, and openly visible prices allows it to come closer to the book''s theoretical model of perfect competition than the boutique restaurant''s market does.', 'Because the boutique restaurant''s sauce recipe is secret, its market is, according to the book, automatically a monopoly over seafood in that entire region.', 'The herring auction, since it involves many buyers and sellers, should be classified by the book as an oligopoly.', 'Perfect competition, as defined in the book, is common in most everyday markets, including this fish harbour, without any exceptions.', 'A secret sauce recipe that creates customer loyalty has no relevance to the book''s concept of personal preference affecting competition level.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — A standardised good with many buyers and transparent prices matches the conditions the book lists for approaching perfect competition, unlike a differentiated, loyalty-driven product.', 'FALSE — A unique, protected recipe for one restaurant does not make it a monopolist over an entire region''s seafood market, since other restaurants and food options still exist regionally.', 'FALSE — Oligopoly in the book means few suppliers with large shares, the opposite of many buyers and sellers at an open auction.', 'FALSE — The book presents perfect competition as a rare, largely theoretical model, not something common across most everyday markets.', 'FALSE — A loyalty-inducing secret recipe is exactly the kind of personal-preference factor the book says reduces how replaceable a supplier''s goods are, and so weakens conditions for perfect competition.'], '5/5', 13, 'full' ),
( '2.7', 'CASE 2.7.14', 'Car makers who watch each other''s financing deals', 'The global market for new passenger cars is dominated by a limited number of large manufacturers, each holding a sizeable share of sales, and these manufacturers are known to watch each other''s pricing and financing offers closely before adjusting their own. In several countries, competition authorities have fined manufacturers in the past for secretly agreeing on component prices. Evaluate the statements using the book''s concepts of oligopoly and cartels.', ARRAY['A market with a limited number of large manufacturers, each holding a sizeable share, matches the book''s own example of car makers as a typical oligopoly.', 'Manufacturers closely watching and adjusting to each other''s pricing and financing offers illustrates the strong competitive reaction between rivals that the book associates with oligopoly.', 'Secretly agreeing on component prices, as some manufacturers were fined for, fits the book''s description of a cartel, which is usually treated as illegal.', 'Because car manufacturers negotiate financing deals with customers, the book classifies the car market as perfect competition rather than oligopoly.', 'The book explains that laws supporting competition exist because rivalry between suppliers, rather than secret coordination, is generally considered better for customers.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — The book names car makers directly alongside telecoms as a typical oligopoly example.', 'TRUE — Closely watching and reacting to rivals'' offers is the strong reactive rivalry the book links to oligopoly.', 'TRUE — Secretly agreeing on prices instead of competing matches the book''s cartel description, usually illegal.', 'FALSE — Offering financing deals to customers has no bearing on the market''s classification; a limited number of large, share-holding manufacturers remains an oligopoly, not perfect competition.', 'TRUE — The book states competition laws exist because open rivalry, not secret coordination, is generally better for customers.'], '3/5', 14, 'full' ),
( '2.7', 'CASE 2.7.15', 'A lone island ferry and five rival coastal bus lines', 'A small island off the coast is served by a single ferry company, which operates the only scheduled crossing to the mainland; a private helicopter charter also flies passengers over, but at a price most islanders cannot afford for daily use. On the mainland, five competing bus companies run parallel routes along the coastal highway and frequently adjust timetables to attract passengers. Evaluate the statements using the book''s concepts of monopoly, oligopoly and cartels.', ARRAY['The ferry company''s role as sole scheduled operator to the island fits the book''s description of a local monopoly-like supplier, even though a costly helicopter alternative technically exists.', 'Because a helicopter charter is technically available, the ferry company faces exactly the same level of competition as a mainland bus company operating alongside four rivals.', 'Five competing bus companies adjusting timetables to attract passengers is closer to a competitive market than to a monopoly, since here multiple suppliers are actively vying for the same customers.', 'According to the book, a single supplier automatically qualifies as an illegal cartel, since cartels are defined as any market with only one seller.', 'The five bus companies would only be described as an oligopoly if they were also secretly fixing prices together; without such an agreement, the book says they cannot be considered an oligopoly under any circumstances.'], ARRAY[true, false, true, false, false], ARRAY['TRUE — Being the sole scheduled, realistically affordable operator fits the book''s local monopoly-like idea, since an unaffordable niche alternative barely changes ordinary islanders'' options.', 'FALSE — An unaffordable niche substitute does not equalise competition with a market that has several actively competing suppliers; substitute availability matters, but only if it is a realistic option.', 'TRUE — Multiple suppliers actively competing for the same customers is closer to a competitive market than to monopoly.', 'FALSE — A cartel requires multiple suppliers agreeing together instead of competing; a single seller is a monopoly, not a cartel.', 'FALSE — Oligopoly classification in the book depends on having few suppliers with large shares, not on whether they have secretly agreed on prices; secret price-fixing would instead make them a cartel, a separate concept.'], '4/5', 15, 'full' ),
( '2.7', 'CASE 2.7.16', 'Cement producers and a proposed territory-sharing scheme', 'In a large country, the market for cement is supplied by a small number of large manufacturers, each controlling a substantial regional share, and construction companies report that these manufacturers'' prices tend to move together shortly after any one of them announces a change. A parliamentary inquiry once examined whether manufacturers had divided the country into exclusive sales territories instead of competing across the whole market. Evaluate the statements using the book''s concepts of oligopoly, cartels and competition level.', ARRAY['A small number of large manufacturers each controlling a substantial share matches the book''s definition of an oligopoly.', 'Prices moving together shortly after one manufacturer''s announcement illustrates the strong reaction to rivals'' behaviour that the book links to oligopolistic markets.', 'If manufacturers had actually divided the country into exclusive sales territories instead of competing, that arrangement would fit the book''s description of a cartel, generally regarded as illegal.', 'The book explains competition level as depending on the number of suppliers and the availability of substitutes, and cement being difficult to substitute for large construction projects further limits competitive pressure in this market.', 'Laws supporting competition exist, per the book, because rivalry between suppliers rather than secretly dividing markets is generally seen as better for customers.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Few large suppliers each with a substantial regional share is the book''s oligopoly definition.', 'TRUE — Prices moving together right after one firm''s announcement is the reactive rivalry pattern the book links to oligopoly.', 'TRUE — Dividing territories instead of competing matches the book''s cartel description, generally illegal.', 'TRUE — The book ties competition level to supplier numbers and substitute availability; a hard-to-substitute material limits competitive pressure further.', 'TRUE — The book states competition laws exist because rivalry, not market-sharing agreements, benefits customers.'], '3/5', 16, 'full' ),
( '2.7', 'CASE 2.7.17', 'The opera house''s only intermission bar', 'Inside a small city''s only opera house, a single bar has the exclusive right to sell drinks during intermissions, since no outside vendors are permitted inside the building; ticket holders wishing to buy a drink elsewhere would have to leave and miss part of the performance. Outside the building, several unrelated cafés compete for the same theatregoers before and after shows. Evaluate the statements using the book''s concepts of monopoly and perfect competition.', ARRAY['The intermission bar''s exclusive position inside the opera house matches the book''s own theatre-bar example of a local, monopoly-like supplier.', 'Because ticket holders would have to leave and miss part of the performance to buy a drink elsewhere, the intermission bar faces meaningfully less competitive pressure than the cafés outside, which theatregoers can freely choose between.', 'The several unrelated cafés outside the opera house competing for the same theatregoers automatically meet every theoretical requirement of perfect competition, including full information and no personal preferences.', 'This kind of exclusive-vendor arrangement inside a single venue shows how competition level can vary even within a small local area, not just across whole national markets.', 'Since only one bar operates inside the opera house, competition authorities would automatically classify this arrangement as an illegal cartel.'], ARRAY[true, true, false, true, false], ARRAY['TRUE — This is precisely the book''s theatre-bar example of an exclusive, local monopoly-like supplier.', 'TRUE — The practical cost of leaving and missing the performance sharply limits realistic substitutes, which is exactly the substitute-availability factor behind weaker competition.', 'FALSE — Real cafés with differentiated menus and loyal regulars rarely meet every strict theoretical condition for perfect competition; the claim of automatically satisfying all conditions overstates it.', 'TRUE — Competition level, per the book, depends on supplier numbers and substitutes in a given market, which can be assessed locally (a single venue) as well as nationally.', 'FALSE — A single exclusive supplier is a monopoly-like situation, not a cartel, since a cartel requires multiple suppliers agreeing together instead of competing.'], '4/5', 17, 'full' ),
( '2.7', 'CASE 2.7.18', 'Free-entry organic egg stalls beside a patented cheese process', 'In a farming region, dozens of small family farms sell organic eggs of a similar certified grade at a weekly regional market, with prices posted on a shared board and new farms free to join the market each season without special permission. A separate specialty cheese producer nearby has patented a unique aging process that no other producer in the country is legally allowed to copy. Evaluate the statements using the book''s concepts of perfect competition and entry barriers.', ARRAY['The organic egg market''s combination of many small sellers, a similar certified grade, openly posted prices, and free entry each season brings it closer to the book''s theoretical model of perfect competition than most real markets manage.', 'Because the cheese producer''s aging process is patented, the book would describe that cheese market as a perfectly competitive market with full information for all producers.', 'Dozens of small egg farms selling at the same market automatically makes this an oligopoly according to the book''s definition.', 'Since new farms are free to join the egg market each season, this proves the market has strong personal preference among buyers, which the book requires for perfect competition.', 'A patented, legally protected production process is, according to the book, irrelevant to how easily new suppliers can enter a market.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Many sellers, a similar standardised grade, transparent prices, and free entry are exactly the conditions the book lists for approaching perfect competition.', 'FALSE — A patent that legally blocks others from copying a process is an entry barrier, the opposite of the no-barriers condition perfect competition requires.', 'FALSE — Oligopoly in the book means few suppliers with large market shares, not dozens of small, similarly sized sellers.', 'FALSE — The book requires the absence of personal preference, not its presence, for perfect competition; free entry relates to entry barriers, not to personal preference.', 'FALSE — A legal patent is a clear example of an entry barrier and is directly relevant to how freely new suppliers can enter a market.'], '5/5', 18, 'full' ),
( '2.7', 'CASE 2.7.19', 'Two ride-hailing apps and a fare-fixing suspicion', 'In a capital city, two ride-hailing apps together handle the vast majority of app-based rides, and drivers notice that when one app raises its commission or lowers driver pay, the other often follows within a short period. City regulators have investigated whether the two apps ever quietly agreed on minimum fares instead of undercutting each other to attract riders. Evaluate the statements using the book''s concepts of oligopoly, cartels and perfect competition.', ARRAY['Two apps together handling the vast majority of rides, each therefore holding a large share, fits the book''s description of an oligopoly.', 'Drivers observing that one app''s commission or pay changes are often followed by the other within a short period illustrates the strong reaction between rivals that the book links to oligopolistic markets.', 'If regulators confirmed the two apps had quietly agreed on minimum fares instead of competing, that would match the book''s description of a cartel, usually treated as illegal.', 'Because only two apps operate, this market automatically satisfies the book''s requirement of many buyers and sellers needed for perfect competition.', 'The book''s point that laws support competition because it benefits customers applies directly to why regulators would object to the two apps secretly agreeing on fares rather than competing.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — Two suppliers with large combined shares matches the book''s oligopoly definition of few suppliers with large shares.', 'TRUE — One app''s changes being followed by the other quickly is the reactive rivalry the book associates with oligopoly.', 'TRUE — Quietly agreeing on fares instead of competing fits the book''s cartel description, usually illegal.', 'FALSE — Two suppliers is far from the ''many'' required by perfect competition, where no single player can influence price; two large apps clearly can.', 'TRUE — The book explains that competition laws exist because rivalry, not secret agreements, is generally better for customers.'], '3/5', 19, 'full' ),
( '2.7', 'CASE 2.7.20', 'A global gold exchange beside a custom-ring jeweller', 'On an international bullion exchange, gold of a certified standard purity is bought and sold by thousands of traders worldwide, with live prices visible to anyone with a market data feed, and virtually any accredited firm can begin trading with minimal restriction. A separate small-town jeweller sells custom engagement rings that each customer designs individually with the jeweller over several consultations. Evaluate the statements using the book''s concepts of perfect competition and personal preference.', ARRAY['The gold exchange''s combination of a standardised product, very many traders, and widely visible live prices brings it closer to the book''s theoretical model of perfect competition than the custom jewellery market does.', 'Because gold trading involves thousands of participants, the book would classify this exchange as an oligopoly rather than as an example approaching perfect competition.', 'The custom-designed engagement rings, shaped individually with each customer, illustrate the personal-preference and non-replaceable-goods element that the book says works against a market being perfectly competitive.', 'Since perfect competition is only theoretical, the book states that no real commodity market, including this gold exchange, can ever come close to resembling it.', 'A small-town jeweller designing custom rings is, according to the book, automatically in the same competitive category as thousands of anonymous gold traders, since both simply sell physical goods to customers.'], ARRAY[true, false, true, false, false], ARRAY['TRUE — A standardised good, very many traders, and transparent live prices match the book''s conditions for approaching perfect competition.', 'FALSE — Oligopoly in the book means few suppliers with large shares, the opposite of thousands of participating traders.', 'TRUE — Individually designed, non-substitutable rings are exactly the personal-preference factor the book says prevents a market from being perfectly competitive.', 'FALSE — The book allows that near-identical, standardised goods such as certified-purity gold can come close to perfect competition, even though it remains a theoretical ideal rarely met exactly.', 'FALSE — Highly differentiated, individually designed goods sit in a very different competitive category from a standardised, widely traded commodity; the two are not automatically comparable.'], '4/5', 20, 'full' )
